// Live Cross-tab Storage Synchronisatie met Vragenlijst (gedebounced, geen focus loop)
var __storageSyncTimer = null;
if (typeof window !== 'undefined') {
  window.addEventListener('storage', function(e) {
    if (window.__isSyncingQuestionnaire) return;
    if (e.key === 'interflon_questionnaire_full_data' || e.key === 'interflon_last_questionnaire_data') {
      if (window.__lastDossierImportTime && (Date.now() - window.__lastDossierImportTime < 15000)) {
        return;
      }
      clearTimeout(__storageSyncTimer);
      __storageSyncTimer = setTimeout(function() {
        try {
          const data = e.newValue ? JSON.parse(e.newValue) : null;
          if (!data) return;
          const activeCalcMachine = (
            (document.getElementById('techMachineInput') && document.getElementById('techMachineInput').value) ||
            (document.getElementById('omTechMachine') && document.getElementById('omTechMachine').value) ||
            window.__activeDossierMachine ||
            localStorage.getItem('interflon_active_dossier_machine') ||
            localStorage.getItem('tech_machine') || ''
          ).trim().toLowerCase();
          const incMachine = (
            (data.general && (data.general.machineName || data.general.name)) ||
            data.machineName ||
            (data.surveyRasterConfig && data.surveyRasterConfig.machineName) ||
            ''
          ).trim().toLowerCase();
          if (activeCalcMachine && incMachine && activeCalcMachine !== incMachine) {
            console.warn(`Ignoring storage update for '${incMachine}' because active calculator machine is '${activeCalcMachine}'`);
            return;
          }
          if (activeCalcMachine && !incMachine) {
            console.warn(`Ignoring storage update with missing machine name because active calculator machine is '${activeCalcMachine}'`);
            return;
          }
          if (typeof syncAllQuestionnaireDataToCalculator === 'function') {
            const curL = window.currentActiveSurveyBearingLetter || localStorage.getItem("interflon_active_survey_letter") || null;
            syncAllQuestionnaireDataToCalculator(data, curL);
          }
        } catch(err) {}
      }, 200);
    }
  });
}

// Cross-tab BroadcastChannel listener for questionnaire synchronization
try {
  if (typeof BroadcastChannel !== 'undefined') {
    if (!window.__surveySyncBroadcastChannel) {
      window.__surveySyncBroadcastChannel = new BroadcastChannel('interflon_questionnaire_sync');
    }
    const surveyChannel = window.__surveySyncBroadcastChannel;
    surveyChannel.onmessage = function(ev) {
      if (!ev.data) return;
      // Ignore own broadcast echo from calculator import
      if (ev.data.source === 'calculator_dossier_import') return;

      const incomingData = ev.data.fullData || ev.data.data || ev.data.config;
      const activeCalcMachine = (
        (document.getElementById('techMachineInput') && document.getElementById('techMachineInput').value) ||
        (document.getElementById('omTechMachine') && document.getElementById('omTechMachine').value) ||
        window.__activeDossierMachine ||
        localStorage.getItem('interflon_active_dossier_machine') ||
        localStorage.getItem('tech_machine') || ''
      ).trim().toLowerCase();
      const incMachine = (
        (incomingData && incomingData.general && (incomingData.general.machineName || incomingData.general.name)) ||
        (incomingData && incomingData.machineName) ||
        (ev.data.config && ev.data.config.machineName) ||
        (ev.data.config && ev.data.config.general && (ev.data.config.general.machineName || ev.data.config.general.name)) ||
        (ev.data.data && ev.data.data.general && (ev.data.data.general.machineName || ev.data.data.general.name)) ||
        ''
      ).trim().toLowerCase();

      // Strict rejection: if calculator machine is known and incoming message has a different machine name, drop it!
      if (activeCalcMachine && incMachine && activeCalcMachine !== incMachine) {
        console.warn(`Ignoring incoming cross-tab survey for '${incMachine}' because active calculator machine is '${activeCalcMachine}'`);
        return;
      }
      if (activeCalcMachine && !incMachine) {
        console.warn(`Ignoring incoming cross-tab survey with missing machine name because active calculator machine is '${activeCalcMachine}'`);
        return;
      }

      // If we recently imported a dossier (within 60 seconds), ignore incoming cross-tab messages to protect imported data
      if (window.__lastDossierImportTime && (Date.now() - window.__lastDossierImportTime < 60000)) {
        if (ev.data.source !== 'vragenlijst_user_import') {
          console.log("Ignoring cross-tab survey message right after dossier import to protect imported data");
          return;
        }
      }
      if (ev.data.type === 'SURVEY_BEARINGS_RESPONSE' || ev.data.type === 'QUESTIONNAIRE_IMPORTED' || ev.data.type === 'CONFIG_UPDATED') {
        console.log("Vragenlijst update ontvangen:", ev.data.type);
        const incomingData = ev.data.fullData || ev.data.data || ev.data.config;
        if (incomingData && typeof incomingData === 'object') {
          window.latestSurveyFullData = incomingData;
        }
        const bearings = (Array.isArray(ev.data.bearings) && ev.data.bearings.length > 0)
          ? ev.data.bearings
          : (incomingData && Array.isArray(incomingData.bearings) && incomingData.bearings.length > 0)
            ? incomingData.bearings
            : null;

        if (bearings && bearings.length > 0) {
          window.latestSurveyBearings = bearings;
          try {
            // Only update interflon_questionnaire_full_data if ev.data is a QUESTIONNAIRE_IMPORTED event
            // Do NOT re-save questionnaire full data on CONFIG_UPDATED to avoid cross-tab storage echo loops with vragenlijst.html!
            if (ev.data.type === 'QUESTIONNAIRE_IMPORTED' && (ev.data.fullData || ev.data.data)) {
              const importedData = ev.data.fullData || ev.data.data;
              localStorage.setItem('interflon_questionnaire_full_data', JSON.stringify(importedData));
              localStorage.setItem('interflon_last_questionnaire_data', JSON.stringify(importedData));
            }

            let rasterCfg = {};
            try { rasterCfg = JSON.parse(localStorage.getItem('interflon_survey_raster_config') || '{}'); } catch(e){}
            rasterCfg.bearings = bearings;
            localStorage.setItem('interflon_survey_raster_config', JSON.stringify(rasterCfg));
          } catch(e) {}

          populateSurveyBearingsDropdown(bearings);
        } else if (typeof refreshSurveyBearingsList === 'function') {
          refreshSurveyBearingsList(false);
        }
        // Cache latest survey raster config in localStorage without automatically applying it to Automatisering.
        // Automatisering import must ONLY occur when the user explicitly clicks the import button.
        const latestConfig = ev.data.config || (incomingData && incomingData.surveyRasterConfig);
        if (latestConfig) {
          try {
            localStorage.setItem('interflon_survey_raster_config', JSON.stringify(latestConfig));
          } catch(e) {}
        }
        if (typeof syncAllQuestionnaireDataToCalculator === 'function') {
          const curL = window.currentActiveSurveyBearingLetter || localStorage.getItem("interflon_active_survey_letter") || null;
          syncAllQuestionnaireDataToCalculator(incomingData, curL);
        }
      }
    };
  }
} catch (e) {}

