/* ==========================================================================
   INTERACTIVE AI AVATAR SPEECH CONTROLLER (MICPOL - INTERFLON SPECIALIST)
   ========================================================================== */
let isRoiAvatarSpeaking = false;
let roiSpeechQueue = [];
let roiSpeechVoices = [];

function numberToDutchWords(n) {
  n = Math.round(Math.abs(n));
  if (n === 0) return 'nul';

  const eenheden = ['', 'een', 'twee', 'drie', 'vier', 'vijf', 'zes', 'zeven', 'acht', 'negen',
    'tien', 'elf', 'twaalf', 'dertien', 'veertien', 'vijftien', 'zestien', 'zeventien', 'achttien', 'negentien'];
  const tientallen = ['', '', 'twintig', 'dertig', 'veertig', 'vijftig', 'zestig', 'zeventig', 'tachtig', 'negentig'];

  function onder100(num) {
    if (num === 0) return '';
    if (num < 20) return eenheden[num];
    const t = Math.floor(num / 10);
    const e = num % 10;
    if (e === 0) return tientallen[t];
    const voegwoord = (e === 2 || e === 3) ? 'ën' : 'en';
    return eenheden[e] + voegwoord + tientallen[t];
  }

  function onder1000(num) {
    if (num === 0) return '';
    const h = Math.floor(num / 100);
    const rest = num % 100;
    let res = '';
    if (h === 1) {
      res = 'honderd';
    } else if (h > 1) {
      res = eenheden[h] + 'honderd';
    }
    if (rest > 0) {
      if (res) {
        res += onder100(rest);
      } else {
        res = onder100(rest);
      }
    }
    return res;
  }

  function convert(num) {
    if (num === 0) return '';
    let str = '';
    const m = Math.floor(num / 1000000);
    let rest = num % 1000000;
    if (m > 0) {
      str += (m === 1 ? 'een miljoen ' : convert(m) + ' miljoen ');
    }
    const d = Math.floor(rest / 1000);
    rest = rest % 1000;
    if (d > 0) {
      if (d === 1) {
        str += 'duizend ';
      } else {
        str += onder1000(d) + 'duizend ';
      }
    }
    if (rest > 0) {
      str += onder1000(rest);
    }
    return str.trim();
  }

  return convert(n);
}

function sanitizeDeviceNameForSpeech(name, lang) {
  if (!name) return "";
  let clean = name;
  if (lang === "nl" || !lang) {
    clean = clean.replace(/\s*\+\s*/g, ' en ');
    const dutchNumWords = ['', 'één', 'twee', 'drie', 'vier', 'vijf', 'zes', 'zeven', 'acht', 'negen', 'tien'];
    clean = clean.replace(/(\d+)\s*[xX]\b/g, (match, p1) => {
      const n = parseInt(p1, 10);
      const w = (n >= 1 && n <= 10) ? dutchNumWords[n] : p1;
      return `${w} maal `;
    });
  } else if (lang === "fr") {
    clean = clean.replace(/\s*\+\s*/g, ' et ');
    clean = clean.replace(/(\d+)\s*[xX]\b/g, '$1 fois ');
  } else if (lang === "en") {
    clean = clean.replace(/\s*\+\s*/g, ' and ');
    clean = clean.replace(/(\d+)\s*[xX]\b/g, '$1 times ');
  }
  return clean.replace(/\s+/g, ' ').trim();
}

function initRoiAvatarVoices() {
  if (typeof window !== "undefined" && "speechSynthesis" in window) {
    roiSpeechVoices = window.speechSynthesis.getVoices();
    if (window.speechSynthesis.onvoiceschanged !== undefined) {
      window.speechSynthesis.onvoiceschanged = () => {
        roiSpeechVoices = window.speechSynthesis.getVoices();
      };
    }
  }
}
initRoiAvatarVoices();

function getBestVoiceForLang(langCode) {
  if (!roiSpeechVoices || roiSpeechVoices.length === 0) {
    if (typeof window !== "undefined" && "speechSynthesis" in window) {
      roiSpeechVoices = window.speechSynthesis.getVoices();
    }
  }
  if (!roiSpeechVoices || roiSpeechVoices.length === 0) return null;

  const targetLang = (langCode || "nl").toLowerCase();
  let filtered = [];

  if (targetLang === "fr") {
    filtered = roiSpeechVoices.filter(v => v.lang && v.lang.toLowerCase().startsWith("fr"));
  } else if (targetLang === "en") {
    filtered = roiSpeechVoices.filter(v => v.lang && v.lang.toLowerCase().startsWith("en"));
  } else {
    // Nederlands
    filtered = roiSpeechVoices.filter(v => v.lang && (v.lang.toLowerCase().startsWith("nl") || v.lang.toLowerCase().includes("dutch")));
  }

  if (filtered.length === 0) {
    filtered = roiSpeechVoices.filter(v => v.lang && v.lang.toLowerCase().startsWith("nl"));
  }
  if (filtered.length === 0) return null;

  // 1. Zoek naar 'Natural', 'Neural' of 'Online' vrouwelijke stemmen (Edge / Chrome)
  const naturalFemale = filtered.find(v => {
    const name = v.name.toLowerCase();
    const isNatural = name.includes("natural") || name.includes("online") || name.includes("neural") || name.includes("google");
    const isFemale = name.includes("colette") || name.includes("fenna") || name.includes("dena") || name.includes("fleur") || 
                     name.includes("denise") || name.includes("brigitte") || name.includes("hortense") || name.includes("jenny") ||
                     name.includes("female") || name.includes("vrouw");
    return isNatural && isFemale;
  });
  if (naturalFemale) return naturalFemale;

  // 2. Zoek naar 'Natural' / 'Google' stemmen algemeen
  const naturalAny = filtered.find(v => {
    const name = v.name.toLowerCase();
    return name.includes("natural") || name.includes("online") || name.includes("google") || name.includes("neural");
  });
  if (naturalAny) return naturalAny;

  // 3. Zoek naar vrouwelijke stem
  const femaleAny = filtered.find(v => {
    const name = v.name.toLowerCase();
    return name.includes("colette") || name.includes("fenna") || name.includes("dena") || name.includes("fleur") ||
           name.includes("female") || name.includes("vrouw");
  });
  if (femaleAny) return femaleAny;

  // 4. Eerste beschikbare stem
  return filtered[0];
}

function setRoiAvatarUiState(speaking) {
  isRoiAvatarSpeaking = speaking;
  const container = document.getElementById("roiAvatarContainer");
  const statusText = document.getElementById("roiAvatarStatusText");
  const icon = document.getElementById("roiAvatarIcon");
  const stopBtn = document.getElementById("roiAvatarStopBtn");
  const lang = typeof currentLang !== "undefined" ? currentLang : "nl";

  if (container) {
    if (speaking) {
      container.classList.add("speaking");
    } else {
      container.classList.remove("speaking");
    }
  }
  if (statusText) {
    if (speaking) {
      statusText.textContent = lang === "fr" ? "En cours d'explication..." : (lang === "en" ? "Explaining..." : "Aan het toelichten...");
    } else {
      statusText.textContent = lang === "fr" ? "Écouter l'analyse" : (lang === "en" ? "Listen to summary" : "Toelichting beluisteren");
    }
  }
  if (icon) {
    icon.textContent = speaking ? "🔊" : "▶";
  }
  if (stopBtn) {
    stopBtn.style.display = speaking ? "inline-flex" : "none";
  }
}

function stopRoiAvatarSpeech() {
  roiSpeechQueue = [];
  if (typeof window !== "undefined" && "speechSynthesis" in window) {
    try {
      window.speechSynthesis.cancel();
    } catch (e) {
      console.warn("Fout bij annuleren van spraak:", e);
    }
  }
  setRoiAvatarUiState(false);
}

function generateRoiSpeechScript() {
  const getCleanVal = (id) => {
    const el = document.getElementById(id);
    if (!el) return "";
    return (el.innerText || el.textContent || "").trim();
  };

  const parseNumFromText = (txt) => {
    if (!txt) return 0;
    const cleaned = txt.replace(/[^0-9,-]/g, '').replace(',', '.');
    const v = parseFloat(cleaned);
    return isNaN(v) ? 0 : v;
  };

  const lang = typeof currentLang !== "undefined" ? currentLang : "nl";

  const rawNetYearly = getCleanVal("roiNetYearlySaving");
  const rawYear1 = getCleanVal("roiYear1NetResult");
  const rawPayback = getCleanVal("roiPaybackPeriod");
  const rawMultiYear = getCleanVal("roiMultiYearSaving");
  const yearsInput = document.getElementById("roiYearsInput");
  const numYears = yearsInput ? (parseInt(yearsInput.value, 10) || 5) : 5;

  const netYearlyNum = parseNumFromText(rawNetYearly);
  const year1Num = parseNumFromText(rawYear1);
  const multiYearNum = parseNumFromText(rawMultiYear);

  const rawDeviceName = getCleanVal("roiAutoDeviceName") || (lang === "fr" ? "le graissage automatique Interflon" : (lang === "en" ? "Interflon automatic lubrication" : "automatische Interflon smering"));
  const deviceName = sanitizeDeviceNameForSpeech(rawDeviceName, lang);

  let bearingCount = 0;
  if (typeof autoSelectedBearings !== "undefined" && Array.isArray(autoSelectedBearings) && autoSelectedBearings.length > 0) {
    bearingCount = autoSelectedBearings.length;
  } else if (typeof bearingsData !== "undefined" && Array.isArray(bearingsData) && bearingsData.length > 0) {
    bearingCount = bearingsData.length;
  }

  const formatEuro = (amount) => {
    const rounded = Math.round(Math.abs(amount));
    if (rounded === 0) return "nul euro";
    if (lang === "nl") {
      return numberToDutchWords(rounded) + " euro";
    }
    const loc = lang === "fr" ? "fr-FR" : "en-US";
    const suffix = lang === "en" ? "euros" : "euro";
    return rounded.toLocaleString(loc) + " " + suffix;
  };

  if (lang === "fr") {
    const ptTxt = bearingCount > 1 ? `pour les ${bearingCount} points de lubrification` : "pour votre installation";
    let script = `Bienvenue. Permettez-moi de vous présenter les résultats de ce calcul financier ${ptTxt}. `;
    script += `Dans la pratique manuelle actuelle, vos techniciens effectuent des tournées régulières de graissage, ce qui mobilise des heures précieuses et présente des risques de surdosage ou d'oubli de points. `;
    script += `En adoptant ${deviceName}, vos roulements bénéficient d'un apport continu et extrêmement précis. Notre technologie exclusive MicPol assure un film lubrifiant ininterrompu et réduit drastiquement les frottements. `;
    script += `Sur le plan financier, l'analyse démontre une rentabilité immédiate. `;
    if (year1Num >= 0) {
      script += `Dès la première année, vous réalisez une économie nette de ${formatEuro(year1Num)}, coût d'acquisition et installation complète inclus. `;
    } else {
      script += `La première année nécessite un investissement initial net de ${formatEuro(Math.abs(year1Num))}. `;
    }
    if (netYearlyNum > 0) {
      script += `À partir de la deuxième année, votre gain structurel annuel s'élève à ${formatEuro(netYearlyNum)}. `;
    }
    if (rawPayback.toLowerCase().includes("direct")) {
      script += `L'investissement est immédiatement rentable dès le premier jour. `;
    } else {
      const pClean = rawPayback.split("(")[0].trim();
      if (pClean) script += `Le délai d'amortissement est particulièrement rapide avec seulement ${pClean}. `;
    }
    if (multiYearNum > 0) {
      script += `Sur une durée de ${numYears} ans, votre économie nette cumulée atteint plus de ${formatEuro(multiYearNum)}. `;
    }
    script += `Enfin, le gain opérationnel majeur réside dans une fiabilité accrue : moins d'usure, baisse des coûts de révision et suppression des arrêts de production non planifiés.`;
    return script;
  }

  if (lang === "en") {
    const ptTxt = bearingCount > 1 ? `for the ${bearingCount} lubrication points` : "for your application";
    let script = `Welcome. I would be pleased to present the results of this financial calculation ${ptTxt}. `;
    script += `In your current manual practice, technicians perform periodic greasing rounds. This requires valuable labor hours and carries risks of over-lubrication or missed lubrication points. `;
    script += `By switching to ${deviceName}, your bearings receive continuous and precisely metered lubrication. Our MicPol technology guarantees an unbroken protective lubricating film and drastically reduces friction. `;
    script += `Looking at the financial return, the business case is compelling. `;
    if (year1Num >= 0) {
      script += `In year one, you achieve a net saving of ${formatEuro(year1Num)}, fully covering the equipment purchase. `;
    } else {
      script += `In year one, the initial net investment is ${formatEuro(Math.abs(year1Num))}. `;
    }
    if (netYearlyNum > 0) {
      script += `From year two onwards, your structural annual savings amount to ${formatEuro(netYearlyNum)} per year. `;
    }
    if (rawPayback.toLowerCase().includes("direct") || rawPayback.toLowerCase().includes("immediately")) {
      script += `The investment is profitable immediately from day one. `;
    } else {
      const pClean = rawPayback.split("(")[0].trim();
      if (pClean) script += `The payback period is exceptionally short at just ${pClean}. `;
    }
    if (multiYearNum > 0) {
      script += `Over a ${numYears}-year period, your cumulative net savings will exceed ${formatEuro(multiYearNum)}. `;
    }
    script += `In addition, the greatest practical benefit comes from maximum reliability: longer component life, reduced overhaul costs, and avoidance of unplanned production downtime.`;
    return script;
  }

  // Standaard: Nederlands
  const bearingPhrase = bearingCount > 1 ? `voor de ${bearingCount} aangesloten smeerpunten` : (bearingCount === 1 ? "voor dit smeerpunt" : "voor uw smeerpunten");

  let script = `Welkom. Graag licht ik de resultaten van deze berekening toe ${bearingPhrase}. `;
  script += `In de huidige handmatige praktijk voeren uw medewerkers periodiek smeerrondes uit. Dit vraagt kostbare arbeidsuren en brengt risico's met zich mee op vergeten smeerpunten of overmatige vetdosering. `;
  script += `Door over te stappen op ${deviceName} worden uw lagers volautomatisch en continu voorzien van de exact benodigde hoeveelheid smeermiddel. Onze hoogwaardige MicPol-technologie garandeert een ononderbroken beschermende smeerfilm en verlaagt de wrijving drastisch. `;
  script += `Kijken we naar het financiële resultaat, dan levert dit direct een overtuigende businesscase op. `;

  if (year1Num >= 0) {
    script += `In het eerste jaar realiseert u een directe nettobesparing van ${formatEuro(year1Num)}, waarbij de aanschaf van de hardware al volledig is verrekend. `;
  } else {
    script += `In het eerste jaar vraagt de initiële investering een netto inzet van ${formatEuro(Math.abs(year1Num))}. `;
  }

  if (netYearlyNum > 0) {
    script += `Vanaf het tweede jaar bespaart u structureel ${formatEuro(netYearlyNum)} per jaar aan vermeden arbeid en smeermiddel. `;
  }

  if (rawPayback.toLowerCase().includes("direct")) {
    script += `De investering is direct vanaf dag één rendabel. `;
  } else {
    let paybackClean = rawPayback.split("(")[0].trim();
    paybackClean = paybackClean.replace(/(\d+),(\d+)/, "$1 komma $2");
    if (paybackClean) {
      script += `De totale investering heeft een bijzonder snelle terugverdientijd van slechts ${paybackClean}. `;
    }
  }

  if (multiYearNum > 0) {
    script += `Over een periode van ${numYears} jaar loopt uw totale nettobesparing op tot ${formatEuro(multiYearNum)}. `;
  }

  script += `Bovendien ontstaat het grootste voordeel in de praktijk door maximale bedrijfszekerheid: minder lagerschade, lagere revisiekosten en het vermijden van ongeplande machinestilstand.`;

  return script;
}

function speakNextRoiSentence(voice) {
  if (!isRoiAvatarSpeaking || roiSpeechQueue.length === 0) {
    setRoiAvatarUiState(false);
    return;
  }

  const sentence = roiSpeechQueue.shift();
  if (!sentence || !sentence.trim()) {
    speakNextRoiSentence(voice);
    return;
  }

  const lang = typeof currentLang !== "undefined" ? currentLang : "nl";
  const utter = new SpeechSynthesisUtterance(sentence.trim());
  utter.lang = lang === "fr" ? "fr-FR" : (lang === "en" ? "en-US" : "nl-NL");
  utter.rate = 0.98;
  utter.pitch = 1.05;
  if (voice) utter.voice = voice;

  utter.onend = () => {
    if (isRoiAvatarSpeaking && roiSpeechQueue.length > 0) {
      speakNextRoiSentence(voice);
    } else {
      setRoiAvatarUiState(false);
    }
  };

  utter.onerror = (e) => {
    console.warn("Spraakfout:", e);
    setRoiAvatarUiState(false);
  };

  window.speechSynthesis.speak(utter);
}

function toggleRoiAvatarSpeech() {
  if (isRoiAvatarSpeaking) {
    stopRoiAvatarSpeech();
    return;
  }

  if (typeof window === "undefined" || !("speechSynthesis" in window)) {
    alert("Uw browser ondersteunt helaas geen spraaksynthese (Web Speech API). Probeer Google Chrome of Microsoft Edge.");
    return;
  }

  // Annuleer eventuele actieve spraak
  window.speechSynthesis.cancel();

  if (typeof stopAutoAvatarSpeech === "function") {
    stopAutoAvatarSpeech();
  }

  const script = generateRoiSpeechScript();
  if (!script || !script.trim()) return;

  // Split in afzonderlijke zinnen voor continue vloeiendheid zonder browser-timeouts
  roiSpeechQueue = script.split(/(?<=[.?!])\s+/).filter(s => s.trim().length > 0);
  if (roiSpeechQueue.length === 0) return;

  const lang = typeof currentLang !== "undefined" ? currentLang : "nl";
  const voice = getBestVoiceForLang(lang);

  setRoiAvatarUiState(true);

  if (window.speechSynthesis.paused) {
    window.speechSynthesis.resume();
  }

  speakNextRoiSentence(voice);
}

// Zorg dat spraak stopt bij sluiten of verlaten van pagina
if (typeof window !== "undefined") {
  window.addEventListener("beforeunload", () => {
    stopRoiAvatarSpeech();
    stopAutoAvatarSpeech();
  });
}

// ==========================================================================
// AUTOMATISERING AI AVATAR SPEECH SYNTHESIS (MICPOL)
// ==========================================================================
let isAutoAvatarSpeaking = false;
let autoSpeechQueue = [];
let activeAutoUtterance = null;

function setAutoAvatarUiState(speaking) {
  isAutoAvatarSpeaking = speaking;
  const container = document.getElementById("autoAvatarContainer");
  const icon = document.getElementById("autoAvatarIcon");
  const statusText = document.getElementById("autoAvatarStatusText");
  const stopBtn = document.getElementById("autoAvatarStopBtn");

  if (container) {
    if (speaking) {
      container.classList.add("speaking");
    } else {
      container.classList.remove("speaking");
    }
  }

  if (icon) {
    icon.textContent = speaking ? "🔊" : "▶";
  }

  if (statusText) {
    statusText.textContent = speaking ? "Aan het woord... (klik om te stoppen)" : "Toelichting configuratie beluisteren";
  }

  if (stopBtn) {
    stopBtn.style.display = speaking ? "inline-flex" : "none";
  }
}

function stopAutoAvatarSpeech() {
  if (typeof window !== "undefined" && "speechSynthesis" in window) {
    window.speechSynthesis.cancel();
  }
  activeAutoUtterance = null;
  autoSpeechQueue = [];
  setAutoAvatarUiState(false);
}
window.stopAutoAvatarSpeech = stopAutoAvatarSpeech;

function formatDecForDutchSpeech(val) {
  const num = (typeof val === 'number') ? val : (parseFloat(val) || 0);
  const fixed = num.toFixed(2).replace('.', ',');
  const parts = fixed.split(',');
  const wholeVal = parseInt(parts[0], 10);
  const fracVal = parseInt(parts[1], 10);
  const wholeWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(wholeVal) : wholeVal.toString();
  const fracWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(fracVal) : fracVal.toString();
  return `${wholeWord} komma ${fracWord}`;
}

function generateAutomationSpeechScript() {
  const lang = typeof currentLang !== "undefined" ? currentLang : "nl";
  const deviceSelect = document.getElementById("automationDeviceSelect") || document.getElementById("autoDeviceSelect");
  const deviceKey = deviceSelect ? deviceSelect.value : "single_point";
  const isSinglePoint = (deviceKey === "single_point");

  // =========================================================================
  // 1. SPECIALIZED VOICE SCRIPT FOR SINGLE POINT LUBRICATORS (1-ON-1 DIRECT)
  // =========================================================================
  if (isSinglePoint) {
    const spGroups = (Array.isArray(autoDevicesState) && autoDevicesState.length > 0)
      ? autoDevicesState.filter(d => d && d.isSinglePointGroup && (d.unitCount > 0 || (d.bearingLetters && d.bearingLetters.length > 0)))
      : [];

    if (spGroups.length === 0) {
      const defaultUnits = window.spNumBearingsValue || (autoDevicesState[0] && autoDevicesState[0].unitCount) || 1;
      const defaultCap = (autoDevicesState[0] && autoDevicesState[0].cap) || 125;
      const defaultPeriod = (autoDevicesState[0] && autoDevicesState[0].period) || 6;
      spGroups.push({
        unitCount: defaultUnits,
        bearingLetters: [],
        groupBearingsText: '',
        cap: defaultCap,
        period: defaultPeriod,
        dailyNeedCm3: window.currentDailyNeedCm3 || 0.20
      });
    }

    const totalUnits = spGroups.reduce((sum, g) => sum + (g.unitCount || (g.bearingLetters ? g.bearingLetters.length : 1)), 0);
    const totalUnitsWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(totalUnits) : totalUnits.toString();
    const lagersWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(totalUnits) : totalUnits.toString();

    if (lang === "nl") {
      const groupSummaries = spGroups.map((g, idx) => {
        const uCount = g.unitCount || (g.bearingLetters ? g.bearingLetters.length : 1);
        const uWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(uCount) : uCount.toString();
        const capWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(g.cap || 125) : `${g.cap || 125}`;
        if (idx === 0) {
          return `${uWord} Single Point toestellen van ${capWord} milliliter`;
        } else {
          return `${uWord} van ${capWord} milliliter`;
        }
      });

      let groupSummaryPhrase = "";
      if (groupSummaries.length === 1) {
        groupSummaryPhrase = groupSummaries[0];
      } else if (groupSummaries.length === 2) {
        groupSummaryPhrase = `${groupSummaries[0]} en ${groupSummaries[1]}`;
      } else {
        groupSummaryPhrase = groupSummaries.slice(0, -1).join(', ') + ' en ' + groupSummaries[groupSummaries.length - 1];
      }

      let script = `Bij de huidige selectie voorziet u ${lagersWord} lagers van een rechtstreekse automatische smering met in totaal ${totalUnitsWord} Single Point Lubricators, direct gemonteerd op de smeerpunten. `;
      script += `Om optimaal in te spelen op de toerentallen en individuele vetbehoeften van uw lagers adviseren wij ${groupSummaryPhrase} om ${totalUnitsWord} lagers in totaal te smeren. `;

      spGroups.forEach(g => {
        const uCount = g.unitCount || (g.bearingLetters ? g.bearingLetters.length : 1);
        const bText = g.groupBearingsText
          ? `Lagers ${g.groupBearingsText.replace(/,\s*([^,]+)$/, ' en $1')}`
          : (g.bearingLetters && g.bearingLetters.length > 0
              ? `Lagers ${g.bearingLetters.join(', ').replace(/,\s*([^,]+)$/, ' en $1')}`
              : (uCount > 1 ? `deze ${uCount} lagers` : 'dit lager'));
        const uWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(uCount) : uCount.toString();
        const capWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(g.cap || 125) : `${g.cap || 125}`;
        const pVal = g.period || 6;
        const pWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(pVal) : pVal.toString();
        const periodUnitWord = pVal === 1 ? "maand" : "maanden";

        const dailyNeed = (g.dailyNeedCm3 && g.dailyNeedCm3 > 0) ? g.dailyNeedCm3 : ((typeof window !== 'undefined' && window.currentDailyNeedCm3) ? window.currentDailyNeedCm3 : 0.20);
        const totalDays = 30.4375 * pVal;
        const actualDose = (g.cap || 125) / totalDays;
        const doseSpoken = formatDecForDutchSpeech(actualDose);
        const needSpoken = formatDecForDutchSpeech(dailyNeed);
        const isMatch = Math.abs(actualDose - dailyNeed) < 0.03;

        if (isMatch) {
          script += `Voor ${bText}: ${uWord} Single Point toestellen van ${capWord} milliliter, met een draaiknopstand van ${pWord} ${periodUnitWord}. Dit doseert ${doseSpoken} milliliter per dag per lager, wat perfect aansluit bij de berekende vetbehoefte van ${needSpoken} milliliter per dag. `;
        } else {
          script += `Voor ${bText}: ${uWord} Single Point toestellen van ${capWord} milliliter, met een draaiknopstand van ${pWord} ${periodUnitWord}. Dit doseert ${doseSpoken} milliliter per dag per lager, bij een berekende behoefte van ${needSpoken} milliliter per dag. `;
        }
      });

      script += `Indien u een andere configuratie of looptijd wenst, kunt u deze eenvoudig aanpassen in sectie 3 van de vragenlijst of hieronder op deze pagina.`;
      return script;
    } else if (lang === "fr") {
      let script = `Avec la sélection actuelle, vous équipez ${totalUnits} roulements d'une lubrification automatique directe avec ${totalUnits} appareils Single Point Lubricator montés directement sur les points de graissage. `;
      spGroups.forEach(g => {
        const uCount = g.unitCount || 1;
        const bText = g.groupBearingsText ? `Roulements ${g.groupBearingsText}` : `ces ${uCount} roulements`;
        script += `Pour ${bText} : ${uCount} appareils de ${g.cap || 125} ml réglés sur ${g.period || 6} mois. `;
      });
      script += `Si vous préférez une configuration différente, vous pouvez la modifier dans la section 3 du questionnaire ou ci-dessous sur cette page.`;
      return script;
    } else {
      let script = `With the current selection, you provide ${totalUnits} bearings with direct automated lubrication using a total of ${totalUnits} Single Point Lubricators mounted directly on the lubrication points. `;
      spGroups.forEach(g => {
        const uCount = g.unitCount || 1;
        const bText = g.groupBearingsText ? `Bearings ${g.groupBearingsText}` : `these ${uCount} bearings`;
        script += `For ${bText}: ${uCount} units of ${g.cap || 125} ml set to a ${g.period || 6}-month dial setting. `;
      });
      script += `If you prefer a different configuration, you can adjust it in section 3 of the questionnaire or below on this page.`;
      return script;
    }
  }

  // =========================================================================
  // 2. MULTI-POINT VOICE SCRIPT FOR PULSARLUBE (DIVIDER BLOCKS & LINES)
  // =========================================================================
  const numDevices = typeof getActiveNumDevices === "function" ? getActiveNumDevices() : 1;
  const numCards = numDevices;

  let totalPoints = 0;
  for (let i = 0; i < numCards; i++) {
    const d = (autoDevicesState && autoDevicesState[i]) ? autoDevicesState[i] : null;
    if (d) {
      totalPoints += (typeof d.points === 'number' ? d.points : (parseInt(d.points, 10) || 0));
    } else {
      totalPoints += 1;
    }
  }
  if (totalPoints <= 0) totalPoints = numCards;

  const pointsWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(totalPoints) : totalPoints.toString();
  const devicesWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(numCards) : numCards.toString();
  const pointsNoun = totalPoints === 1 ? "smeerpunt" : "smeerpunten";
  const devicesNoun = numCards === 1 ? "toestel" : "toestellen";

  const distinctTypes = [...new Set(autoDevicesState.slice(0, numCards).map(d => (d && d.type) || deviceKey))];
  let deviceTypeSummary = "";
  if (distinctTypes.length === 1) {
    const singleType = distinctTypes[0];
    const typeName = getDeviceTypeName(singleType);
    deviceTypeSummary = `${typeName} ${devicesNoun}`;
  } else {
    const breakdown = autoDevicesState.slice(0, numCards).map(d => {
      const tName = getDeviceTypeName((d && d.type) || deviceKey);
      return `Toestel ${d ? d.id : ''} (${tName})`;
    }).join(' en ');
    deviceTypeSummary = `Pulsarlube ${devicesNoun} (${breakdown})`;
  }

  let script = "";
  if (lang === "nl") {
    script += `Bij de huidige selectie verdeelt u ${pointsWord} ${pointsNoun} over ${devicesWord} ${deviceTypeSummary}. `;
    script += `Op basis van leidingafstanden en individuele smeerbehoeften van de lagers is dit de ideale configuratie wat betreft keuze van de juiste toestellen en de leeglooptijd in maanden. `;

    for (let i = 0; i < numCards; i++) {
      const d = (autoDevicesState && autoDevicesState[i]) ? autoDevicesState[i] : { id: String.fromCharCode(65 + i) };
      const devId = d.id || String.fromCharCode(65 + i);
      const devModelName = getDeviceTypeName(d.type || deviceKey);

      const devPts = d.points || 1;
      const devPeriod = d.period || 6;
      const periodWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(devPeriod) : devPeriod.toString();
      const periodUnitWord = devPeriod === 1 ? "maand" : "maanden";
      const devPtsWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(devPts) : devPts.toString();
      const devPtsNoun = devPts === 1 ? "lager" : "lagers";

      const capMl = d.cap || 125;
      const capWord = (typeof numberToDutchWords === 'function') ? numberToDutchWords(capMl) : capMl.toString();

      const dailyNeed = (d.dailyNeedCm3 && d.dailyNeedCm3 > 0) ? d.dailyNeedCm3 : ((typeof window !== 'undefined' && window.currentDailyNeedCm3) ? window.currentDailyNeedCm3 : 0.20);
      const totalDailyNeedForDev = d.totalDailyNeed && d.totalDailyNeed > 0 ? d.totalDailyNeed : dailyNeed * devPts;
      const totalDays = 30.4375 * devPeriod;
      const actualDosePerBearing = (capMl / totalDays) / (devPts > 0 ? devPts : 1);
      const targetNeedPerBearing = devPts > 0 ? (totalDailyNeedForDev / devPts) : 0;

      const doseSpoken = formatDecForDutchSpeech(actualDosePerBearing);
      const needSpoken = formatDecForDutchSpeech(targetNeedPerBearing);

      const maxTheoMonths = (500 / (totalDailyNeedForDev > 0 ? totalDailyNeedForDev : 1)) / 30.4375;
      const isGraco = maxTheoMonths < 2.0;

      if (isGraco) {
        script += `Voor Toestel ${devId} (${devModelName}): vanwege een bijzonder hoge vetbehoefte wordt geadviseerd om een centraal Graco smeersysteem te overwegen. `;
      } else {
        const isMatch = Math.abs(actualDosePerBearing - targetNeedPerBearing) < 0.03;
        if (isMatch) {
          script += `Voor Toestel ${devId} (${devModelName}): met een patroon van ${capWord} milliliter en een instelling van ${periodWord} ${periodUnitWord} doseert dit toestel ${doseSpoken} milliliter per dag per lager voor ${devPtsWord} ${devPtsNoun}, wat perfect aansluit bij de berekende vetbehoefte van ${needSpoken} milliliter per dag. `;
        } else {
          script += `Voor Toestel ${devId} (${devModelName}): met een patroon van ${capWord} milliliter en een instelling van ${periodWord} ${periodUnitWord} doseert dit toestel ${doseSpoken} milliliter per dag per lager voor ${devPtsWord} ${devPtsNoun}, ten opzichte van een berekende behoefte van ${needSpoken} milliliter per dag. `;
        }
      }
    }

    script += `Indien u een andere configuratie verkiest, kunt u deze eenvoudig manueel aanpassen in sectie 3 van de vragenlijst of hieronder op deze pagina.`;
  } else if (lang === "fr") {
    const devTypeName = getDeviceTypeName(deviceKey);
    script += `Avec la sélection actuelle, vous répartissez ${totalPoints} points de lubrification sur ${numCards} appareils ${devTypeName}. `;
    script += `Sur la base des longueurs de tuyauterie et des besoins individuels de lubrification des roulements, il s'agit de la configuration idéale pour le choix des appareils et la durée de vidange en mois. `;
    for (let i = 0; i < numCards; i++) {
      const d = (autoDevicesState && autoDevicesState[i]) ? autoDevicesState[i] : { id: String.fromCharCode(65 + i) };
      const devId = d.id || String.fromCharCode(65 + i);
      const devPts = d.points || 1;
      const devPeriod = d.period || 6;
      script += `Pour l'Appareil ${devId}, avec un réglage de ${devPeriod} mois pour ${devPts} roulement${devPts > 1 ? 's' : ''}, le dosage assure une protection optimale parfaitement adaptée. `;
    }
    script += `Si vous préférez une configuration différente, vous pouvez la modifier manuellement dans la section 3 du questionnaire ou ci-dessous sur cette page.`;
  } else {
    const devTypeName = getDeviceTypeName(deviceKey);
    script += `With the current selection, you distribute ${totalPoints} lubrication points across ${numCards} ${devTypeName} units. `;
    script += `Based on pipe lengths and individual bearing lubrication requirements, this represents the ideal configuration regarding device selection and discharge period in months. `;
    for (let i = 0; i < numCards; i++) {
      const d = (autoDevicesState && autoDevicesState[i]) ? autoDevicesState[i] : { id: String.fromCharCode(65 + i) };
      const devId = d.id || String.fromCharCode(65 + i);
      const devPts = d.points || 1;
      const devPeriod = d.period || 6;
      script += `For Unit ${devId}, with a setting of ${devPeriod} months for ${devPts} bearing${devPts > 1 ? 's' : ''}, the unit delivers an optimal dose matching the calculated need. `;
    }
    script += `If you prefer a different configuration, you can easily adjust it manually in section 3 of the questionnaire or below on this page.`;
  }

  return script;
}

function speakNextAutoSentence(voice) {
  if (!isAutoAvatarSpeaking || autoSpeechQueue.length === 0) {
    setAutoAvatarUiState(false);
    return;
  }

  const sentence = autoSpeechQueue.shift();
  if (!sentence || !sentence.trim()) {
    speakNextAutoSentence(voice);
    return;
  }

  const lang = typeof currentLang !== "undefined" ? currentLang : "nl";
  const utter = new SpeechSynthesisUtterance(sentence.trim());
  activeAutoUtterance = utter;
  utter.lang = lang === "fr" ? "fr-FR" : (lang === "en" ? "en-US" : "nl-NL");
  utter.rate = 0.98;
  utter.pitch = 1.05;
  if (voice) utter.voice = voice;

  utter.onend = () => {
    activeAutoUtterance = null;
    if (isAutoAvatarSpeaking && autoSpeechQueue.length > 0) {
      speakNextAutoSentence(voice);
    } else {
      setAutoAvatarUiState(false);
    }
  };

  utter.onerror = (e) => {
    console.warn("Spraakfout:", e);
    activeAutoUtterance = null;
    setAutoAvatarUiState(false);
  };

  if (window.speechSynthesis.paused) {
    window.speechSynthesis.resume();
  }
  window.speechSynthesis.speak(utter);
}

function toggleAutoAvatarSpeech() {
  if (isAutoAvatarSpeaking) {
    stopAutoAvatarSpeech();
    return;
  }

  // Annuleer ROI avatar als die nog spreekt
  if (typeof stopRoiAvatarSpeech === "function") {
    stopRoiAvatarSpeech();
  }

  if (typeof window === "undefined" || !("speechSynthesis" in window)) {
    alert("Uw browser ondersteunt helaas geen spraaksynthese (Web Speech API). Probeer Google Chrome of Microsoft Edge.");
    return;
  }

  window.speechSynthesis.cancel();

  const script = generateAutomationSpeechScript();
  if (!script || !script.trim()) return;

  autoSpeechQueue = script.split(/(?<=[.?!])\s+/).filter(s => s.trim().length > 0);
  if (autoSpeechQueue.length === 0) return;

  const lang = typeof currentLang !== "undefined" ? currentLang : "nl";
  const voice = getBestVoiceForLang(lang);

  setAutoAvatarUiState(true);

  if (window.speechSynthesis.paused) {
    window.speechSynthesis.resume();
  }

  speakNextAutoSentence(voice);
}
window.toggleAutoAvatarSpeech = toggleAutoAvatarSpeech;


function addRoiPdfPage(doc, dateString, watermarkDataUrl, aspectRatio, autoDataUrl, autoImagesMap = null) {
  const pVal = (id) => {
    const prefixes = ["omShared", "om", "chainOmShared", "chainOm"];
    for (const p of prefixes) {
      const el = document.getElementById(p + id);
      if (el) {
        const v = parseFloat(el.value);
        if (!isNaN(v) && v !== 0) return v;
      }
    }
    for (const p of prefixes) {
      const el = document.getElementById(p + id);
      if (el) {
        const v = parseFloat(el.value);
        if (!isNaN(v)) return v;
      }
    }
    return 0;
  };
  doc.addPage();
  const pw = doc.internal.pageSize.getWidth();
  const ph = doc.internal.pageSize.getHeight();

  if (watermarkDataUrl) {
    try {
      doc.addImage(watermarkDataUrl, "PNG", 0, 0, pw, ph);
    } catch (e) {}
  }

  // Header Title
  doc.setFillColor(227, 6, 19);
  doc.rect(20, 15, 170, 2, "F");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(14);
  doc.setTextColor(227, 6, 19);
  doc.text("INTERFLON ROI BEREKENING AUTOMATISERING", 20, 25);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(100, 100, 100);
  doc.text("Kostenvergelijking manuele smering vs. automatische smeermodule • Gegenereerd op: " + dateString, 20, 30);

  doc.setDrawColor(220, 220, 220);
  doc.line(20, 33, 190, 33);

  // Read active devices state
  const deviceSelect = document.getElementById("automationDeviceSelect") || document.getElementById("autoDeviceSelect");
  let deviceKey = deviceSelect ? deviceSelect.value : "single_point";

  const isSinglePointMode = (deviceKey === "single_point") || (Array.isArray(autoDevicesState) && autoDevicesState.some(d => d && (d.isSinglePointGroup || d.type === 'single_point')));
  const isSinglePoint = isSinglePointMode;
  if (isSinglePoint) {
    deviceKey = "single_point";
    if (Array.isArray(autoDevicesState)) {
      autoDevicesState.forEach(d => { if (d) d.type = 'single_point'; });
    }
  }

  const numDevices = typeof getActiveNumDevices === "function" ? getActiveNumDevices() : 1;
  const activeDevList = (Array.isArray(autoDevicesState) ? autoDevicesState.slice(0, numDevices) : []);

  const selectGrease = document.getElementById("inputGrease") || document.getElementById("selectGrease");
  const greaseName = selectGrease ? selectGrease.value : "Interflon Grease MP2/3";
  const greasePriceInput = document.getElementById("omProdPrice2") || document.getElementById("chainOmProdPrice2") || document.getElementById("tcoPriceInterflonInput");
  const greasePricePerLiter = greasePriceInput ? (parseFloat(greasePriceInput.value) || 70.50) : 70.50;

  const dailyNeedCm3 = window.currentDailyNeedCm3 || 0.704;

  let totalPointsAllDevices = 0;
  let totalUnitsPrice = 0;
  let totalInstallKitPrice = 0;
  let totalDividerBlockPrice = 0;
  let totalCartridgesPerYear = 0;
  let totalCartridgesCostYear = 0;
  let mainCapMl = 125;
  let devBreakdownText = [];

  const spCapEl = document.getElementById("autoCartridgeCap_A") || document.getElementById("autoCartridgeCap");
  const spCapVal = (spCapEl ? parseInt(spCapEl.value, 10) : 0) || (typeof autoDevicesState !== "undefined" && autoDevicesState[0] ? autoDevicesState[0].cap : 0) || 125;
  const spPeriodEl = document.getElementById("autoDispensePeriod_A") || document.getElementById("autoDispensePeriod");
  const spPeriodVal = (spPeriodEl ? parseFloat(spPeriodEl.value) : 0) || (typeof autoDevicesState !== "undefined" && autoDevicesState[0] ? autoDevicesState[0].period : 0) || 4;
  const spUnitEl = document.getElementById("autoDispenseUnit_A") || document.getElementById("autoDispenseUnit");
  const spUnitVal = (spUnitEl ? spUnitEl.value : "") || (typeof autoDevicesState !== "undefined" && autoDevicesState[0] ? autoDevicesState[0].unit : "months");

  const activeSpGroups = (isSinglePoint && Array.isArray(autoDevicesState))
    ? autoDevicesState.filter(d => d && d.isSinglePointGroup && (d.unitCount > 0 || (d.bearingLetters && d.bearingLetters.length > 0)))
    : [];
  const isSpMultiGroup = (isSinglePoint && activeSpGroups.length > 1);
  const numLoop = isSinglePoint
    ? (isSpMultiGroup ? activeSpGroups.length : 1)
    : numDevices;

  for (let i = 0; i < numLoop; i++) {
    const d = (typeof autoDevicesState !== "undefined" && autoDevicesState[i]) ? autoDevicesState[i] : { id: String.fromCharCode(65 + i), points: 1, cap: 125, period: 6, unit: 'months' };
    const multiplier = isSinglePoint
      ? (isSpMultiGroup ? (d.unitCount || 1) : (window.spNumBearingsValue || (autoDevicesState[0] && autoDevicesState[0].unitCount) || 1))
      : 1;
    const pts = isSinglePoint ? 1 : ((typeof d.points === 'number') ? d.points : (parseInt(d.points, 10) || 0));
    if (pts === 0 && !isSinglePoint) continue;

    const devCapEl = document.getElementById("autoCartridgeCap_" + d.id);
    const devCapVal = devCapEl ? parseInt(devCapEl.value, 10) : 0;
    const cap = (isSinglePoint && !isSpMultiGroup) ? spCapVal : (devCapVal || d.cap || 125);
    mainCapMl = cap;
    totalPointsAllDevices += (pts * multiplier);

    if (!isSinglePoint) {
      const thisDevType = d.type || (deviceKey !== "mixed" ? deviceKey : "pulsarlube_m2");
      const devTypeName = getDeviceTypeName(thisDevType);
      devBreakdownText.push(`Toestel ${d.id} (${devTypeName}): ${pts} ${pts === 1 ? 'lager' : 'lagers'}`);
    } else if (isSpMultiGroup) {
      const lStr = d.groupBearingsText || (d.bearingLetters ? d.bearingLetters.join(', ') : d.id);
      devBreakdownText.push(`${multiplier}x Single Point (Lager ${lStr})`);
    }

    const devPeriodEl = document.getElementById("autoDispensePeriod_" + d.id);
    const devPeriodVal = devPeriodEl ? parseFloat(devPeriodEl.value) : 0;
    const devUnitEl = document.getElementById("autoDispenseUnit_" + d.id);
    const devUnitVal = devUnitEl ? devUnitEl.value : "";

    const period = (isSinglePoint && !isSpMultiGroup) ? spPeriodVal : (devPeriodVal || d.period || 6);
    const unit = (isSinglePoint && !isSpMultiGroup) ? spUnitVal : (devUnitVal || d.unit || "months");

    const domCustomPriceEl = document.getElementById("autoCustomPackPrice_" + d.id) || document.getElementById("autoCustomPackPrice_A");
    const domCustomVal = domCustomPriceEl ? parseFloat(domCustomPriceEl.value) : 0;
    const spCustomFallback = window.customSinglePointPackPrice || (typeof autoDevicesState !== "undefined" && autoDevicesState[0] ? autoDevicesState[0].customPackPrice : 0);
    const activeCustomPrice = (!isNaN(domCustomVal) && domCustomVal > 0) ? domCustomVal : (d.customPackPrice || ((isSinglePoint || i === 0) ? spCustomFallback : 0));
    const thisDevType = isSinglePoint ? "single_point" : (d.type || (deviceKey !== "mixed" ? deviceKey : "pulsarlube_m2"));
    const pInfo = getAutomationPriceInfo(thisDevType, cap, greaseName, pts, activeCustomPrice);
    if (!isSinglePoint) {
      totalUnitsPrice += (pInfo.unitPrice * multiplier);
      totalInstallKitPrice += (pInfo.installKitPrice * multiplier);
      totalDividerBlockPrice += (pInfo.dividerBlockPrice * multiplier);
    }

    const devNeedRate = (isSinglePoint && d.dailyNeedCm3 && d.dailyNeedCm3 > 0) ? d.dailyNeedCm3 : dailyNeedCm3;
    const yearlyMlDev = devNeedRate * pts * 365.25;
    let cartsDev = 0;
    if (period > 0) {
      cartsDev = unit === "weeks" ? (52.1785 / period) : (12 / period);
    } else {
      cartsDev = cap > 0 ? (yearlyMlDev / cap) : 0;
    }
    const cartsGroup = cartsDev * multiplier;
    totalCartridgesPerYear += cartsGroup;
    totalCartridgesCostYear += (cartsGroup * pInfo.servicepackPrice);
  }

  const numPoints = totalPointsAllDevices;
  let totalDailyNeedAllDevices = 0;
  if (isSinglePoint) {
    if (isSpMultiGroup) {
      activeSpGroups.forEach(g => {
        const cnt = g.unitCount || (g.bearingLetters ? g.bearingLetters.length : 1);
        const need1 = (g.dailyNeedCm3 && g.dailyNeedCm3 > 0) ? g.dailyNeedCm3 : (window.currentDailyNeedCm3 || 0.704);
        totalDailyNeedAllDevices += (need1 * cnt);
      });
    } else {
      const cnt = window.spNumBearingsValue || (autoDevicesState[0] && autoDevicesState[0].unitCount) || 1;
      const need1 = (autoDevicesState[0] && autoDevicesState[0].dailyNeedCm3 > 0) ? autoDevicesState[0].dailyNeedCm3 : (window.currentDailyNeedCm3 || 0.704);
      totalDailyNeedAllDevices = need1 * cnt;
    }
  } else {
    totalDailyNeedAllDevices = dailyNeedCm3 * totalPointsAllDevices;
  }
  const yearlyMlTotal = totalDailyNeedAllDevices * 365.25;

  let fullDeviceTitle = "";
  if (isSinglePoint) {
    fullDeviceTitle = (numPoints > 1 ? `${numPoints}x Interflon Single Point Lubricator` : "Interflon Single Point Lubricator");
  } else if (numDevices === 1) {
    const t = (autoDevicesState && autoDevicesState[0] && autoDevicesState[0].type) || (deviceKey !== "mixed" ? deviceKey : "pulsarlube_m2");
    fullDeviceTitle = getDeviceTypeName(t);
  } else {
    const typeCounts = {};
    const typeOrder = [];
    for (let i = 0; i < numDevices; i++) {
      const d = (typeof autoDevicesState !== "undefined" && autoDevicesState[i]) ? autoDevicesState[i] : null;
      const t = (d && d.type) ? d.type : (deviceKey !== "mixed" ? deviceKey : "pulsarlube_m2");
      if (!typeCounts[t]) {
        typeCounts[t] = 0;
        typeOrder.push(t);
      }
      typeCounts[t]++;
    }
    const titleParts = typeOrder.map(t => `${typeCounts[t]}x ${getDeviceTypeName(t)}`);
    fullDeviceTitle = titleParts.join(" + ");
  }

  // Banner Box
  doc.setFillColor(248, 250, 252);
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.25);
  doc.roundedRect(20, 36, 170, 20, 2, 2, "FD");

  const roiDevTypes = [];
  if (isSinglePoint) {
    roiDevTypes.push("single_point");
  } else {
    for (let i = 0; i < numDevices; i++) {
      const d = activeDevList[i] || null;
      const t = (d && d.type) ? d.type : (deviceKey !== "mixed" ? deviceKey : "pulsarlube_m2");
      if (!roiDevTypes.includes(t)) {
        roiDevTypes.push(t);
      }
    }
    if (roiDevTypes.length === 0) {
      roiDevTypes.push(deviceKey !== "mixed" ? deviceKey : "pulsarlube_m2");
    }
  }

  let textStartX = 44;
  if (roiDevTypes.length <= 1) {
    const t = roiDevTypes[0];
    const imgData = (autoImagesMap && autoImagesMap[t] && autoImagesMap[t].dataUrl) ? autoImagesMap[t].dataUrl : autoDataUrl;
    if (imgData) {
      try {
        doc.addImage(imgData, "PNG", 24, 38, 16, 16);
      } catch(e){}
    }
    textStartX = 44;
  } else {
    const t1 = roiDevTypes[0];
    const t2 = roiDevTypes[1];
    const img1 = (autoImagesMap && autoImagesMap[t1] && autoImagesMap[t1].dataUrl) ? autoImagesMap[t1].dataUrl : autoDataUrl;
    const img2 = (autoImagesMap && autoImagesMap[t2] && autoImagesMap[t2].dataUrl) ? autoImagesMap[t2].dataUrl : null;
    if (img1) {
      try { doc.addImage(img1, "PNG", 22, 38, 15, 15); } catch(e){}
    }
    if (img2) {
      try { doc.addImage(img2, "PNG", 38, 38, 15, 15); } catch(e){}
    }
    textStartX = 56;
  }

  doc.setFont("helvetica", "bold");
  doc.setFontSize(11);
  doc.setTextColor(30, 41, 59);
  doc.text(fullDeviceTitle, textStartX, 43);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(100, 116, 139);
  const capInfoStr = numDevices === 1 ? `Patrooninhoud: ${mainCapMl} ml` : `${numDevices} geselecteerde toestellen`;
  doc.text(`${capInfoStr}  •  Aantal lagers: ${numPoints}  •  Geselecteerd product: ${greaseName}`, textStartX, 49);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(9);
  doc.setTextColor(227, 6, 19);
  doc.text(`Berekend verbruik: ${yearlyMlTotal.toLocaleString("nl-BE", { minimumFractionDigits: 1, maximumFractionDigits: 1 })} ml / jaar`, 186, 46, { align: "right" });

  // Calculations
  const manualModeSelect = document.getElementById("roiManualModeSelect");
  const manualMode = manualModeSelect ? manualModeSelect.value : "interflon";
  const isHuidigMode = (manualMode === "huidig");

  const techBeurtenInput = document.getElementById("tcoFreqInterflonInput");
  const manualBeurtenPerYearInterflon = pVal("ProdFreq2") || 13.1;
  const workTimeInput = document.getElementById("omSharedWorktime") || document.getElementById("chainOmSharedWorktime");
  let workTimeMinutes = 3;
  if (workTimeInput && !isNaN(parseFloat(workTimeInput.value)) && parseFloat(workTimeInput.value) >= 0) {
    workTimeMinutes = parseFloat(workTimeInput.value);
  } else {
    const pv = pVal("Worktime") || pVal("SharedWorktime");
    if (!isNaN(pv) && pv > 0) workTimeMinutes = pv;
  }

  const hourlyRateInput = document.getElementById("omSharedLaborRate") || document.getElementById("chainOmSharedLaborRate") || document.getElementById("tcoHourlyRateInput");
  let hourlyRate = 50.00;
  if (hourlyRateInput && !isNaN(parseFloat(hourlyRateInput.value)) && parseFloat(hourlyRateInput.value) >= 0) {
    hourlyRate = parseFloat(hourlyRateInput.value);
  } else {
    const pv = pVal("LaborRate") || pVal("SharedLaborRate");
    if (!isNaN(pv) && pv > 0) hourlyRate = pv;
  }

  let manualGreasePricePerLiter = greasePricePerLiter;
  let manualBeurtenPerYear = manualBeurtenPerYearInterflon;
  let manualYearlyMl = yearlyMlTotal;
  let manualGreaseCost = 0;
  let manualLaborHours = 0;
  let manualLaborCost = 0;
  let manualTotalCost = 0;

  // TCO extra costs (PDF)


  const tcoSets = pVal("SetsPerMachine") || 1;
  const numBearingsForTco = (tcoSets > 0) ? Math.max(tcoSets, totalPointsAllDevices) : (totalPointsAllDevices || 1);

  // TCO extra costs PDF (Col 1: Huidige Situatie, Col 2: Interflon)
  const p1_lifetime = pVal("Lifetime1") || pVal("RepairFreq1") || 12;
  const p2_lifetime = pVal("Lifetime2") || pVal("RepairFreq2") || 36;

  const shared_repair_h = pVal("RepairH") || pVal("SharedRepairH");
  const shared_prep_h = pVal("PrepH") || pVal("SharedPrepH");
  const shared_parts_cost = pVal("PartsCost") || pVal("SharedPartsCost");
  const shared_downtime_rate = pVal("DowntimeRate") || pVal("SharedDowntimeRate");

  const p1_downtime_h = pVal("DowntimeH1") || pVal("PrepH") || 1;
  const p1_downtime_freq = p1_lifetime > 0 ? (12 / p1_lifetime) : 0.5;

  const p2_downtime_h = pVal("DowntimeH2") || pVal("PrepH") || 1;
  const p2_downtime_freq = p2_lifetime > 0 ? (12 / p2_lifetime) : 0.3333;

  const activeLifetime = isHuidigMode ? p1_lifetime : p2_lifetime;
  const activeRepairFreq = activeLifetime;
  const activeDtH = isHuidigMode ? p1_downtime_h : p2_downtime_h;
  const activeDtFreq = isHuidigMode ? p1_downtime_freq : p2_downtime_freq;

  let manualRepairCost = activeRepairFreq > 0 ? ((12 / activeRepairFreq) * (shared_repair_h + shared_prep_h) * numBearingsForTco * hourlyRate) : 0;
  let manualMatCost = activeLifetime > 0 ? ((12 / activeLifetime) * shared_parts_cost * numBearingsForTco) : 0;
  let manualDowntimeCost = activeDtH * activeDtFreq * shared_downtime_rate * numBearingsForTco;

  const lifetimeFactorEl = document.getElementById("roiLifetimeFactorSelect");
  const lifetimeFactorPct = lifetimeFactorEl ? (parseFloat(lifetimeFactorEl.value) || 0) : 0;
  const lifetimeMult = 1 + (lifetimeFactorPct / 100);

  let autoRepairCost = (p2_lifetime > 0 ? ((12 / p2_lifetime) * (shared_repair_h + shared_prep_h) * numBearingsForTco * hourlyRate) : 0) / lifetimeMult;
  let autoMatCost = (p2_lifetime > 0 ? ((12 / p2_lifetime) * shared_parts_cost * numBearingsForTco) : 0) / lifetimeMult;
  let autoDowntimeCost = (p2_downtime_h * p2_downtime_freq * shared_downtime_rate * numBearingsForTco) / lifetimeMult;

  if (isHuidigMode) {
    const currentPriceInput = document.getElementById("omProdPrice1") || document.getElementById("chainOmProdPrice1") || document.getElementById("tcoPriceCurrentInput");
    manualGreasePricePerLiter = currentPriceInput ? (parseFloat(currentPriceInput.value) || 20.00) : 20.00;

    const currentFreqInput = document.getElementById("omProdFreq1") || document.getElementById("chainOmProdFreq1") || document.getElementById("tcoFreqCurrentInput");
    manualBeurtenPerYear = currentFreqInput ? (parseFloat(currentFreqInput.value) || 26.0) : 26.0;

    const currentConsInput = document.getElementById("omProdCons1") || document.getElementById("chainOmProdCons1") || document.getElementById("tcoQtyCurrentInput");
    const manualConsPerBeurtGrams = currentConsInput ? parseFloat(currentConsInput.value) || 0 : 0;

    if (manualConsPerBeurtGrams > 0) {
      manualYearlyMl = (manualConsPerBeurtGrams * manualBeurtenPerYear * numBearingsForTco) / 0.92;
    } else {
      manualYearlyMl = manualBeurtenPerYearInterflon > 0 ? (yearlyMlTotal * (manualBeurtenPerYear / manualBeurtenPerYearInterflon)) : yearlyMlTotal;
    }

    manualGreaseCost = (manualYearlyMl / 1000) * manualGreasePricePerLiter;
    manualLaborHours = numBearingsForTco * manualBeurtenPerYear * (workTimeMinutes / 60);
    manualLaborCost = manualLaborHours * hourlyRate;
    manualTotalCost = manualGreaseCost + manualLaborCost + manualRepairCost + manualMatCost + manualDowntimeCost;
  } else {
    manualBeurtenPerYear = pVal("ProdFreq2") || 13.1;
    const interflonPriceInput = document.getElementById("omProdPrice2") || document.getElementById("chainOmProdPrice2") || document.getElementById("tcoPriceInterflonInput");
    if (interflonPriceInput && !isNaN(parseFloat(interflonPriceInput.value)) && parseFloat(interflonPriceInput.value) >= 0) {
      manualGreasePricePerLiter = parseFloat(interflonPriceInput.value);
    } else {
      const pv = pVal("ProdPrice2");
      if (!isNaN(pv) && pv >= 0) manualGreasePricePerLiter = pv;
      else manualGreasePricePerLiter = greasePricePerLiter;
    }

    const interflonConsInput = document.getElementById("omProdCons2") || document.getElementById("chainOmProdCons2");
    const interflonConsPerBeurtGrams = (interflonConsInput && !isNaN(parseFloat(interflonConsInput.value)) && parseFloat(interflonConsInput.value) > 0) ? parseFloat(interflonConsInput.value) : (pVal("ProdCons2") || 0);
    if (interflonConsPerBeurtGrams > 0) {
      manualYearlyMl = (interflonConsPerBeurtGrams * manualBeurtenPerYear * numBearingsForTco) / 0.92;
    } else {
      manualYearlyMl = dailyNeedCm3 * numBearingsForTco * 365.25;
    }

    manualGreaseCost = (manualYearlyMl / 1000) * manualGreasePricePerLiter;
    manualLaborHours = numBearingsForTco * manualBeurtenPerYear * (workTimeMinutes / 60);
    manualLaborCost = manualLaborHours * hourlyRate;
    manualTotalCost = manualGreaseCost + manualLaborCost + manualRepairCost + manualMatCost + manualDowntimeCost;
  }

  const autoLaborCost = totalCartridgesPerYear * (15 / 60) * hourlyRate;
  const autoYear1Total = totalUnitsPrice + totalInstallKitPrice + totalDividerBlockPrice + totalCartridgesCostYear + autoLaborCost + autoRepairCost + autoMatCost + autoDowntimeCost;
  const autoRecurringTotal = totalCartridgesCostYear + autoLaborCost + autoRepairCost + autoMatCost + autoDowntimeCost;

  function drawRow(x, y, w, h, label, valStr, isHeader, isTotal, isGreen) {
    if (isHeader) {
      doc.setFillColor(isGreen ? 6 : 159, isGreen ? 95 : 18, isGreen ? 70 : 57);
      doc.rect(x, y, w, h, "F");
      doc.setFont("helvetica", "bold");
      doc.setFontSize(8.5);
      doc.setTextColor(255, 255, 255);
      doc.text(label, x + w / 2, y + h / 2 + 1.2, { align: "center" });
      return;
    }

    if (isTotal) {
      if (isGreen === "dark") doc.setFillColor(220, 252, 231);
      else if (isGreen) doc.setFillColor(240, 253, 244);
      else doc.setFillColor(254, 242, 242);
      doc.rect(x, y, w, h, "F");
    } else {
      doc.setFillColor(255, 255, 255);
      doc.rect(x, y, w, h, "F");
    }

    doc.setDrawColor(226, 232, 240);
    doc.setLineWidth(0.2);
    doc.rect(x, y, w, h, "D");

    doc.setFont("helvetica", isTotal ? "bold" : "normal");
    doc.setFontSize(7);
    doc.setTextColor(71, 85, 105);
    doc.text(label, x + 2.5, y + h / 2 + 1.2);

    doc.setFont("helvetica", "bold");
    doc.setFontSize(7.5);
    if (isGreen) doc.setTextColor(22, 101, 52);
    else if (isTotal) doc.setTextColor(159, 18, 57);
    else doc.setTextColor(15, 23, 42);
    doc.text(valStr || "", x + w - 2.5, y + h / 2 + 1.2, { align: "right" });
  }

  // Tables
  const startY = 60;
  const colW = 82;
  const rh = 6.2;

  // Table 1: Manuele Smering
  let y1 = startY;
  const table1Title = isHuidigMode ? "MANUELE SMERING (HUIDIG)" : "MANUELE SMERING (INTERFLON)";
  if (isHuidigMode) {
    doc.setFillColor(3, 105, 161);
    doc.rect(20, y1, colW, 6, "F");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8.5);
    doc.setTextColor(255, 255, 255);
    doc.text(table1Title, 20 + colW / 2, y1 + 6 / 2 + 1.2, { align: "center" });
  } else {
    drawRow(20, y1, colW, 6, table1Title, "", true, false, false);
  }
  y1 += 6;
  drawRow(20, y1, colW, rh, "Jaarlijks vetverbruik:", `${manualYearlyMl.toLocaleString("nl-BE", { minimumFractionDigits: 1, maximumFractionDigits: 1 })} ml`, false, false, false);
  y1 += rh;
  drawRow(20, y1, colW, rh, "Prijs vet per liter:", `€ ${manualGreasePricePerLiter.toLocaleString("nl-BE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} / L`, false, false, false);
  y1 += rh;
  drawRow(20, y1, colW, rh, "Jaarlijkse vetkost:", `€ ${manualGreaseCost.toLocaleString("nl-BE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} / j`, false, false, false);
  y1 += rh;
  const effectivePdfManBearings = numBearingsForTco;
  const pdfBeurtenValStr = effectivePdfManBearings > 1
    ? `${(manualBeurtenPerYear * effectivePdfManBearings).toLocaleString("nl-BE", { minimumFractionDigits: 1, maximumFractionDigits: 1 })} (${manualBeurtenPerYear.toLocaleString("nl-BE", { minimumFractionDigits: 1, maximumFractionDigits: 1 })} beurten x ${effectivePdfManBearings} lagers)`
    : `${manualBeurtenPerYear.toLocaleString("nl-BE", { minimumFractionDigits: 1, maximumFractionDigits: 1 })} beurten`;
  drawRow(20, y1, colW, rh, "Totaal lagersmeerbeurten/jaar:", pdfBeurtenValStr, false, false, false);
  y1 += rh;
  drawRow(20, y1, colW, rh, "Tijd per smeerbeurt:", `${workTimeMinutes} min (${manualLaborHours.toFixed(1).replace('.',',')} u/j)`, false, false, false);
  y1 += rh;
  drawRow(20, y1, colW, rh, "Uurloon technieker:", `€ ${hourlyRate.toLocaleString("nl-BE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} / uur`, false, false, false);
  y1 += rh;
  drawRow(20, y1, colW, rh, "Jaarlijkse arbeidskost:", `€ ${manualLaborCost.toLocaleString("nl-BE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} / j`, false, false, false);
  y1 += rh;
  drawRow(20, y1, colW, rh, "Tijdsbesteding revisie:", `€ ${manualRepairCost.toLocaleString("nl-BE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} / j`, false, false, false);
  y1 += rh;
  drawRow(20, y1, colW, rh, "Materiaalkost onderdelen:", `€ ${manualMatCost.toLocaleString("nl-BE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} / j`, false, false, false);
  y1 += rh;
  drawRow(20, y1, colW, rh, "Downtime kost:", `€ ${manualDowntimeCost.toLocaleString("nl-BE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} / j`, false, false, false);
  y1 += rh;

  if (isHuidigMode) {
    doc.setFillColor(240, 249, 255);
    doc.rect(20, y1, colW, 7, "F");
    doc.setDrawColor(186, 230, 253);
    doc.setLineWidth(0.2);
    doc.rect(20, y1, colW, 7, "D");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(7);
    doc.setTextColor(3, 105, 161);
    doc.text("TOTALE JAARKOST MANUEEL:", 22.5, y1 + 7 / 2 + 1.2);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(7.5);
    doc.setTextColor(3, 105, 161);
    doc.text(`€ ${manualTotalCost.toLocaleString("nl-BE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`, 20 + colW - 2.5, y1 + 7 / 2 + 1.2, { align: "right" });
  } else {
    drawRow(20, y1, colW, 7, "TOTALE JAARKOST MANUEEL:", `€ ${manualTotalCost.toLocaleString("nl-BE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`, false, true, false);
  }

  // Table 2: Automatische Smering
  let y2 = startY;
  drawRow(108, y2, colW, 6, "AUTOMATISCHE SMERING", "", true, false, true);
  y2 += 6;
  drawRow(108, y2, colW, rh, "Gekozen smeerunit:", fullDeviceTitle, false, false, false);
  y2 += rh;
  drawRow(108, y2, colW, rh, "Verbruik patronen/jaar:", `${totalCartridgesPerYear.toFixed(1).replace('.', ',')} patronen/j`, false, false, false);
  y2 += rh;
  drawRow(108, y2, colW, rh, "Prijs leeg toestel (totaal):", (deviceKey === 'single_point' ? '€ 0,00 (Voorgevuld)' : `€ ${totalUnitsPrice.toFixed(2).replace('.', ',')}`), false, false, false);
  y2 += rh;
  drawRow(108, y2, colW, rh, "Jaarlijkse kosten patronen:", `€ ${totalCartridgesCostYear.toFixed(2).replace('.', ',')} / j`, false, false, false);
  y2 += rh;
  drawRow(108, y2, colW, rh, "Installatiekits + Verdeelblokken:", (deviceKey === 'single_point' ? '€ 0,00 (Niet nodig)' : `€ ${(totalInstallKitPrice + totalDividerBlockPrice).toFixed(2).replace('.', ',')} (Eenmalig)`), false, false, false);
  y2 += rh;
  drawRow(108, y2, colW, rh, "Arbeidskost patroonwissels:", `€ ${autoLaborCost.toFixed(2).replace('.', ',')} / j`, false, false, false);
  y2 += rh;
  drawRow(108, y2, colW, rh, "Tijdsbesteding revisie:", `€ ${autoRepairCost.toFixed(2).replace('.', ',')} / j`, false, false, false);
  y2 += rh;
  drawRow(108, y2, colW, rh, "Materiaalkost onderdelen:", `€ ${autoMatCost.toFixed(2).replace('.', ',')} / j`, false, false, false);
  y2 += rh;
  drawRow(108, y2, colW, rh, "Downtime kost:", `€ ${autoDowntimeCost.toFixed(2).replace('.', ',')} / j`, false, false, false);
  y2 += rh;

  drawRow(108, y2, colW, 7, "JAAR 1 TOTAAL:", `€ ${autoYear1Total.toFixed(2).replace('.', ',')}`, false, true, false);
  y2 += 7;
  drawRow(108, y2, colW, 7, "JAAR 2+ TERUGKEREND:", `€ ${autoRecurringTotal.toFixed(2).replace('.', ',')}`, false, true, "dark");

  // Financial ROI Results Box (Matching App Layout & Exact TVT Calculation)
  const roiBoxY = 138;
  const roiBoxH = 64;
  doc.setFillColor(248, 250, 252);
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.3);
  doc.roundedRect(20, roiBoxY, 170, roiBoxH, 2, 2, "FD");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.setTextColor(30, 41, 59);
  doc.text("FINANCIËLE ANALYSE & ROI RESULTAAT", 25, roiBoxY + 7);

  const netYearlySaving = manualTotalCost - autoRecurringTotal;
  const year1NetResult = manualTotalCost - autoYear1Total;

  const roiYearsInput = document.getElementById("roiYearsInput");
  const numYears = roiYearsInput ? (parseInt(roiYearsInput.value, 10) || 5) : 5;
  const multiYearSaving = year1NetResult + Math.max(0, numYears - 1) * netYearlySaving;

  // Payback calculation matching App UI exactly:
  const initialInvestment = autoYear1Total - autoRecurringTotal;
  let paybackStr = "Direct";
  let isPaybackGreen = true;
  if (initialInvestment <= 0) {
    paybackStr = "Direct";
  } else if (netYearlySaving <= 0) {
    paybackStr = "Geen TVT";
    isPaybackGreen = false;
  } else {
    const paybackYears = initialInvestment / netYearlySaving;
    const paybackMonths = paybackYears * 12;
    paybackStr = `${paybackMonths.toFixed(1).replace('.', ',')} m (${paybackYears.toFixed(2).replace('.', ',')} j)`;
  }

  function drawRoiCard(x, y, w, h, title, valStr, subStr, valColor) {
    doc.setFillColor(255, 255, 255);
    doc.setDrawColor(226, 232, 240);
    doc.setLineWidth(0.2);
    doc.roundedRect(x, y, w, h, 1.5, 1.5, "FD");

    doc.setFont("helvetica", "bold");
    doc.setFontSize(6);
    doc.setTextColor(100, 116, 139);
    doc.text(title, x + w / 2, y + 4.5, { align: "center" });

    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(valColor[0], valColor[1], valColor[2]);
    doc.text(valStr, x + w / 2, y + 11.5, { align: "center" });

    doc.setFont("helvetica", "normal");
    doc.setFontSize(5.5);
    doc.setTextColor(148, 163, 184);
    doc.text(subStr, x + w / 2, y + 17, { align: "center" });
  }

  const row1Y = roiBoxY + 11;
  const row2Y = roiBoxY + 33;
  const cardW = 50;
  const cardH = 20;

  // Card 1: Structurele jaarlijkse besparing
  const sign1 = netYearlySaving >= 0 ? "+" : "-";
  const color1 = netYearlySaving >= 0 ? [22, 163, 74] : [220, 38, 38];
  drawRoiCard(24, row1Y, cardW, cardH, "STRUCTURELE JAARLIJKSE BESPARING", `${sign1} € ${Math.abs(netYearlySaving).toFixed(2).replace('.', ',')} / j`, "Vanaf Jaar 2", color1);

  // Card 2: Netto resultaat jaar 1
  const sign2 = year1NetResult >= 0 ? "+" : "-";
  const color2 = year1NetResult >= 0 ? [22, 163, 74] : [220, 38, 38];
  drawRoiCard(80, row1Y, cardW, cardH, "NETTO RESULTAAT JAAR 1", `${sign2} € ${Math.abs(year1NetResult).toFixed(2).replace('.', ',')} (Jaar 1)`, "Inclusief initiële installatie", color2);

  // Card 3: Terugverdientijd
  const color3 = isPaybackGreen ? [220, 38, 38] : [100, 116, 139];
  drawRoiCard(136, row1Y, cardW, cardH, "TERUGVERDIENTIJD (ROI)", paybackStr, "Investerings-terugverdientijd", color3);

  // Card 4: Besparing na N jaar
  const sign4 = multiYearSaving >= 0 ? "+" : "-";
  const color4 = multiYearSaving >= 0 ? [5, 150, 105] : [220, 38, 38];
  drawRoiCard(24, row2Y, cardW, cardH, `BESPARING NA ${numYears} JAAR`, `${sign4} € ${Math.abs(multiYearSaving).toFixed(2).replace('.', ',')}`, "Inclusief initiële installatie", color4);

  // Belangrijke Toelichting Box in PDF
  const toelW = 106;
  doc.setFillColor(254, 242, 242);
  doc.setDrawColor(252, 165, 165);
  doc.setLineWidth(0.2);
  doc.roundedRect(80, row2Y, toelW, cardH, 1.5, 1.5, "FD");

  // Red accent line on left of toelichting
  doc.setFillColor(227, 6, 19);
  doc.rect(80, row2Y, 1.5, cardH, "F");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(6.5);
  doc.setTextColor(227, 6, 19);
  doc.text("Belangrijke toelichting:", 84, row2Y + 4.5);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(5.2);
  doc.setTextColor(71, 85, 105);
  const toelichtingTxt = "Bovenstaande berekening weerspiegelt uitsluitend de directe overgang van handmatige naar automatische smering. In de praktijk ontstaat het grootste financiële en operationele voordeel echter door een verhoogde bedrijfszekerheid (hogere output), een langere levensduur van componenten (minder reserveonderdelen) en een aanzienlijke reductie in revisie-uren.";
  const splitToel = doc.splitTextToSize(toelichtingTxt, toelW - 6);
  doc.text(splitToel, 84, row2Y + 8.5);

  // Footer Line & Disclaimer at bottom
  const footerY = roiBoxY + roiBoxH + 6;
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.2);
  doc.line(20, footerY, 190, footerY);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(5.5);
  doc.setTextColor(148, 163, 184);
  const footerText = "De gegenereerde gegevens bieden een betrouwbare indicatie, maar vormen geen expliciete garantie dat een product of dosering geschikt is voor elke specifieke toepassing. De calculator biedt een adviesrichtlijn; er kan geen wettelijke waarborg of aansprakelijkheid worden verleend met betrekking tot het concrete gebruik ervan in de praktijk.";
  const splitFooter = doc.splitTextToSize(footerText, 170);
  doc.text(splitFooter, 20, footerY + 4);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(7.5);
  doc.setTextColor(227, 6, 19);
  doc.text("INTERFLON - A WORLD WITHOUT FRICTION", 20, footerY + 14);
}

// ==========================================================================
// PAGINA 5: 3D MACHINERASTER / INSTALLATIE SCHETS & LEIDINGAFSTANDEN
// ==========================================================================

function calculateOptimalRasterZoom(bearingPositions, devices, showCentralPoint, machineRangeMeters, layoutViewMode) {
  const points = [];

  if (showCentralPoint) {
    points.push({ x: 0, y: 0 });
  }

  (devices || []).forEach(dev => {
    if (dev && dev.active !== false) {
      points.push({ x: dev.x || 0, y: dev.y || 0 });
    }
  });

  Object.values(bearingPositions || {}).forEach(pos => {
    if (pos && typeof pos.x === 'number' && typeof pos.y === 'number') {
      points.push({ x: pos.x, y: pos.y });
    }
  });

  if (points.length <= 1) {
    return 2.5;
  }

  const is3D = (layoutViewMode === '3d');
  let minIsoX = Infinity, maxIsoX = -Infinity;
  let minIsoY = Infinity, maxIsoY = -Infinity;

  points.forEach(p => {
    let ix, iy;
    if (is3D) {
      ix = (p.x - p.y) * 0.866;
      iy = -(p.x + p.y) * 0.5;
    } else {
      ix = p.x;
      iy = -p.y;
    }
    if (ix < minIsoX) minIsoX = ix;
    if (ix > maxIsoX) maxIsoX = ix;
    if (iy < minIsoY) minIsoY = iy;
    if (iy > maxIsoY) maxIsoY = iy;
  });

  const maxSpanX = Math.max(Math.abs(minIsoX), Math.abs(maxIsoX));
  const maxSpanY = Math.max(Math.abs(minIsoY), Math.abs(maxIsoY));

  // Ruime marge in meters voor labels, afstandsbadges en cirkels
  const marginMeters = 1.35;
  const effectiveSpanX = (maxSpanX + marginMeters);
  const effectiveSpanY = (maxSpanY + marginMeters);

  const rangeNeededX = is3D ? (effectiveSpanX / 1.732) : effectiveSpanX;
  const rangeNeededY = effectiveSpanY;
  const rangeNeeded = Math.max(rangeNeededX, rangeNeededY, 2.2);

  let optimalZoom = (machineRangeMeters || 10) / rangeNeeded;
  const minZoom = (machineRangeMeters && machineRangeMeters >= 50) ? 1.0 : 1.2;
  optimalZoom = Math.max(minZoom, Math.min(3.0, Math.round(optimalZoom * 20) / 20));

  return optimalZoom;
}

function getActiveMachineRasterData() {
  let qData = null;
  try {
    const raw = localStorage.getItem('interflon_questionnaire_full_data') || localStorage.getItem('interflon_last_questionnaire_data');
    if (raw) qData = JSON.parse(raw);
  } catch (e) {}

  let surveyConfig = window.currentSurveyRasterConfig || null;
  if (!surveyConfig) {
    try {
      const rawCfg = localStorage.getItem('interflon_survey_raster_config');
      if (rawCfg) surveyConfig = JSON.parse(rawCfg);
    } catch (e) {}
  }

  let machineName = (qData && qData.general && qData.general.machineName) ||
                    (surveyConfig && surveyConfig.machineName) ||
                    localStorage.getItem('tech_machine') ||
                    (document.getElementById('techMachine') ? document.getElementById('techMachine').value : '') ||
                    'Machine';

  let bearings = [];
  let bearingPositions = {};
  let devices = [];
  let machineRangeMeters = 10;
  let layoutViewMode = '3d';
  let showCentralPoint = true;

  if (qData && qData.raster && qData.raster.bearingPositions) {
    bearingPositions = JSON.parse(JSON.stringify(qData.raster.bearingPositions));
    machineRangeMeters = qData.raster.machineRangeMeters || 10;
    layoutViewMode = qData.raster.layoutViewMode || '3d';
    showCentralPoint = qData.raster.showCentralPoint !== false;
    devices = (qData.raster.devices && Array.isArray(qData.raster.devices)) ? JSON.parse(JSON.stringify(qData.raster.devices)) : [];
    if (qData.bearings && Array.isArray(qData.bearings)) {
      bearings = JSON.parse(JSON.stringify(qData.bearings));
    }
  } else if (surveyConfig && surveyConfig.bearings) {
    bearings = JSON.parse(JSON.stringify(surveyConfig.bearings));
    if (surveyConfig.devices && Array.isArray(surveyConfig.devices)) {
      devices = JSON.parse(JSON.stringify(surveyConfig.devices));
    }
  }

  // Ensure devices have assignedBearingLetters mapped if available in surveyRasterConfig or surveyConfig
  const cfgDevs = (surveyConfig && Array.isArray(surveyConfig.devices))
    ? surveyConfig.devices
    : (qData && qData.surveyRasterConfig && Array.isArray(qData.surveyRasterConfig.devices) ? qData.surveyRasterConfig.devices : []);

  if (cfgDevs.length > 0) {
    devices.forEach((d, idx) => {
      if (!d.assignedBearingLetters || d.assignedBearingLetters.length === 0) {
        const match = cfgDevs.find(sc => sc.surveyId === d.id || sc.id === d.short || sc.name === d.name || sc.index === idx);
        if (match && match.bearingLetters && match.bearingLetters.length > 0) {
          d.assignedBearingLetters = [...match.bearingLetters];
        }
      }
    });
  }

  const LETTERS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L'];
  const PRESET_COORDS = [
    { x: -2.4, y: 1.8 },
    { x: 2.4, y: 1.8 },
    { x: -2.4, y: -1.8 },
    { x: 2.2, y: -1.8 },
    { x: 0.0, y: 2.8 },
    { x: 0.0, y: -2.8 },
    { x: -3.5, y: 0.0 },
    { x: 3.5, y: 0.0 }
  ];

  const currentBearingInput = document.getElementById('bearingSearchInput') || document.getElementById('inputBearingNumber');
  const currentBearingNr = currentBearingInput ? currentBearingInput.value.trim() : '22225';

  const autoDevSelect = document.getElementById('automationDeviceSelect') || document.getElementById('autoDeviceSelect');
  const devKey = autoDevSelect ? autoDevSelect.value : 'pulsarlube_m2';
  const isSinglePoint = (devKey === 'single_point');
  const totalPts = isSinglePoint 
    ? (window.spNumBearingsValue || 4) 
    : (typeof autoDevicesState !== 'undefined' && autoDevicesState[0] ? autoDevicesState.reduce((sum, d) => sum + (d.points || 1), 0) : 4);

  if (bearings.length === 0) {
    const ptsCount = Math.min(8, Math.max(1, totalPts));
    for (let i = 0; i < ptsCount; i++) {
      const letter = LETTERS[i];
      bearings.push({
        letter: letter,
        nr: currentBearingNr || '22225',
        desc: `Lager ${letter}`,
        qty: '1'
      });
      if (!bearingPositions[letter]) {
        bearingPositions[letter] = { ...PRESET_COORDS[i % PRESET_COORDS.length] };
      }
    }
  } else {
    bearings.forEach((b, idx) => {
      const l = b.letter || LETTERS[idx];
      if (!bearingPositions[l]) {
        bearingPositions[l] = { ...PRESET_COORDS[idx % PRESET_COORDS.length] };
      }
    });
  }

  if (devices.length === 0) {
    const numDevs = typeof getActiveNumDevices === 'function' ? getActiveNumDevices() : 1;
    for (let i = 0; i < numDevs; i++) {
      let devName = "Toestel 1 • Pulsarlube M2";
      if (devKey === "single_point") devName = "Interflon Single Point Lubricator";
      else if (devKey === "pulsarlube_msp_ac") devName = "Toestel 1 • Pulsarlube MSP AC";
      else if (devKey === "pulsarlube_msp_dc" || devKey === "pulsarlube_msp") devName = "Toestel 1 • Pulsarlube MSP DC";
      else if (devKey === "pulsarlube_plc") devName = "Toestel 1 • Pulsarlube PLC";

      devices.push({
        id: `dev-${i+1}`,
        name: `Toestel ${i+1}`,
        short: `T${i+1}`,
        type: devKey,
        active: true,
        x: (numDevs === 1) ? 2.1 : (i === 0 ? -2.0 : 2.0),
        y: (numDevs === 1) ? -0.8 : 0,
        paletteIndex: i
      });
    }
  }

  return {
    machineName,
    machineRangeMeters,
    layoutViewMode,
    showCentralPoint,
    showBearingDistances: (surveyConfig && surveyConfig.showBearingDistances) || (qData && qData.raster && qData.raster.showBearingDistances) || false,
    bearingPositions,
    devices,
    bearings,
    surveyRasterConfig: (surveyConfig || (qData && qData.surveyRasterConfig) || null)
  };
}

function generateMachineRasterImageDataUrl(rasterData, customZoom = null) {
  try {
    const canvas = document.createElement('canvas');
    const width = 1600;
    const height = 1000;
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;

    // 1. Dark Blueprint/CAD Background
    ctx.fillStyle = '#090e17';
    ctx.fillRect(0, 0, width, height);

    const is3D = (rasterData.layoutViewMode === '3d');
    const gridRange = rasterData.machineRangeMeters || 10;
    const optimalZoom = customZoom || calculateOptimalRasterZoom(
      rasterData.bearingPositions,
      rasterData.devices,
      rasterData.showCentralPoint,
      gridRange,
      rasterData.layoutViewMode
    );

    const padY = 70;
    const padX = 90;
    const availH = height - padY * 2;
    const availW = width - padX * 2;

    let basePpm;
    if (is3D) {
      const ppmH = availH / (2 * gridRange);
      const ppmW = availW / (3.464 * gridRange);
      basePpm = Math.min(ppmH, ppmW);
    } else {
      basePpm = Math.min(availW, availH) / (2 * gridRange);
    }

    const ppm = basePpm * optimalZoom;
    const cx = width / 2;
    const cy = height / 2;

    function worldToScreen(x, y) {
      if (!is3D) {
        return { u: cx + x * ppm, v: cy - y * ppm };
      }
      const cos30 = 0.866;
      const sin30 = 0.5;
      const u = cx + (x - y) * cos30 * ppm;
      const v = cy - (x + y) * sin30 * ppm;
      return { u, v };
    }

    // 2. Machine Floor Grid
    if (is3D) {
      const pTop = worldToScreen(gridRange, gridRange);
      const pRight = worldToScreen(gridRange, -gridRange);
      const pBottom = worldToScreen(-gridRange, -gridRange);
      const pLeft = worldToScreen(-gridRange, gridRange);

      ctx.beginPath();
      ctx.moveTo(pTop.u, pTop.v);
      ctx.lineTo(pRight.u, pRight.v);
      ctx.lineTo(pBottom.u, pBottom.v);
      ctx.lineTo(pLeft.u, pLeft.v);
      ctx.closePath();
      ctx.fillStyle = '#0c1322';
      ctx.fill();
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 2.5;
      ctx.stroke();

      // Isometric Grid Lines
      const step = gridRange <= 6 ? 1 : gridRange <= 15 ? 2 : gridRange <= 30 ? 5 : gridRange <= 60 ? 10 : 20;
      ctx.lineWidth = 1.2;
      for (let m = -gridRange; m <= gridRange; m += step) {
        const isCenter = Math.abs(m) < 0.01;
        ctx.strokeStyle = isCenter ? 'rgba(148, 163, 184, 0.45)' : 'rgba(51, 65, 85, 0.45)';

        const l1 = worldToScreen(-gridRange, m);
        const l2 = worldToScreen(gridRange, m);
        ctx.beginPath();
        ctx.moveTo(l1.u, l1.v);
        ctx.lineTo(l2.u, l2.v);
        ctx.stroke();

        const l3 = worldToScreen(m, -gridRange);
        const l4 = worldToScreen(m, gridRange);
        ctx.beginPath();
        ctx.moveTo(l3.u, l3.v);
        ctx.lineTo(l4.u, l4.v);
        ctx.stroke();
      }

      // Concentric distance guide rings with meter tags
      const ringStep = gridRange <= 6 ? 1 : gridRange <= 12 ? 2 : gridRange <= 20 ? 4 : gridRange <= 30 ? 5 : gridRange <= 60 ? 10 : 20;
      for (let r = ringStep; r <= gridRange; r += ringStep) {
        ctx.beginPath();
        for (let angle = 0; angle <= Math.PI * 2 + 0.1; angle += 0.08) {
          const rx = Math.cos(angle) * r;
          const ry = Math.sin(angle) * r;
          const pt = worldToScreen(rx, ry);
          if (angle === 0) ctx.moveTo(pt.u, pt.v);
          else ctx.lineTo(pt.u, pt.v);
        }
        ctx.strokeStyle = 'rgba(56, 189, 248, 0.22)';
        ctx.setLineDash([6, 6]);
        ctx.stroke();
        ctx.setLineDash([]);

        const lblPt = worldToScreen(r, 0);
        ctx.font = 'bold 15px sans-serif';
        ctx.fillStyle = 'rgba(56, 189, 248, 0.7)';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'bottom';
        ctx.fillText(r + 'm', lblPt.u + 6, lblPt.v - 3);
      }
    } else {
      // 2D Blueprint Grid
      ctx.fillStyle = '#0c1322';
      ctx.fillRect(cx - gridRange * ppm, cy - gridRange * ppm, gridRange * 2 * ppm, gridRange * 2 * ppm);
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 2.5;
      ctx.strokeRect(cx - gridRange * ppm, cy - gridRange * ppm, gridRange * 2 * ppm, gridRange * 2 * ppm);

      const step = gridRange <= 6 ? 1 : gridRange <= 15 ? 2 : gridRange <= 30 ? 5 : gridRange <= 60 ? 10 : 20;
      ctx.lineWidth = 1.2;
      for (let m = -gridRange; m <= gridRange; m += step) {
        ctx.strokeStyle = Math.abs(m) < 0.01 ? 'rgba(148, 163, 184, 0.45)' : 'rgba(51, 65, 85, 0.45)';
        ctx.beginPath();
        ctx.moveTo(cx - gridRange * ppm, cy - m * ppm);
        ctx.lineTo(cx + gridRange * ppm, cy - m * ppm);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(cx + m * ppm, cy - gridRange * ppm);
        ctx.lineTo(cx + m * ppm, cy + gridRange * ppm);
        ctx.stroke();
      }
    }

    // 3. Active Origins (Central Point & Devices)
    const activeOrigins = [];
    if (rasterData.showCentralPoint) {
      activeOrigins.push({
        id: 'cp',
        name: 'Centraal Punt',
        short: 'Centraal',
        type: 'cp',
        x: 0,
        y: 0,
        lineColor: '#ef4444',
        tagBg: 'rgba(220, 38, 38, 0.94)',
        tagBorder: '#ef4444',
        tagText: '#ffffff'
      });
    }

    const DEVICE_PALETTES = [
      { color: '#ea580c', line: '#fb923c', tagBg: 'rgba(154, 52, 18, 0.95)' },
      { color: '#059669', line: '#34d399', tagBg: 'rgba(6, 78, 59, 0.95)' },
      { color: '#7c3aed', line: '#c084fc', tagBg: 'rgba(91, 33, 182, 0.95)' },
      { color: '#0d9488', line: '#2dd4bf', tagBg: 'rgba(19, 78, 74, 0.95)' }
    ];

    (rasterData.devices || []).forEach((dev, devIdx) => {
      if (dev.active !== false) {
        const pal = DEVICE_PALETTES[devIdx % DEVICE_PALETTES.length];
        activeOrigins.push({
          id: dev.id,
          name: dev.name || `Toestel ${devIdx + 1}`,
          short: dev.short || `T${devIdx + 1}`,
          type: dev.type,
          targetBearingLetter: dev.targetBearingLetter,
          assignedBearingLetters: dev.assignedBearingLetters || null,
          x: dev.x || 0,
          y: dev.y || 0,
          lineColor: pal.line,
          tagBg: pal.tagBg,
          tagBorder: pal.line,
          tagText: '#ffffff'
        });
      }
    });

    // 4. Connecting Lines & Distance Badges
    activeOrigins.forEach((origin, origIdx) => {
      const isSinglePoint = (origin.type === 'single_point');

      rasterData.bearings.forEach((b, bIdx) => {
        const letter = b.letter || String.fromCharCode(65 + bIdx);
        const pos = rasterData.bearingPositions[letter] || { x: 0, y: 0 };
        const distM = Math.hypot(pos.x - origin.x, pos.y - origin.y);

        if (isSinglePoint) {
          if (origin.targetBearingLetter && origin.targetBearingLetter !== letter) return;
          if (distM < 0.15) return;
        }

        // For multi-device: only connect to assigned bearings!
        if (origin.id !== 'cp' && origin.type !== 'cp') {
          const activeDevices = (rasterData.devices || []).filter(d => d.active !== false);
          if (activeDevices.length > 1) {
            let isAssigned = false;
            const anyExplicit = activeDevices.some(d => d.assignedBearingLetters && Array.isArray(d.assignedBearingLetters) && d.assignedBearingLetters.length > 0);
            if (anyExplicit) {
              isAssigned = (origin.assignedBearingLetters && Array.isArray(origin.assignedBearingLetters) && origin.assignedBearingLetters.includes(letter));
            } else {
              let closestDevId = null;
              let minD = Infinity;
              activeDevices.forEach(d => {
                const dDist = Math.hypot(pos.x - (d.x || 0), pos.y - (d.y || 0));
                if (dDist < minD) {
                  minD = dDist;
                  closestDevId = d.id;
                }
              });
              isAssigned = (closestDevId === origin.id);
            }
            if (!isAssigned) return;
          }
        }

        const origScreen = worldToScreen(origin.x, origin.y);
        const bScreen = worldToScreen(pos.x, pos.y);

        // Draw line
        ctx.beginPath();
        ctx.moveTo(origScreen.u, origScreen.v);
        ctx.lineTo(bScreen.u, bScreen.v);
        ctx.strokeStyle = origin.lineColor;
        ctx.lineWidth = 2.2;
        ctx.setLineDash([8, 6]);
        ctx.stroke();
        ctx.setLineDash([]);

        // Badge along line
        const offsetRatio = activeOrigins.length > 1 ? (0.42 + (origIdx * 0.16)) : 0.5;
        const midU = origScreen.u + (bScreen.u - origScreen.u) * offsetRatio;
        const midV = origScreen.v + (bScreen.v - origScreen.v) * offsetRatio;

        const distStr = (activeOrigins.length > 1 ? (origin.short + ': ') : '') + distM.toFixed(1).replace('.', ',') + ' m';

        ctx.font = 'bold 15px sans-serif';
        const textWidth = ctx.measureText(distStr).width;
        const padW = 8;
        const padH = 4;

        ctx.fillStyle = origin.tagBg;
        ctx.beginPath();
        if (ctx.roundRect) {
          ctx.roundRect(midU - textWidth/2 - padW, midV - 11 - padH, textWidth + padW*2, 22 + padH*2, 5);
        } else {
          ctx.rect(midU - textWidth/2 - padW, midV - 11 - padH, textWidth + padW*2, 22 + padH*2);
        }
        ctx.fill();
        ctx.strokeStyle = origin.tagBorder;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        ctx.fillStyle = origin.tagText;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(distStr, midU, midV);
      });
    });

    // 4B. Inter-Bearing Distance Lines & Badges (Afstand Lagers)
    if (rasterData.showBearingDistances && Array.isArray(rasterData.bearings) && rasterData.bearings.length >= 2) {
      const bList = rasterData.bearings.map((b, idx) => {
        const letter = b.letter || String.fromCharCode(65 + idx);
        const pos = (rasterData.bearingPositions && rasterData.bearingPositions[letter]) ? rasterData.bearingPositions[letter] : { x: 0, y: 0 };
        return { letter, x: pos.x, y: pos.y };
      });

      const edges = [];
      const n = bList.length;
      if (n === 2) {
        edges.push({ from: bList[0].letter, to: bList[1].letter });
      } else if (n === 3) {
        edges.push(
          { from: bList[0].letter, to: bList[1].letter },
          { from: bList[1].letter, to: bList[2].letter },
          { from: bList[0].letter, to: bList[2].letter }
        );
      } else {
        const edgeSet = new Set();
        const addE = (f, t) => {
          const k = f < t ? (f + '-' + t) : (t + '-' + f);
          if (!edgeSet.has(k)) { edgeSet.add(k); edges.push({ from: f, to: t }); }
        };
        for (let i = 0; i < n - 1; i++) addE(bList[i].letter, bList[i + 1].letter);

        const allP = [];
        for (let i = 0; i < n; i++) {
          for (let j = i + 1; j < n; j++) {
            allP.push({ i, j, f: bList[i].letter, t: bList[j].letter, d: Math.hypot(bList[i].x - bList[j].x, bList[i].y - bList[j].y) });
          }
        }
        allP.sort((a, b) => a.d - b.d);
        const parent = Array.from({ length: n }, (_, i) => i);
        const findR = (x) => parent[x] === x ? x : (parent[x] = findR(parent[x]));
        for (const p of allP) {
          const r1 = findR(p.i); const r2 = findR(p.j);
          if (r1 !== r2) { parent[r1] = r2; addE(p.f, p.t); }
        }
      }

      edges.forEach(edge => {
        const b1 = bList.find(b => b.letter === edge.from);
        const b2 = bList.find(b => b.letter === edge.to);
        if (!b1 || !b2) return;
        const distM = Math.hypot(b2.x - b1.x, b2.y - b1.y);
        const s1 = worldToScreen(b1.x, b1.y);
        const s2 = worldToScreen(b2.x, b2.y);

        ctx.beginPath();
        ctx.moveTo(s1.u, s1.v);
        ctx.lineTo(s2.u, s2.v);
        ctx.strokeStyle = '#38bdf8';
        ctx.lineWidth = 2.4;
        ctx.setLineDash([8, 6]);
        ctx.stroke();
        ctx.setLineDash([]);

        const midU = (s1.u + s2.u) / 2;
        const midV = (s1.v + s2.v) / 2;
        const distStr = edge.from + ' ↔ ' + edge.to + ': ' + distM.toFixed(1).replace('.', ',') + ' m';
        ctx.font = 'bold 15px sans-serif';
        const textWidth = ctx.measureText(distStr).width;
        const padW = 8;
        const padH = 4;

        ctx.fillStyle = 'rgba(8, 47, 73, 0.94)';
        ctx.beginPath();
        if (ctx.roundRect) {
          ctx.roundRect(midU - textWidth / 2 - padW, midV - 11 - padH, textWidth + padW * 2, 22 + padH * 2, 5);
        } else {
          ctx.rect(midU - textWidth / 2 - padW, midV - 11 - padH, textWidth + padW * 2, 22 + padH * 2);
        }
        ctx.fill();
        ctx.strokeStyle = '#38bdf8';
        ctx.lineWidth = 1.5;
        ctx.stroke();

        ctx.fillStyle = '#e0f2fe';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(distStr, midU, midV);
      });
    }

    // 5. Central Reference Point (0,0)
    if (rasterData.showCentralPoint) {
      const centerScreen = worldToScreen(0, 0);

      // Outer glow
      ctx.beginPath();
      ctx.arc(centerScreen.u, centerScreen.v, 22, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(227, 6, 19, 0.25)';
      ctx.fill();

      // Red circle
      ctx.beginPath();
      ctx.arc(centerScreen.u, centerScreen.v, 12, 0, Math.PI * 2);
      ctx.fillStyle = '#E30613';
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 3;
      ctx.stroke();

      // White dot
      ctx.beginPath();
      ctx.arc(centerScreen.u, centerScreen.v, 4.5, 0, Math.PI * 2);
      ctx.fillStyle = '#ffffff';
      ctx.fill();

      // Label below
      ctx.font = 'bold 16px sans-serif';
      ctx.fillStyle = '#ffffff';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      ctx.fillText('Centraal Punt (0,0)', centerScreen.u, centerScreen.v + 18);
    }

    // 6. Extra Devices (Toestellen)
    (rasterData.devices || []).forEach((dev, devIdx) => {
      if (dev.active === false) return;
      const pal = DEVICE_PALETTES[devIdx % DEVICE_PALETTES.length];
      const dScreen = worldToScreen(dev.x || 0, dev.y || 0);
      const dSize = 44;

      // Ground shadow
      ctx.beginPath();
      ctx.ellipse(dScreen.u, dScreen.v + 6, dSize * 0.55, dSize * 0.28, 0, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
      ctx.fill();

      // Rounded Hexagon / Squircle
      ctx.beginPath();
      if (ctx.roundRect) {
        ctx.roundRect(dScreen.u - dSize/2, dScreen.v - dSize/2, dSize, dSize, 10);
      } else {
        ctx.rect(dScreen.u - dSize/2, dScreen.v - dSize/2, dSize, dSize);
      }
      const grad = ctx.createLinearGradient(dScreen.u - dSize/2, dScreen.v - dSize/2, dScreen.u + dSize/2, dScreen.v + dSize/2);
      grad.addColorStop(0, pal.line);
      grad.addColorStop(1, pal.color);
      ctx.fillStyle = grad;
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2.8;
      ctx.stroke();

      // Text inside device
      ctx.font = 'bold 18px sans-serif';
      ctx.fillStyle = '#ffffff';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(dev.short || `T${devIdx+1}`, dScreen.u, dScreen.v);

      // Label badge underneath
      let devNameText = dev.name || `Toestel ${devIdx+1}`;
      if (dev.type === 'pulsarlube_m2') devNameText += ' • Pulsarlube M2';
      else if (dev.type === 'pulsarlube_msp_ac') devNameText += ' • Pulsarlube MSP AC';
      else if (dev.type === 'pulsarlube_msp_dc' || dev.type === 'pulsarlube_msp') devNameText += ' • Pulsarlube MSP DC';
      else if (dev.type === 'pulsarlube_plc') devNameText += ' • Pulsarlube PLC';
      else if (dev.type === 'single_point') devNameText = 'Interflon Single Point';

      ctx.font = 'bold 15px sans-serif';
      const devTagW = ctx.measureText(devNameText).width;
      const padX = 8;
      const padY = 4;

      ctx.fillStyle = 'rgba(15, 23, 42, 0.94)';
      ctx.beginPath();
      if (ctx.roundRect) {
        ctx.roundRect(dScreen.u - devTagW/2 - padX, dScreen.v + dSize/2 + 6, devTagW + padX*2, 22 + padY, 5);
      } else {
        ctx.rect(dScreen.u - devTagW/2 - padX, dScreen.v + dSize/2 + 6, devTagW + padX*2, 22 + padY);
      }
      ctx.fill();
      ctx.strokeStyle = pal.line;
      ctx.lineWidth = 1.5;
      ctx.stroke();

      ctx.fillStyle = '#ffffff';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(devNameText, dScreen.u, dScreen.v + dSize/2 + 18);
    });

    // 7. Bearing Nodes (A, B, C, D...)
    rasterData.bearings.forEach((b, bIdx) => {
      const letter = b.letter || String.fromCharCode(65 + bIdx);
      const pos = rasterData.bearingPositions[letter] || { x: 0, y: 0 };
      const bScreen = worldToScreen(pos.x, pos.y);
      const radius = 22;

      // Ground shadow
      ctx.beginPath();
      ctx.ellipse(bScreen.u, bScreen.v + 5, radius, radius * 0.5, 0, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
      ctx.fill();

      // 3D sphere gradient
      const grad = ctx.createRadialGradient(
        bScreen.u - radius * 0.3, bScreen.v - radius * 0.3, radius * 0.1,
        bScreen.u, bScreen.v, radius
      );
      grad.addColorStop(0, '#60a5fa');
      grad.addColorStop(1, '#1d4ed8');

      ctx.beginPath();
      ctx.arc(bScreen.u, bScreen.v, radius, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Letter inside node
      ctx.font = 'bold 19px sans-serif';
      ctx.fillStyle = '#ffffff';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(letter, bScreen.u, bScreen.v);

      // Pill label underneath node: "Lager A: 22225"
      const nrStr = b.nr || (document.getElementById('bearingSearchInput')?.value.trim()) || "22225";
      const labelText = `Lager ${letter}: ${nrStr}`;

      ctx.font = 'bold 16px sans-serif';
      const tagWidth = ctx.measureText(labelText).width;
      const tagPad = 8;
      const tagHeight = 24;

      ctx.fillStyle = 'rgba(15, 23, 42, 0.92)';
      ctx.beginPath();
      if (ctx.roundRect) {
        ctx.roundRect(bScreen.u - tagWidth/2 - tagPad, bScreen.v + radius + 7, tagWidth + tagPad*2, tagHeight, 5);
      } else {
        ctx.rect(bScreen.u - tagWidth/2 - tagPad, bScreen.v + radius + 7, tagWidth + tagPad*2, tagHeight);
      }
      ctx.fill();
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 1.5;
      ctx.stroke();

      ctx.fillStyle = '#f8fafc';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(labelText, bScreen.u, bScreen.v + radius + 19);
    });

    // 8. Top In-Canvas Header Bar
    ctx.fillStyle = 'rgba(15, 23, 42, 0.88)';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(24, 20, 680, 48, 8);
    else ctx.rect(24, 20, 680, 48);
    ctx.fill();
    ctx.strokeStyle = 'rgba(51, 65, 85, 0.7)';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Green Dot
    ctx.beginPath();
    ctx.arc(44, 44, 7, 0, Math.PI * 2);
    ctx.fillStyle = '#10b981';
    ctx.fill();

    // Header Title
    ctx.font = 'bold 18px sans-serif';
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText('Interactief Machineraster', 62, 44);

    // Range Badge
    ctx.fillStyle = 'rgba(30, 41, 59, 0.9)';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(300, 30, 110, 28, 4);
    else ctx.rect(300, 30, 110, 28);
    ctx.fill();
    ctx.strokeStyle = '#38bdf8';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 13.5px sans-serif';
    ctx.fillStyle = '#38bdf8';
    ctx.textAlign = 'center';
    ctx.fillText(`Bereik: ${gridRange} m`, 355, 44);

    // Auto-Zoom Badge
    const zoomPct = Math.round(optimalZoom * 100);
    ctx.fillStyle = 'rgba(6, 78, 59, 0.85)';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(420, 30, 268, 28, 4);
    else ctx.rect(420, 30, 268, 28);
    ctx.fill();
    ctx.strokeStyle = '#34d399';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 13.5px sans-serif';
    ctx.fillStyle = '#34d399';
    ctx.textAlign = 'center';
    ctx.fillText(`Auto-Zoom: ${zoomPct}% (Optimale Leesbaarheid)`, 554, 44);

    // 9. Bottom Legend Bar
    ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(24, height - 56, 520, 36, 6);
    else ctx.rect(24, height - 56, 520, 36);
    ctx.fill();
    ctx.strokeStyle = 'rgba(51, 65, 85, 0.6)';
    ctx.lineWidth = 1.2;
    ctx.stroke();

    // Red Legend Dot: Centraal Smeerpunt
    ctx.beginPath();
    ctx.arc(42, height - 38, 6, 0, Math.PI * 2);
    ctx.fillStyle = '#E30613';
    ctx.fill();
    ctx.font = 'bold 13.5px sans-serif';
    ctx.fillStyle = '#f8fafc';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText('Centraal Punt (0,0)', 56, height - 38);

    // Blue Legend Dot: Lagers
    ctx.beginPath();
    ctx.arc(225, height - 38, 6, 0, Math.PI * 2);
    ctx.fillStyle = '#3b82f6';
    ctx.fill();
    ctx.fillText('Lagers (Smeerpunten)', 239, height - 38);

    // Orange Legend Dot: Toestel
    ctx.fillStyle = '#ea580c';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(410, height - 44, 12, 12, 3);
    else ctx.rect(410, height - 44, 12, 12);
    ctx.fill();
    ctx.fillText('Smeertoestel', 430, height - 38);

    // Cyan Legend Bar: Afstand Lagers
    if (rasterData.showBearingDistances) {
      ctx.fillStyle = '#38bdf8';
      ctx.beginPath();
      if (ctx.roundRect) ctx.roundRect(550, height - 40, 16, 4, 2);
      else ctx.rect(550, height - 40, 16, 4);
      ctx.fill();
      ctx.fillStyle = '#f8fafc';
      ctx.fillText('Afstand Lagers', 574, height - 38);
    }

    return canvas.toDataURL('image/png');
  } catch (err) {
    console.error('Error generating raster image:', err);
    return null;
  }
}

function addMachineRasterPdfPage(doc, dateString, watermarkDataUrl, aspectRatio) {
  doc.addPage();
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();

  // 1. Watermark logo
  if (watermarkDataUrl && aspectRatio) {
    const imgWidth = 160;
    const imgHeight = 160 * aspectRatio;
    const x = (pageWidth - imgWidth) / 2;
    const y = (pageHeight - imgHeight) / 2;
    try {
      doc.addImage(watermarkDataUrl, "JPEG", x, y, imgWidth, imgHeight);
    } catch(e) {}
  }

  // 2. Header
  doc.setFillColor(227, 6, 19);
  doc.rect(20, 15, 170, 2, "F");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(13);
  doc.setTextColor(227, 6, 19);
  doc.text("INTERFLON 3D MACHINERASTER & INSTALLATIE LAY-OUT", 20, 24);

  // Retrieve active raster & questionnaire data
  const rasterData = getActiveMachineRasterData();

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.setTextColor(100, 100, 100);
  const subTitle = `Machine: ${rasterData.machineName || "Machine"} • Ruimtelijke opstelling smeerpunten, leidingafstanden & toestelposities`;
  doc.text(subTitle, 20, 29);

  doc.setDrawColor(220, 220, 220);
  doc.setLineWidth(0.3);
  doc.line(20, 32, 190, 32);

  // 3. Render High-Resolution Auto-Zoomed 3D Machineraster Image
  const rasterImgDataUrl = generateMachineRasterImageDataUrl(rasterData);

  const rasterBoxX = 20;
  const rasterBoxY = 35;
  const rasterBoxW = 170;
  const rasterBoxH = 106;

  // Dark frame background
  doc.setFillColor(11, 17, 32);
  doc.rect(rasterBoxX, rasterBoxY, rasterBoxW, rasterBoxH, "F");

  if (rasterImgDataUrl) {
    try {
      doc.addImage(rasterImgDataUrl, "PNG", rasterBoxX, rasterBoxY, rasterBoxW, rasterBoxH);
    } catch (err) {
      console.warn("Could not add raster image to PDF:", err);
    }
  }

  doc.setDrawColor(203, 213, 225);
  doc.setLineWidth(0.3);
  doc.rect(rasterBoxX, rasterBoxY, rasterBoxW, rasterBoxH, "D");

  // 4. Section Title: Installation Details & Distances Table
  const secY = 145;
  doc.setFillColor(227, 6, 19);
  doc.rect(20, secY, 170, 5, "F");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(7.5);
  doc.setTextColor(255, 255, 255);
  doc.text("INSTALLATIEDETAILS & LEIDINGAFSTANDEN PER SMEERPUNT", 24, secY + 3.6);

  // 5. Table Header
  const tableY = secY + 5.5;
  const thH = 5.5;
  doc.setFillColor(241, 245, 249);
  doc.rect(20, tableY, 170, thH, "F");
  doc.setDrawColor(203, 213, 225);
  doc.setLineWidth(0.2);
  doc.rect(20, tableY, 170, thH, "D");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(6.5);
  doc.setTextColor(51, 65, 85);
  doc.text("PUNT", 23, tableY + 3.8);
  doc.text("LAGER OMSCHRIJVING / TYPE", 38, tableY + 3.8);
  doc.text("TOEGEWEZEN TOESTEL", 94, tableY + 3.8);
  doc.text("LEIDINGAFSTAND", 132, tableY + 3.8);
  doc.text("AFSTAND CP", 154, tableY + 3.8);
  doc.text("STATUS", 172, tableY + 3.8);

  // 6. Table Rows
  let curY = tableY + thH;
  const rh = 5.6;
  let totalLineMeters = 0;
  let maxLineDist = 0;
  const maxRows = 7;
  const displayedBearings = rasterData.bearings.slice(0, maxRows);

  displayedBearings.forEach((b, idx) => {
    const letter = b.letter || String.fromCharCode(65 + idx);
    const pos = rasterData.bearingPositions[letter] || { x: 0, y: 0 };
    
    // Find assigned device
    let assignedDev = null;
    let minDevDist = Infinity;
    const activeDevs = (rasterData.devices || []).filter(d => d.active !== false);

    // 1. Explicit assignment via assignedBearingLetters on device
    activeDevs.forEach(d => {
      if (d.assignedBearingLetters && Array.isArray(d.assignedBearingLetters) && d.assignedBearingLetters.includes(letter)) {
        assignedDev = d;
        minDevDist = Math.hypot(pos.x - (d.x || 0), pos.y - (d.y || 0));
      } else if (d.targetBearingLetter === letter) {
        assignedDev = d;
        minDevDist = Math.hypot(pos.x - (d.x || 0), pos.y - (d.y || 0));
      }
    });

    // 2. Explicit assignment via surveyRasterConfig deviceConfigs
    if (!assignedDev && rasterData.surveyRasterConfig && Array.isArray(rasterData.surveyRasterConfig.devices)) {
      rasterData.surveyRasterConfig.devices.forEach(dc => {
        if (dc.bearingLetters && Array.isArray(dc.bearingLetters) && dc.bearingLetters.includes(letter)) {
          const matchDev = activeDevs.find(d => d.id === dc.surveyId || d.short === dc.id || d.name === dc.name);
          if (matchDev) {
            assignedDev = matchDev;
            minDevDist = Math.hypot(pos.x - (matchDev.x || 0), pos.y - (matchDev.y || 0));
          }
        }
      });
    }

    // 3. Fallback: closest active device
    if (!assignedDev) {
      activeDevs.forEach(d => {
        const dist = Math.hypot(pos.x - (d.x || 0), pos.y - (d.y || 0));
        if (dist < minDevDist) {
          minDevDist = dist;
          assignedDev = d;
        }
      });
    }

    if (!assignedDev && activeDevs.length > 0) {
      assignedDev = activeDevs[0];
      minDevDist = Math.hypot(pos.x - (assignedDev.x || 0), pos.y - (assignedDev.y || 0));
    }

    const distDev = (minDevDist < Infinity) ? minDevDist : 0;
    const distCp = Math.hypot(pos.x, pos.y);

    totalLineMeters += distDev;
    if (distDev > maxLineDist) maxLineDist = distDev;

    // Alternating Row BG
    doc.setFillColor(idx % 2 === 0 ? 255 : 248, idx % 2 === 0 ? 255 : 250, idx % 2 === 0 ? 255 : 252);
    doc.rect(20, curY, 170, rh, "F");
    doc.setDrawColor(226, 232, 240);
    doc.setLineWidth(0.2);
    doc.rect(20, curY, 170, rh, "D");

    // Col 1: Lager Badge
    doc.setFillColor(37, 99, 235);
    doc.roundedRect(22, curY + 1.1, 8, 3.6, 0.8, 0.8, "F");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(6);
    doc.setTextColor(255, 255, 255);
    doc.text(letter, 26, curY + 3.7, { align: "center" });

    // Col 2: Nr & Desc
    const nrStr = b.nr || (document.getElementById('bearingSearchInput')?.value.trim()) || "22225";
    const descStr = b.desc ? ` - ${b.desc}` : "";
    doc.setFont("helvetica", "bold");
    doc.setFontSize(6.5);
    doc.setTextColor(15, 23, 42);
    const fullDesc = (nrStr + descStr).length > 34 ? (nrStr + descStr).substring(0, 32) + "..." : (nrStr + descStr);
    doc.text(fullDesc, 38, curY + 3.8);

    // Col 3: Assigned Device
    doc.setFont("helvetica", "normal");
    doc.setFontSize(6.5);
    doc.setTextColor(30, 41, 59);
    const devNameStr = assignedDev ? `${assignedDev.name} (${assignedDev.short})` : "Toestel 1 (T1)";
    doc.text(devNameStr, 94, curY + 3.8);

    // Col 4: Leidingafstand
    doc.setFont("helvetica", "bold");
    doc.setFontSize(6.8);
    if (distDev <= 6.0) doc.setTextColor(22, 101, 52);
    else doc.setTextColor(194, 65, 12);
    doc.text(`${distDev.toFixed(1).replace('.', ',')} m`, 132, curY + 3.8);

    // Col 5: Afstand CP
    doc.setFont("helvetica", "normal");
    doc.setFontSize(6.5);
    doc.setTextColor(71, 85, 105);
    doc.text(`${distCp.toFixed(1).replace('.', ',')} m`, 154, curY + 3.8);

    // Col 6: Status
    doc.setFont("helvetica", "bold");
    doc.setFontSize(5.8);
    if (distDev < 0.2) {
      doc.setTextColor(37, 99, 235);
      doc.text("Direct op lager", 172, curY + 3.8);
    } else if (distDev <= 6.0) {
      doc.setTextColor(22, 101, 52);
      doc.text("Binnen bereik", 172, curY + 3.8);
    } else {
      doc.setTextColor(194, 65, 12);
      doc.text("Leiding > 6 m", 172, curY + 3.8);
    }

    curY += rh;
  });

  // 7. Summary Cards below Table
  const sumY = curY + 3.5;
  const sumH = 18;
  const colW = 54;

  // Card 1: Totale Leidinglengte
  doc.setFillColor(248, 250, 252);
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.25);
  doc.roundedRect(20, sumY, colW, sumH, 2, 2, "FD");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(5.5);
  doc.setTextColor(100, 116, 139);
  doc.text("TOTALE LEIDINGLENGTE", 24, sumY + 4.5);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(9.5);
  doc.setTextColor(37, 99, 235);
  doc.text(`${totalLineMeters.toFixed(1).replace('.', ',')} meter`, 24, sumY + 10.5);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(5);
  doc.setTextColor(71, 85, 105);
  doc.text("Advies: 6 mm OD polyamide leiding", 24, sumY + 15);

  // Card 2: Maximale Afstand
  doc.setFillColor(248, 250, 252);
  doc.roundedRect(78, sumY, colW, sumH, 2, 2, "FD");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(5.5);
  doc.setTextColor(100, 116, 139);
  doc.text("MAXIMALE LEIDINGAFSTAND", 82, sumY + 4.5);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(9.5);
  if (maxLineDist <= 6.0) doc.setTextColor(22, 101, 52);
  else doc.setTextColor(194, 65, 12);
  doc.text(`${maxLineDist.toFixed(1).replace('.', ',')} meter`, 82, sumY + 10.5);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(5);
  doc.setTextColor(71, 85, 105);
  const maxLineNote = maxLineDist <= 6.0 ? "✓ Binnen veilige pompdruklimiet" : "Bij NLGI 2: gebruik 8 mm leiding";
  doc.text(maxLineNote, 82, sumY + 15);

  // Card 3: Geadviseerde Configuratie
  const card3W = 54;
  doc.setFillColor(254, 242, 242);
  doc.setDrawColor(254, 202, 202);
  doc.roundedRect(136, sumY, card3W, sumH, 2, 2, "FD");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(5.5);
  doc.setTextColor(227, 6, 19);
  doc.text("GEADVISEERDE HARDWARE", 140, sumY + 4.5);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(8.5);
  doc.setTextColor(227, 6, 19);
  const activeDevsCount = (rasterData.devices || []).filter(d => d.active !== false).length || 1;
  const numPtsCount = rasterData.bearings.length || 1;
  doc.text(`${activeDevsCount}x Toestel • ${numPtsCount} Lagers`, 140, sumY + 10.5);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(5);
  doc.setTextColor(127, 29, 29);
  doc.text("Inclusief verdeelblok & koppelingen", 140, sumY + 15);

  // 8. Installation Guidance Notice Box
  const noticeY = sumY + sumH + 3.5;
  const noticeH = 14;
  doc.setFillColor(240, 253, 244);
  doc.setDrawColor(187, 247, 208);
  doc.setLineWidth(0.2);
  doc.roundedRect(20, noticeY, 170, noticeH, 1.5, 1.5, "FD");

  doc.setFillColor(22, 101, 52);
  doc.rect(20, noticeY, 1.5, noticeH, "F");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(6.5);
  doc.setTextColor(22, 101, 52);
  doc.text("Richtlijnen voor installatie van de leidingen:", 24, noticeY + 4.5);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(5.2);
  doc.setTextColor(20, 83, 45);
  const noticeTxt = "Vul alle leidingen vooraf volledig met het aanbevolen Interflon vet vóór aansluiting op de lagers. Houd leidingen zo kort mogelijk en vermijd scherpe bochten (min. buigradius 30 mm). Gebruik bij leidingafstanden boven 6 meter of bij temperaturen onder 0°C een 8 mm leiding om leidingweerstand te minimaliseren.";
  const splitNotice = doc.splitTextToSize(noticeTxt, 162);
  doc.text(splitNotice, 24, noticeY + 8.5);

  // 9. Footer
  const footerY = 268;
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.2);
  doc.line(20, footerY, 190, footerY);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(5.5);
  doc.setTextColor(148, 163, 184);
  const footerText = "De lay-out en afstanden zijn berekend op basis van de ingevoerde coördinaten in het interactief machineraster. Werkelijke leidingroutes kunnen afwijken door obstakels of kabelgoten in de fabriek.";
  doc.text(footerText, 20, footerY + 4);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(7.5);
  doc.setTextColor(227, 6, 19);
  doc.text("INTERFLON - A WORLD WITHOUT FRICTION", 20, footerY + 13);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(7.5);
  doc.setTextColor(100, 116, 139);
  const curPage = doc.internal.getNumberOfPages();
  doc.text(`PAGINA ${curPage} VAN ${curPage}`, 190, footerY + 13, { align: "right" });
}

function onSinglePointNumBearingsChange(val) {
  if (typeof val !== "undefined" && val !== null) {
    window.spNumBearingsValue = Math.max(1, parseInt(val, 10) || 1);
  } else {
    const el = document.getElementById("singlePointNumBearingsInput");
    if (el) window.spNumBearingsValue = Math.max(1, parseInt(el.value, 10) || 1);
  }
  if (typeof updateRoiAutomationPage === "function") {
    updateRoiAutomationPage();
  }
}
window.onSinglePointNumBearingsChange = onSinglePointNumBearingsChange;

function onSinglePointGroupCountChange(devId, val) {
  const count = Math.max(1, parseInt(val, 10) || 1);
  if (typeof autoDevicesState !== 'undefined' && Array.isArray(autoDevicesState)) {
    const dev = autoDevicesState.find(d => d.id === devId);
    if (dev) {
      dev.unitCount = count;
    }
    const total = autoDevicesState.filter(d => d.isSinglePointGroup).reduce((sum, d) => sum + (d.unitCount || 0), 0);
    if (total > 0) {
      window.spNumBearingsValue = total;
    }
  }
  if (typeof calculateAutomationLubrication === "function") {
    calculateAutomationLubrication();
  }
  if (typeof updateRoiAutomationPage === "function") {
    updateRoiAutomationPage();
  }
}
window.onSinglePointGroupCountChange = onSinglePointGroupCountChange;



function getSurveyUrl(options = {}) {
  const opEmail = localStorage.getItem("operator_email") || "";

  let params = new URLSearchParams();
  // Ensure the link always opens a clean, blank questionnaire for clients
  params.set("new", "1");
  params.set("blank", "1");
  params.set("v", Date.now().toString());
  if (typeof currentLang !== "undefined" && currentLang) params.set("lang", currentLang);
  if (opEmail) params.set("contact", opEmail);

  // Only include previous client data if explicitly requested (default is blank for mailing to clients)
  if (options && options.includeClientData) {
    const clientCompany = localStorage.getItem("client_company") || "";
    const clientContact = localStorage.getItem("client_contact") || "";
    const clientEmail = localStorage.getItem("client_email") || "";
    if (clientCompany) params.set("company", clientCompany);
    if (clientContact) params.set("client_contact", clientContact);
    if (clientEmail) params.set("client_email", clientEmail);
  }

  let baseUrl = "https://www.interflonapps.com/vragenlijst.html";
  try {
    if (typeof window !== "undefined" && window.location && window.location.href) {
      baseUrl = new URL("vragenlijst.html", window.location.href).href;
    }
  } catch(e) {}

  return baseUrl + "?" + params.toString();
}

function openSurveyLink(e) {
  if (e) e.preventDefault();

  const curMach = (document.getElementById("techMachineInput") && document.getElementById("techMachineInput").value.trim()) ||
                  (document.getElementById("omTechMachine") && document.getElementById("omTechMachine").value.trim()) ||
                  window.__activeDossierMachine ||
                  localStorage.getItem("tech_machine") || "";
  const curComp = (document.getElementById("clientCompanyInput") && document.getElementById("clientCompanyInput").value.trim()) ||
                  (document.getElementById("omClientCompany") && document.getElementById("omClientCompany").value.trim()) ||
                  window.__activeDossierCompany ||
                  localStorage.getItem("client_company") || "";

  // Make sure questionnaire in localStorage matches the active calculator dossier
  try {
    let q = null;
    const raw = localStorage.getItem('interflon_questionnaire_full_data') || localStorage.getItem('interflon_last_questionnaire_data');
    if (raw) {
      try { q = JSON.parse(raw); } catch(err) {}
    }
    const qMach = (q && q.general && (q.general.machineName || q.general.name)) || '';
    if (!q || (curMach && qMach && curMach.toLowerCase() !== qMach.toLowerCase())) {
      const targetBrand = (document.getElementById("techBrandInput") && document.getElementById("techBrandInput").value.trim()) || "";
      const targetApp = (document.getElementById("techAppInput") && document.getElementById("techAppInput").value.trim()) || "";
      const targetContact = (document.getElementById("clientContactInput") && document.getElementById("clientContactInput").value.trim()) || "";
      const targetPhone = (document.getElementById("clientPhoneInput") && document.getElementById("clientPhoneInput").value.trim()) || "";
      const targetEmail = (document.getElementById("clientEmailInput") && document.getElementById("clientEmailInput").value.trim()) || "";
      const targetOpEmail = (document.getElementById("opEmailInput") && document.getElementById("opEmailInput").value.trim()) || "";
      const newQ = {
        fileType: 'Interflon_Smeeranalyse_Vragenlijst',
        version: '1.0',
        exportDate: new Date().toISOString(),
        source: 'calculator_dossier_import',
        isDossierImport: true,
        general: {
          machineName: curMach || 'Machine',
          machineBrand: targetBrand,
          application: targetApp,
          machineCount: '1'
        },
        contact: {
          clientCompany: curComp,
          clientContact: targetContact,
          clientPhone: targetPhone,
          clientEmail: targetEmail,
          interflonContactEmail: targetOpEmail
        },
        bearings: (window.latestSurveyBearings && window.latestSurveyBearings.length > 0) ? window.latestSurveyBearings : [
          { letter: 'A', nr: 'Lager A', desc: targetApp, rpm: '', pos: 'Horizontaal', qty: 1 }
        ]
      };
      const qJson = JSON.stringify(newQ);
      localStorage.setItem('interflon_questionnaire_full_data', qJson);
      localStorage.setItem('interflon_last_questionnaire_data', qJson);
      if (curMach) localStorage.setItem('interflon_active_dossier_machine', curMach);
      if (curComp) localStorage.setItem('interflon_active_dossier_company', curComp);
    }
  } catch(e) {}

  let targetUrl = 'vragenlijst.html';
  const params = new URLSearchParams();
  if (typeof currentLang !== "undefined" && currentLang) {
    params.set('lang', currentLang);
  }
  if (curMach) params.set('machine', curMach);
  if (curComp) params.set('company', curComp);

  const qs = params.toString();
  if (qs) targetUrl += '?' + qs;
  window.open(targetUrl, '_blank');
}


function printSurveyPage() {
  let targetUrl = 'vragenlijst.html?autoprint=true';
  if (typeof currentLang !== "undefined" && currentLang) {
    targetUrl += '&lang=' + encodeURIComponent(currentLang);
  }
  window.open(targetUrl, '_blank');
}

function copySurveyLink() {
  const url = getSurveyUrl({ includeClientData: false });

  const dummy = document.createElement("textarea");
  dummy.value = url;
  document.body.appendChild(dummy);
  dummy.select();
  try {
    document.execCommand("copy");
  } catch (e) {}
  document.body.removeChild(dummy);

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url).catch(() => {});
  }

  alert("📋 Blanco vragenlijst-link is gekopieerd naar uw klembord!\n\nLink: " + url + "\n\nDeze link opent voor iedere klant gegarandeerd een schone, lege invullijst zonder eerdere testgegevens.\nU kunt deze nu direct plakken (Ctrl + V) in een e-mail naar uw klant.");
}

