function openSurveyEmailModal() {
  const modal = document.getElementById("surveyEmailModal");
  if (!modal) return;
  const textarea = document.getElementById("surveyEmailTextarea");
  
  let surveyUrl = "";
  try {
    if (typeof getSurveyUrl === "function") {
      surveyUrl = getSurveyUrl({ includeClientData: false });
    }
  } catch (e) {}
  
  if (!surveyUrl) {
    const loc = window.location;
    const basePath = loc.pathname.substring(0, loc.pathname.lastIndexOf('/') + 1);
    surveyUrl = loc.origin + basePath + "vragenlijst.html?t=" + Date.now();
  }

  const lang = (typeof currentLang !== "undefined" && currentLang) ? currentLang : "nl";
  let templateText = "";
  if (lang === "fr") {
    templateText = `Cher client,

Faisant suite à notre conversation concernant l'automatisation, je vous transmets comme promis le lien vers le questionnaire :
${surveyUrl}

Je souhaite vous apporter les précisions suivantes :
Après avoir complété les roulements dans la section 1) Détails de la machine & Spécifications des roulements, vous constaterez qu'ils apparaissent automatiquement dans la grille de la machine dans la section 3) Positionnement des roulements & Distances.
Tout ce que vous avez à faire dans la section 3 est de positionner correctement les roulements concernés à l'aide de votre souris, conformément à la situation réelle et aux distances sur la machine. Ce positionnement ne doit absolument pas être mesuré au millimètre près.
Pour le reste, vous n'avez rien à remplir dans la section 3.

Dans les sections 2, 4 et 5, les données doivent être remplies pour chaque roulement séparément, car elles peuvent être différentes. Si des roulements identiques sont présents dans les mêmes conditions, vous pouvez facilement copier un roulement, puis en sélectionner un autre et le coller. Ainsi, vous n'avez pas à tout ressaisir manuellement à chaque fois.

Vous pouvez toujours me joindre par téléphone ou par e-mail pour obtenir de l'aide lors du remplissage.`;
  } else if (lang === "en") {
    templateText = `Dear Customer,

Following our conversation regarding automation, I am sending you the link to the questionnaire as promised:
${surveyUrl}

I would like to provide the following clarification:
After you have filled in the bearings in section 1) Machine details & Bearing specifications, you will notice that they automatically appear in the machine grid in section 3) Bearing Positioning & Machine Distances.
All you need to do in section 3 is position the relevant bearings correctly using your mouse according to the actual situation and distances on the machine. This positioning does not need to be measured perfectly at all.
You do not need to fill in anything else in section 3.

In sections 2, 4, and 5, the data must be filled in for each bearing separately, as these may vary. If there are identical bearings with the same operating conditions, you can simply copy a bearing, then select another bearing and paste. This saves you from having to re-enter everything manually each time.

You can always reach me by phone or email for any assistance with filling it in.`;
  } else {
    templateText = `Geachte klant, 

Naar aanleiding van ons gesprek betreffende automatisatie zend ik u zoals beloofd de link naar de vragenlijst:
${surveyUrl}

Graag geef ik hierbij volgende toelichting:
Nadat u in sectie "1) Machinedetails & Lagerspecificaties" de lagers heeft ingevuld zal u merken dat deze automatisch verschijnen in het machineraster in sectie "3) Positiebepaling Lagers & Afstanden Machine".
Het enige wat u in sectie 3 hoeft te doen is de betreffende lagers met uw muis juist te positioneren in overeenstemming met de reële situatie en afstanden op de machine. Deze positionering hoeft absoluut niet perfect afgemeten te zijn.
Verder hoeft u in sectie "3) Positiebepaling Lagers & Afstanden Machine" niets in te vullen. 

In secties 2, 4 en 5 dienen de data voor elk lager apart te worden ingevuld, aangezien deze afwijkend kunnen zijn. Indien er identieke lagers aanwezig zijn met dezelfde omstandigheden, kan u eenvoudig een lager kopiëren, daarna een ander lager selecteren en plakken. Zo hoeft u niet telkens opnieuw alles manueel in te vullen. 

U kan mij steeds telefonisch of via Email bereiken voor hulp bij het invullen.`;
  }

  if (textarea) {
    textarea.value = templateText;
  }

  const statusEl = document.getElementById("surveyEmailCopyStatus");
  if (statusEl) {
    statusEl.style.opacity = "0";
  }

  modal.classList.remove("hidden");
}

function closeSurveyEmailModal() {
  const modal = document.getElementById("surveyEmailModal");
  if (modal) modal.classList.add("hidden");
}

function copySurveyEmailText() {
  const textarea = document.getElementById("surveyEmailTextarea");
  if (!textarea) return;

  const text = textarea.value;
  textarea.select();
  textarea.setSelectionRange(0, 99999);

  let success = false;
  try {
    success = document.execCommand("copy");
  } catch (e) {}

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      showSurveyEmailCopyFeedback();
    }).catch(() => {
      if (success) showSurveyEmailCopyFeedback();
    });
  } else if (success) {
    showSurveyEmailCopyFeedback();
  }
}

function showSurveyEmailCopyFeedback() {
  const statusEl = document.getElementById("surveyEmailCopyStatus");
  if (statusEl) {
    statusEl.textContent = "✓ Tekst succesvol gekopieerd naar klembord!";
    statusEl.style.opacity = "1";
    setTimeout(() => {
      if (statusEl) statusEl.style.opacity = "0";
    }, 3500);
  }
}

// ==========================================================================
// PHOTO LIBRARY & FOLDERS LOGIC
// ==========================================================================
let photoFolders = [
  { id: "folder_default", name: "Algemeen", photos: [] }
];
let activePhotoFolderId = "folder_default";
let photoLibrary = []; // Maintained for backwards compatibility with active folder

function getCurrentPhotoFolder() {
  if (!photoFolders || !Array.isArray(photoFolders) || photoFolders.length === 0) {
    photoFolders = [{ id: "folder_default", name: "Algemeen", photos: [] }];
  }
  let cur = photoFolders.find(f => f.id === activePhotoFolderId);
  if (!cur) {
    activePhotoFolderId = photoFolders[0].id;
    cur = photoFolders[0];
  }
  if (!cur.photos || !Array.isArray(cur.photos)) {
    cur.photos = [];
  }
  return cur;
}

function getAllPhotosFlat() {
  if (!photoFolders || !Array.isArray(photoFolders)) return [];
  const all = [];
  photoFolders.forEach(f => {
    if (f.photos && Array.isArray(f.photos)) {
      all.push(...f.photos);
    }
  });
  return all;
}

function updatePhotoBadgeCounter() {
  const badgeText = document.getElementById("photoLibraryBadgeText");
  if (!badgeText) return;
  const lang = (typeof currentLang !== "undefined" && currentLang) ? currentLang : "nl";
  let baseText = "Foto bibliotheek";
  if (lang === "fr") baseText = "Photothèque";
  if (lang === "en") baseText = "Photo library";

  const totalPhotos = (photoFolders && Array.isArray(photoFolders))
    ? photoFolders.reduce((sum, f) => sum + ((f.photos && Array.isArray(f.photos)) ? f.photos.length : 0), 0)
    : 0;

  if (totalPhotos > 0) {
    badgeText.innerText = `${baseText} (${totalPhotos})`;
  } else {
    badgeText.innerText = baseText;
  }
}

function loadPhotoLibrary() {
  try {
    const savedFolders = localStorage.getItem("photo_folders") || localStorage.getItem("photoFolders");
    if (savedFolders) {
      const parsed = JSON.parse(savedFolders);
      if (Array.isArray(parsed) && parsed.length > 0) {
        photoFolders = parsed;
      }
    } else {
      // Legacy fallback from flat photo_library
      const savedLegacy = localStorage.getItem("photo_library") || localStorage.getItem("photoLibrary");
      if (savedLegacy) {
        const parsedLegacy = JSON.parse(savedLegacy);
        if (Array.isArray(parsedLegacy) && parsedLegacy.length > 0) {
          if (parsedLegacy[0].photos && Array.isArray(parsedLegacy[0].photos)) {
            photoFolders = parsedLegacy;
          } else {
            photoFolders = [
              { id: "folder_default", name: "Algemeen", photos: parsedLegacy }
            ];
          }
        }
      }
    }
  } catch (e) {
    console.warn("Could not load photo folders from storage:", e);
  }

  if (!photoFolders || !Array.isArray(photoFolders) || photoFolders.length === 0) {
    photoFolders = [{ id: "folder_default", name: "Algemeen", photos: [] }];
  }

  // Ensure each folder has a valid photos array
  photoFolders.forEach(f => {
    if (!f.photos || !Array.isArray(f.photos)) f.photos = [];
  });

  if (!photoFolders.some(f => f.id === activePhotoFolderId)) {
    activePhotoFolderId = photoFolders[0].id;
  }

  photoLibrary = getCurrentPhotoFolder().photos;

  if (typeof window !== "undefined") {
    window.photoFolders = photoFolders;
    window.activePhotoFolderId = activePhotoFolderId;
    window.photoLibrary = photoLibrary;
  }

  renderPhotoFolderTabs();
  renderPhotoGrid();
  updatePhotoBadgeCounter();
}

function savePhotoLibraryToStorage() {
  try {
    const foldersJson = JSON.stringify(photoFolders);
    localStorage.setItem("photo_folders", foldersJson);
    localStorage.setItem("photoFolders", foldersJson);

    // Save flat array for backwards compatibility
    const flatPhotos = getAllPhotosFlat();
    const flatJson = JSON.stringify(flatPhotos);
    localStorage.setItem("photo_library", flatJson);
    localStorage.setItem("photoLibrary", flatJson);
  } catch (e) {
    console.warn("Storage quota exceeded when saving photo library:", e);
  }

  photoLibrary = getCurrentPhotoFolder().photos;

  if (typeof window !== "undefined") {
    window.photoFolders = photoFolders;
    window.activePhotoFolderId = activePhotoFolderId;
    window.photoLibrary = photoLibrary;
  }

  renderPhotoFolderTabs();
  renderPhotoGrid();
  updatePhotoBadgeCounter();
}

function renderPhotoFolderTabs() {
  const tabsList = document.getElementById("photoFolderTabsList");
  if (!tabsList) return;
  tabsList.innerHTML = "";

  if (!photoFolders || !Array.isArray(photoFolders) || photoFolders.length === 0) {
    photoFolders = [{ id: "folder_default", name: "Algemeen", photos: [] }];
  }

  photoFolders.forEach(f => {
    const isActive = f.id === activePhotoFolderId;
    const count = (f.photos && Array.isArray(f.photos)) ? f.photos.length : 0;
    const tabBtn = document.createElement("button");
    tabBtn.type = "button";
    tabBtn.style.cssText = `
      padding: 6px 14px;
      font-size: 12.5px;
      border-radius: 20px;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 6px;
      white-space: nowrap;
      transition: all 0.2s ease;
      ${isActive
        ? "background: #E30613; color: #ffffff; border: 1.5px solid #E30613; font-weight: 700; box-shadow: 0 2px 4px rgba(227,6,19,0.25);"
        : "background: #ffffff; color: #334155; border: 1.5px solid #cbd5e1; font-weight: 600;"}
    `;

    tabBtn.innerHTML = `
      <span>📁</span>
      <span>${f.name}</span>
      <span style="font-size: 11px; padding: 1px 6px; border-radius: 10px; ${isActive ? 'background: rgba(255,255,255,0.25); color: #fff;' : 'background: #f1f5f9; color: #64748b;'}">${count}/20</span>
    `;

    tabBtn.onclick = () => switchPhotoFolder(f.id);
    tabsList.appendChild(tabBtn);
  });
}

function switchPhotoFolder(folderId) {
  if (photoFolders.some(f => f.id === folderId)) {
    activePhotoFolderId = folderId;
    photoLibrary = getCurrentPhotoFolder().photos;
    if (typeof window !== "undefined") {
      window.activePhotoFolderId = activePhotoFolderId;
      window.photoLibrary = photoLibrary;
    }
    renderPhotoFolderTabs();
    renderPhotoGrid();
    renderPhotoFolderManagerList();
  }
}

function promptCreatePhotoFolder() {
  const name = prompt("Geef een naam op voor de nieuwe map (bijv. Lagers, Aandrijving, Inspectie):");
  if (name && name.trim()) {
    createPhotoFolder(name.trim());
  }
}

function createPhotoFolder(name) {
  if (!name || !name.trim()) return;
  const newFolder = {
    id: "folder_" + Date.now() + "_" + Math.random().toString(36).substr(2, 5),
    name: name.trim(),
    photos: []
  };
  photoFolders.push(newFolder);
  activePhotoFolderId = newFolder.id;
  savePhotoLibraryToStorage();
  renderPhotoFolderManagerList();
}

function submitNewPhotoFolder() {
  const input = document.getElementById("newPhotoFolderNameInput");
  if (!input) return;
  const name = input.value ? input.value.trim() : "";
  if (!name) {
    alert("Vul a.u.b. een mapnaam in.");
    input.focus();
    return;
  }
  createPhotoFolder(name);
  input.value = "";
}

function renamePhotoFolder(folderId) {
  const folder = photoFolders.find(f => f.id === folderId);
  if (!folder) return;
  const newName = prompt("Voer de nieuwe naam in voor map '" + folder.name + "':", folder.name);
  if (newName && newName.trim() && newName.trim() !== folder.name) {
    folder.name = newName.trim();
    savePhotoLibraryToStorage();
    renderPhotoFolderManagerList();
  }
}

function deletePhotoFolder(folderId) {
  if (photoFolders.length <= 1) {
    alert("U kunt de enige resterende map niet verwijderen.");
    return;
  }
  const folder = photoFolders.find(f => f.id === folderId);
  if (!folder) return;
  const count = (folder.photos && Array.isArray(folder.photos)) ? folder.photos.length : 0;
  const msg = count > 0
    ? `Weet u zeker dat u de map "${folder.name}" inclusief ${count} foto('s) wilt verwijderen?`
    : `Weet u zeker dat u de lege map "${folder.name}" wilt verwijderen?`;

  if (!confirm(msg)) return;

  photoFolders = photoFolders.filter(f => f.id !== folderId);
  if (activePhotoFolderId === folderId) {
    activePhotoFolderId = photoFolders[0].id;
  }
  savePhotoLibraryToStorage();
  renderPhotoFolderManagerList();
}

function openPhotoFolderManagerModal() {
  renderPhotoFolderManagerList();
  const modal = document.getElementById("photoFolderManagerModal");
  if (modal) modal.classList.remove("hidden");
  setTimeout(() => {
    const input = document.getElementById("newPhotoFolderNameInput");
    if (input) input.focus();
  }, 100);
}

function closePhotoFolderManagerModal() {
  const modal = document.getElementById("photoFolderManagerModal");
  if (modal) modal.classList.add("hidden");
}

function renderPhotoFolderManagerList() {
  const container = document.getElementById("photoFolderManagerList");
  if (!container) return;
  container.innerHTML = "";

  if (!photoFolders || photoFolders.length === 0) {
    container.innerHTML = `<p style="color: #94a3b8; font-size: 13px; text-align: center; margin: 20px 0;">Geen mappen gevonden.</p>`;
    return;
  }

  photoFolders.forEach(f => {
    const isActive = f.id === activePhotoFolderId;
    const count = (f.photos && Array.isArray(f.photos)) ? f.photos.length : 0;

    const row = document.createElement("div");
    row.style.cssText = `
      display: flex;
      align-items: center;
      justify-content: space-between;
      background: ${isActive ? '#fef2f2' : '#ffffff'};
      border: 1.5px solid ${isActive ? '#fca5a5' : '#e2e8f0'};
      border-radius: 8px;
      padding: 10px 14px;
      gap: 10px;
    `;

    row.innerHTML = `
      <div style="display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0;">
        <span style="font-size: 18px;">📁</span>
        <div style="min-width: 0; flex: 1;">
          <div style="display: flex; align-items: center; gap: 8px;">
            <strong style="color: #0f172a; font-size: 13.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${f.name}</strong>
            ${isActive ? '<span style="background: #16a34a; color: #fff; font-size: 10.5px; font-weight: 700; padding: 1px 7px; border-radius: 10px;">Actief</span>' : ''}
          </div>
          <div style="font-size: 12px; color: #64748b; margin-top: 2px;">
            ${count} / 20 foto's
          </div>
        </div>
      </div>
      <div style="display: flex; align-items: center; gap: 6px; flex-shrink: 0;">
        ${!isActive ? `
          <button type="button" class="btn btn-secondary" onclick="switchPhotoFolder('${f.id}'); closePhotoFolderManagerModal();" style="padding: 5px 10px; font-size: 12px; font-weight: 700; border-radius: 6px;">
            Openen
          </button>
        ` : ''}
        <button type="button" class="btn btn-secondary" onclick="renamePhotoFolder('${f.id}')" title="Hernoemen" style="padding: 5px 9px; font-size: 12px; border-radius: 6px;">
          ✏️
        </button>
        ${photoFolders.length > 1 ? `
          <button type="button" class="btn btn-secondary" onclick="deletePhotoFolder('${f.id}')" title="Map verwijderen" style="padding: 5px 9px; font-size: 12px; border-radius: 6px; color: #e11d48; border-color: #fecdd3;">
            🗑️
          </button>
        ` : ''}
      </div>
    `;

    container.appendChild(row);
  });
}

function openPhotoLibraryModal() {
  loadPhotoLibrary();
  const modal = document.getElementById("photoLibraryModal");
  if (modal) modal.classList.remove("hidden");
}

function closePhotoLibraryModal() {
  const modal = document.getElementById("photoLibraryModal");
  if (modal) modal.classList.add("hidden");
}

function handlePhotoUpload(event) {
  const files = event.target.files;
  if (!files || files.length === 0) return;

  const curFolder = getCurrentPhotoFolder();
  const remainingSlots = 20 - (curFolder.photos ? curFolder.photos.length : 0);
  if (remainingSlots <= 0) {
    alert(`U heeft het maximale aantal van 20 foto's bereikt voor map "${curFolder.name}". Maak een nieuwe map aan via de knop 'Mappen' om meer foto's toe te voegen.`);
    event.target.value = "";
    return;
  }

  const filesToProcess = Array.from(files).slice(0, remainingSlots);
  let processedCount = 0;

  filesToProcess.forEach(file => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        let width = img.width;
        let height = img.height;
        const maxDim = 1000;

        if (width > maxDim || height > maxDim) {
          if (width > height) {
            height = Math.round((height * maxDim) / width);
            width = maxDim;
          } else {
            width = Math.round((width * maxDim) / height);
            height = maxDim;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, width, height);

        const compressedDataUrl = canvas.toDataURL("image/jpeg", 0.8);

        curFolder.photos.push({
          id: Date.now() + "_" + Math.random().toString(36).substr(2, 5),
          dataUrl: compressedDataUrl,
          description: "",
          filename: file.name
        });

        processedCount++;
        if (processedCount === filesToProcess.length) {
          event.target.value = "";
          savePhotoLibraryToStorage();
        }
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}

function updatePhotoDescription(id, text) {
  if (!photoFolders || !Array.isArray(photoFolders)) return;
  let found = false;
  for (const f of photoFolders) {
    if (f.photos && Array.isArray(f.photos)) {
      const item = f.photos.find(p => p.id === id);
      if (item) {
        item.description = text;
        found = true;
        break;
      }
    }
  }
  if (found) {
    try {
      const foldersJson = JSON.stringify(photoFolders);
      localStorage.setItem("photo_folders", foldersJson);
      localStorage.setItem("photoFolders", foldersJson);

      const flatPhotos = getAllPhotosFlat();
      const flatJson = JSON.stringify(flatPhotos);
      localStorage.setItem("photo_library", flatJson);
      localStorage.setItem("photoLibrary", flatJson);
    } catch (e) {}
  }
}

function deletePhoto(id) {
  if (!photoFolders || !Array.isArray(photoFolders)) return;
  for (const f of photoFolders) {
    if (f.photos && Array.isArray(f.photos)) {
      f.photos = f.photos.filter(p => p.id !== id);
    }
  }
  savePhotoLibraryToStorage();
}

function clearAllPhotosForNewDossier() {
  const lang = (typeof currentLang !== "undefined" && currentLang) ? currentLang : "nl";
  let confirmMsg = "Weet u zeker dat u alle foto's en mappen wilt wissen om een nieuwe fotobibliotheek te starten voor een nieuw dossier?\n\n(Foto's van reeds opgeslagen dossiers op uw computer blijven veilig bewaard in hun dossierbestand.)";
  if (lang === "fr") {
    confirmMsg = "Êtes-vous sûr de vouloir effacer toutes les photos et tous les dossiers pour démarrer une nouvelle bibliothèque de photos pour un nouveau dossier ?\n\n(Les photos des dossiers déjà enregistrés sur votre ordinateur restent conservées en toute sécurité dans leur fichier de dossier.)";
  } else if (lang === "en") {
    confirmMsg = "Are you sure you want to clear all photos and folders to start a new photo library for a new file?\n\n(Photos from already saved files on your computer remain safely preserved in their file.)";
  }

  if (!confirm(confirmMsg)) {
    return;
  }

  // 1. Reset memory state to initial clean default folder
  photoFolders = [
    { id: "folder_default", name: "Algemeen", photos: [] }
  ];
  activePhotoFolderId = "folder_default";
  photoLibrary = [];

  if (typeof window !== "undefined") {
    window.photoFolders = photoFolders;
    window.activePhotoFolderId = activePhotoFolderId;
    window.photoLibrary = photoLibrary;
  }

  // 2. Clear old photo localStorage entries and TCO application photos
  try {
    localStorage.removeItem("photo_folders");
    localStorage.removeItem("photoFolders");
    localStorage.removeItem("photo_library");
    localStorage.removeItem("photoLibrary");
    if (typeof setBearingTcoImage === "function") setBearingTcoImage("");
    if (typeof setChainTcoImage === "function") setChainTcoImage("");
  } catch (e) {
    console.warn("Could not remove photo keys from localStorage:", e);
  }

  // 3. Persist the clean initial state
  savePhotoLibraryToStorage();

  // 4. Reset file input if present
  const fileInput = document.getElementById("photoFileInput");
  if (fileInput) fileInput.value = "";

  // 5. Update UI components
  if (typeof renderPhotoFolderTabs === "function") renderPhotoFolderTabs();
  if (typeof renderPhotoGrid === "function") renderPhotoGrid();
  if (typeof updatePhotoBadgeCounter === "function") updatePhotoBadgeCounter();
  if (typeof renderPhotoFolderManagerList === "function") renderPhotoFolderManagerList();

  // 6. Show friendly confirmation toast
  const toastMsg = (lang === "fr")
    ? "🗑️ La bibliothèque de photos a été vidée pour un nouveau dossier."
    : (lang === "en"
        ? "🗑️ The photo library has been cleared for a new dossier."
        : "🗑️ De fotobibliotheek is leeggemaakt voor een nieuw dossier.");

  if (typeof showToastNotification === "function") {
    showToastNotification(toastMsg);
  }
}

function renderPhotoGrid() {
  const container = document.getElementById("photoGridContainer");
  const counterText = document.getElementById("photoCounterText");
  var lang = (typeof currentLang !== "undefined" && currentLang) ? currentLang : "nl";
  const t = (typeof TRANSLATIONS !== "undefined" && TRANSLATIONS[lang]) ? TRANSLATIONS[lang] : (typeof TRANSLATIONS !== "undefined" && TRANSLATIONS["nl"] ? TRANSLATIONS["nl"] : {});

  const curFolder = getCurrentPhotoFolder();
  const photos = curFolder.photos || [];
  photoLibrary = photos;

  if (counterText) {
    const uploadedSuffix = lang === "fr" ? "photos téléchargées" : (lang === "en" ? "photos uploaded" : "foto's geüpload");
    counterText.innerText = `${curFolder.name}: ${photos.length} / 20 ${uploadedSuffix}`;
  }

  if (!container) return;
  container.innerHTML = "";

  if (photos.length === 0) {
    container.innerHTML = `
      <div style="grid-column: 1 / -1; text-align: center; color: #94a3b8; padding: 40px 10px; background: #f8fafc; border-radius: 10px; border: 1.5px dashed #cbd5e1;">
        <span style="font-size: 32px; display: block; margin-bottom: 8px;">📷</span>
        <p style="margin: 0; font-size: 14px; font-weight: 600;">Nog geen foto's in map "${curFolder.name}".</p>
        <p style="margin: 4px 0 0 0; font-size: 12.5px;">${t.noPhotosHint || "Klik hierboven op '➕ Foto's toevoegen' om tot 20 foto's toe te voegen."}</p>
      </div>
    `;
    return;
  }

  photos.forEach((photo, idx) => {
    const card = document.createElement("div");
    card.style.cssText = "background: #ffffff; border: 1px solid #cbd5e1; border-radius: 10px; overflow: hidden; box-shadow: 0 2px 6px rgba(0,0,0,0.04); display: flex; flex-direction: column; min-height: 205px; height: auto;";
    const photoBadge = (t.photoLabel || "Foto") + " " + (idx + 1);
    const enlargeTxt = t.enlargeLabel || "🔍 Vergroot";
    const clickTitle = t.clickToEnlarge || "Klik om te vergroten 🔍";
    const descPlaceholder = t.addDescPlaceholder || "Beschrijving toevoegen...";
    const delTitle = t.deletePhotoTitle || "Verwijderen";

    card.innerHTML = `
      <div style="position: relative; width: 100%; height: 140px; min-height: 140px; flex-shrink: 0; background: #000; overflow: hidden;">
        <img src="${photo.dataUrl}" alt="${photoBadge}" onclick="openPhotoLightbox('${photo.id}')" title="${clickTitle}" style="width: 100%; height: 100%; object-fit: cover; cursor: pointer; transition: transform 0.2s;" onmouseover="this.style.transform='scale(1.05)'" onmouseout="this.style.transform='scale(1)'">
        <div onclick="openPhotoLightbox('${photo.id}')" title="${clickTitle}" style="position: absolute; bottom: 6px; right: 6px; background: rgba(15,23,42,0.75); color: #fff; border-radius: 4px; padding: 2px 6px; font-size: 11px; cursor: pointer; pointer-events: auto;">${enlargeTxt}</div>
        <span style="position: absolute; top: 6px; left: 6px; background: rgba(15,23,42,0.75); color: #fff; font-size: 11px; font-weight: 700; padding: 2px 7px; border-radius: 4px;">${photoBadge}</span>
        <button type="button" onclick="deletePhoto('${photo.id}')" title="${delTitle}" style="position: absolute; top: 6px; right: 6px; background: rgba(227,6,19,0.9); color: #fff; border: none; width: 26px; height: 26px; border-radius: 50%; cursor: pointer; font-size: 13px; font-weight: 800; display: flex; align-items: center; justify-content: center;">✕</button>
      </div>
      <div style="padding: 10px; flex: 1 0 auto; display: flex; flex-direction: column; gap: 6px;">
        <input type="text" value="${photo.description || ''}" placeholder="${descPlaceholder}" oninput="updatePhotoDescription('${photo.id}', this.value)" style="width: 100%; padding: 6px 10px; font-size: 12.5px; border: 1px solid #cbd5e1; border-radius: 6px; box-sizing: border-box;">
      </div>
    `;
    container.appendChild(card);
  });
}

function openPhotoLightbox(id) {
  const allPhotos = getAllPhotosFlat();
  const item = allPhotos.find(p => p.id === id);
  if (!item) return;

  const modal = document.getElementById("photoLightboxModal");
  const img = document.getElementById("photoLightboxImg");
  const caption = document.getElementById("photoLightboxCaption");

  if (img) img.src = item.dataUrl;
  if (caption) {
    if (item.description && item.description.trim()) {
      caption.innerText = item.description.trim();
      caption.style.display = "block";
    } else {
      caption.innerText = "";
      caption.style.display = "none";
    }
  }
  if (modal) modal.classList.remove("hidden");
}

function closePhotoLightboxModal() {
  const modal = document.getElementById("photoLightboxModal");
  if (modal) modal.classList.add("hidden");
}

