function sanitizeFilename(str) {
  if (!str) return "";
  return str.toString()
    .trim()
    .replace(/[^a-zA-Z0-9_\-\s]/g, "")
    .replace(/\s+/g, "_");
}

function showToastNotification(message, isError = false) {
  let toast = document.getElementById("appToastNotification");
  if (!toast) {
    toast = document.createElement("div");
    toast.id = "appToastNotification";
    toast.style.cssText = "position: fixed; bottom: 24px; right: 24px; z-index: 99999; padding: 14px 22px; background: #0f172a; color: #ffffff; font-size: 14px; font-weight: 700; border-radius: 12px; box-shadow: 0 10px 25px rgba(0,0,0,0.3); border-left: 5px solid #10b981; transition: all 0.3s ease; opacity: 0; transform: translateY(20px); pointer-events: none;";
    document.body.appendChild(toast);
  }
  toast.style.borderColor = isError ? "#ef4444" : "#10b981";
  toast.textContent = message;
  toast.style.opacity = "1";
  toast.style.transform = "translateY(0)";
  toast.style.pointerEvents = "auto";

  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translateY(20px)";
    toast.style.pointerEvents = "none";
  }, 4000);
}

async function exportCalculationData() {
  try {
    const isEnglish = (typeof currentLang !== "undefined" && currentLang === "en");

    // Ensure TCO details (including application images) are fresh before export
    if (typeof saveBearingTcoDetails === "function") saveBearingTcoDetails();
    if (typeof saveChainTcoDetails === "function") saveChainTcoDetails();

    // 0. Ensure all metadata between DOM inputs and localStorage are perfectly synced both ways
    const syncFieldToLs = (inputId, lsKey) => {
      const el = document.getElementById(inputId);
      if (el && el.value !== "") {
        localStorage.setItem(lsKey, el.value);
      }
    };
    const syncLsToField = (inputId, lsKey) => {
      const el = document.getElementById(inputId);
      const val = localStorage.getItem(lsKey);
      if (el && (!el.value || el.value === "") && val) {
        el.value = val;
      }
    };

    // Sync Client details
    syncFieldToLs("clientCompanyInput", "client_company");
    syncFieldToLs("clientContactInput", "client_contact");
    syncFieldToLs("clientPhoneInput", "client_phone");
    syncFieldToLs("clientEmailInput", "client_email");
    syncLsToField("clientCompanyInput", "client_company");
    syncLsToField("clientContactInput", "client_contact");
    syncLsToField("clientPhoneInput", "client_phone");
    syncLsToField("clientEmailInput", "client_email");

    // Sync Operator details (Interflon contactpersoon)
    syncFieldToLs("opNameInput", "operator_name");
    syncFieldToLs("opPhoneInput", "operator_phone");
    syncFieldToLs("opEmailInput", "operator_email");
    syncLsToField("opNameInput", "operator_name");
    syncLsToField("opPhoneInput", "operator_phone");
    syncLsToField("opEmailInput", "operator_email");

    // Sync Technical data
    syncFieldToLs("techMachineInput", "tech_machine");
    syncFieldToLs("techAppInput", "tech_app");
    syncFieldToLs("techBrandInput", "tech_brand");
    syncFieldToLs("techProductInput", "tech_product");
    syncFieldToLs("techIntervalInput", "tech_interval");
    syncFieldToLs("techPriceInput", "tech_price");
    syncLsToField("techMachineInput", "tech_machine");
    syncLsToField("techAppInput", "tech_app");
    syncLsToField("techBrandInput", "tech_brand");
    syncLsToField("techProductInput", "tech_product");
    syncLsToField("techIntervalInput", "tech_interval");
    syncLsToField("techPriceInput", "tech_price");

    // Ensure photoFolders is synchronized from storage if currently empty in memory
    if (!photoFolders || !Array.isArray(photoFolders) || photoFolders.length === 0) {
      if (typeof loadPhotoLibrary === "function") loadPhotoLibrary();
    }

    // 1. Gather all inputs across all tabs
    const inputsData = {};
    document.querySelectorAll("input, select, textarea").forEach(el => {
      if (el.id && el.id !== "passwordInput" && el.id !== "importJsonFileInput") {
        if (el.type === "checkbox" || el.type === "radio") {
          inputsData[el.id] = el.checked;
        } else {
          inputsData[el.id] = el.value;
        }
      }
    });

    // 2. Gather localStorage
    const localStorageData = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && (
        key.startsWith("bearing_calc_") ||
        key.startsWith("app_field_") ||
        key.startsWith("bearing_tco_") ||
        key.startsWith("chain_tco_") ||
        key === "bearing_tco_data" ||
        key === "chain_tco_data" ||
        key.includes("operator") ||
        key.includes("client") ||
        key.includes("tech") ||
        key === "autoDevicesState" ||
        key === "photoLibrary" ||
        key === "photo_library" ||
        key === "photoFolders" ||
        key === "photo_folders" ||
        key.startsWith("interflon_")
      )) {
        localStorageData[key] = localStorage.getItem(key);
      }
    }

    const curBearingTco = localStorage.getItem("bearing_tco_data");
    if (curBearingTco) localStorageData["bearing_tco_data"] = curBearingTco;
    const curChainTco = localStorage.getItem("chain_tco_data");
    if (curChainTco) localStorageData["chain_tco_data"] = curChainTco;

    // Explicitly guarantee all metadata keys exist in localStorage snapshot
    const clientCompVal = localStorage.getItem("client_company") || (document.getElementById("clientCompanyInput") ? document.getElementById("clientCompanyInput").value : "");
    const clientContactVal = localStorage.getItem("client_contact") || (document.getElementById("clientContactInput") ? document.getElementById("clientContactInput").value : "");
    const clientPhoneVal = localStorage.getItem("client_phone") || (document.getElementById("clientPhoneInput") ? document.getElementById("clientPhoneInput").value : "");
    const clientEmailVal = localStorage.getItem("client_email") || (document.getElementById("clientEmailInput") ? document.getElementById("clientEmailInput").value : "");

    const opNameVal = localStorage.getItem("operator_name") || (document.getElementById("opNameInput") ? document.getElementById("opNameInput").value : "");
    const opPhoneVal = localStorage.getItem("operator_phone") || (document.getElementById("opPhoneInput") ? document.getElementById("opPhoneInput").value : "");
    const opEmailVal = localStorage.getItem("operator_email") || (document.getElementById("opEmailInput") ? document.getElementById("opEmailInput").value : "");

    const techMachineVal = (document.getElementById("techMachineInput") && document.getElementById("techMachineInput").value.trim()) ||
                           (document.getElementById("omTechMachine") && document.getElementById("omTechMachine").value.trim()) ||
                           (document.getElementById("chainOmTechMachine") && document.getElementById("chainOmTechMachine").value.trim()) ||
                           localStorage.getItem("tech_machine") ||
                           localStorage.getItem("app_field_techMachineInput") ||
                           localStorage.getItem("app_field_omTechMachine") ||
                           localStorage.getItem("app_field_chainOmTechMachine") ||
                           (function() {
                             try {
                               const qData = JSON.parse(localStorage.getItem('interflon_questionnaire_full_data') || localStorage.getItem('interflon_last_questionnaire_data') || '{}');
                               return (qData.general && (qData.general.machineName || qData.general.name)) || (qData.machine && (qData.machine.name || qData.machine.machineName)) || '';
                             } catch(e) { return ''; }
                           })() || "";
    const techAppVal = localStorage.getItem("tech_app") || (document.getElementById("techAppInput") ? document.getElementById("techAppInput").value : "");
    const techBrandVal = localStorage.getItem("tech_brand") || (document.getElementById("techBrandInput") ? document.getElementById("techBrandInput").value : "");
    const techProductVal = localStorage.getItem("tech_product") || (document.getElementById("techProductInput") ? document.getElementById("techProductInput").value : "");
    const techIntervalVal = localStorage.getItem("tech_interval") || (document.getElementById("techIntervalInput") ? document.getElementById("techIntervalInput").value : "");
    const techPriceVal = localStorage.getItem("tech_price") || (document.getElementById("techPriceInput") ? document.getElementById("techPriceInput").value : "");

    localStorageData["client_company"] = clientCompVal;
    localStorageData["client_contact"] = clientContactVal;
    localStorageData["client_phone"] = clientPhoneVal;
    localStorageData["client_email"] = clientEmailVal;

    localStorageData["operator_name"] = opNameVal;
    localStorageData["operator_phone"] = opPhoneVal;
    localStorageData["operator_email"] = opEmailVal;

    localStorageData["tech_machine"] = techMachineVal;
    localStorageData["tech_app"] = techAppVal;
    localStorageData["tech_brand"] = techBrandVal;
    localStorageData["tech_product"] = techProductVal;
    localStorageData["tech_interval"] = techIntervalVal;
    localStorageData["tech_price"] = techPriceVal;

    const currentFolders = (Array.isArray(photoFolders) && photoFolders.length > 0) ? photoFolders : ((typeof window !== "undefined" && Array.isArray(window.photoFolders)) ? window.photoFolders : [{ id: "folder_default", name: "Algemeen", photos: [] }]);
    const currentPhotos = (typeof getAllPhotosFlat === "function") ? getAllPhotosFlat() : ((Array.isArray(photoLibrary) && photoLibrary.length > 0) ? photoLibrary : []);
    if (currentFolders.length > 0) {
      const foldersJson = JSON.stringify(currentFolders);
      localStorageData["photo_folders"] = foldersJson;
      localStorageData["photoFolders"] = foldersJson;
    }
    if (currentPhotos.length > 0) {
      const photosJson = JSON.stringify(currentPhotos);
      localStorageData["photo_library"] = photosJson;
      localStorageData["photoLibrary"] = photosJson;
    }

    // 3. Gather client & machine details for filename (e.g. Klant_Machine_Datum.json)
    const cleanComp = sanitizeFilename(clientCompVal);
    const cleanMachine = sanitizeFilename(techMachineVal);
    const cleanContact = sanitizeFilename(clientContactVal);
    const dateStr = new Date().toISOString().split("T")[0];

    let filename = "";
    if (cleanComp && cleanMachine) {
      filename = `${cleanComp}_${cleanMachine}_${dateStr}.json`;
    } else if (cleanComp && cleanContact) {
      filename = `${cleanComp}_${cleanContact}_${dateStr}.json`;
    } else if (cleanComp) {
      filename = `${cleanComp}_${dateStr}.json`;
    } else if (cleanMachine) {
      filename = `${cleanMachine}_${dateStr}.json`;
    } else if (cleanContact) {
      filename = `${cleanContact}_${dateStr}.json`;
    } else {
      filename = isEnglish ? `Interflon_Calculation_${dateStr}.json` : `Opbrengstmodel_Interflon_${dateStr}.json`;
    }

    // 4. Construct complete export object
    const exportData = {
      appVersion: "2026.1",
      exportedAt: new Date().toISOString(),
      clientCompany: clientCompVal,
      clientContact: clientContactVal,
      client: {
        company: clientCompVal,
        contact: clientContactVal,
        phone: clientPhoneVal,
        email: clientEmailVal
      },
      operator: {
        name: opNameVal,
        phone: opPhoneVal,
        email: opEmailVal
      },
      tech: {
        machine: techMachineVal,
        app: techAppVal,
        brand: techBrandVal,
        product: techProductVal,
        interval: techIntervalVal,
        price: techPriceVal
      },
      inputs: inputsData,
      localStorage: localStorageData,
      questionnaire: (function() {
        let q = null;
        try {
          const raw = localStorage.getItem('interflon_questionnaire_full_data') || localStorage.getItem('interflon_last_questionnaire_data');
          if (raw) q = (typeof raw === 'string') ? JSON.parse(raw) : raw;
        } catch(e) {}
        if (!q && window.latestSurveyFullData) q = window.latestSurveyFullData;

        // If existing questionnaire belongs to another machine, do not attach stale mismatch
        const qMach = (q && q.general && (q.general.machineName || q.general.name)) || '';
        const isMismatch = techMachineVal && qMach && (qMach.trim().toLowerCase() !== techMachineVal.trim().toLowerCase());

        if (!q || isMismatch || !Array.isArray(q.bearings) || q.bearings.length === 0) {
          const bNr = (inputsData && (inputsData.bearingSearchInput || inputsData.omBearingNumber)) || 'Lager A';
          const bRpm = (inputsData && inputsData.inputSpeed) || '';
          const bQty = parseInt((inputsData && (inputsData.omBearingCount || inputsData.omCalcBearingQty)) || 1, 10) || 1;
          const bHours = parseFloat((inputsData && inputsData.inputHoursPerDay) || 16) || 16;
          const bDays = parseFloat((inputsData && inputsData.inputDaysPerWeek) || 5) || 5;

          q = {
            fileType: 'Interflon_Smeeranalyse_Vragenlijst',
            version: '1.0',
            exportDate: new Date().toISOString(),
            source: 'calculator_dossier_import',
            isDossierImport: true,
            general: {
              machineName: techMachineVal || 'Machine',
              machineBrand: techBrandVal || '',
              application: techAppVal || '',
              machineCount: String((inputsData && inputsData.omSharedNumMachines) || '1')
            },
            contact: {
              clientCompany: clientCompVal || '',
              clientContact: clientContactVal || '',
              clientPhone: clientPhoneVal || '',
              clientEmail: clientEmailVal || '',
              interflonContactEmail: opEmailVal || ''
            },
            bearings: [
              {
                letter: 'A',
                nr: bNr,
                desc: techAppVal || '',
                rpm: bRpm,
                pos: 'Horizontaal',
                qty: bQty,
                smeermiddel: techProductVal || '',
                prijsLiter: techPriceVal || '',
                interval: techIntervalVal ? (techIntervalVal + (String(techIntervalVal).toLowerCase().includes('dag') ? '' : ' dagen')) : '',
                hoursPerDay: bHours,
                daysPerWeek: bDays
              }
            ],
            bearingDataMapSec2: {
              'A': {
                q11: techProductVal || '',
                q12_price: techPriceVal || '',
                q4_freq_num: techIntervalVal ? (parseInt(techIntervalVal, 10) || '') : '',
                q4_freq_unit: 'Dagen',
                q13: bHours,
                q14: bDays
              }
            },
            bearingDataMapSec3: {},
            bearingDataMapSec4: {},
            activeBearings: { sec2: 'A', sec3: 'A', sec4: 'A' },
            raster: {
              machineRangeMeters: 10,
              layoutViewMode: '3d',
              showCentralPoint: true,
              showBearingDistances: false,
              bearingPositions: { 'A': { x: 0, y: 0 } },
              devices: []
            }
          };
        } else {
          if (!q.general) q.general = {};
          if (techMachineVal) q.general.machineName = techMachineVal;
          if (techBrandVal && !q.general.machineBrand) q.general.machineBrand = techBrandVal;
          if (techAppVal && !q.general.application) q.general.application = techAppVal;
          if (!q.contact) q.contact = {};
          if (clientCompVal) q.contact.clientCompany = clientCompVal;
          if (clientContactVal && !q.contact.clientContact) q.contact.clientContact = clientContactVal;
          if (clientPhoneVal && !q.contact.clientPhone) q.contact.clientPhone = clientPhoneVal;
          if (clientEmailVal && !q.contact.clientEmail) q.contact.clientEmail = clientEmailVal;
          if (opEmailVal && !q.contact.interflonContactEmail) q.contact.interflonContactEmail = opEmailVal;
          q.source = 'calculator_dossier_import';
          q.isDossierImport = true;
          q.exportDate = new Date().toISOString();
        }
        return q;
      })(),
      autoDevicesState: (typeof autoDevicesState !== "undefined") ? autoDevicesState : null,
      currentSelectedBearing: (typeof currentSelectedBearing !== "undefined") ? currentSelectedBearing : null,
      currentChainData: (typeof currentChainData !== "undefined") ? currentChainData : null,
      activeCalculationMode: (typeof activeCalculationMode !== "undefined") ? activeCalculationMode : "bearing",
      photoFolders: currentFolders,
      photoLibrary: currentPhotos,
      omAppImage: (function() {
        const img = tcoUploadedImageBase64 || (function() {
          try {
            const raw = localStorage.getItem("bearing_tco_data");
            const d = raw ? JSON.parse(raw) : null;
            return (d && d.omAppImage) || "";
          } catch(e) { return ""; }
        })();
        const imgMach = localStorage.getItem("omAppImageMachine") || (function() {
          try {
            const raw = localStorage.getItem("bearing_tco_data");
            const d = raw ? JSON.parse(raw) : null;
            return (d && d.omAppImageMachine) || "";
          } catch(e) { return ""; }
        })();
        if (imgMach && techMachineVal && imgMach.trim().toLowerCase() !== techMachineVal.trim().toLowerCase()) {
          return "";
        }
        return img;
      })(),
      omAppImageMachine: techMachineVal || "",
      chainOmAppImage: (function() {
        const img = chainTcoUploadedImageBase64 || (function() {
          try {
            const raw = localStorage.getItem("chain_tco_data");
            const d = raw ? JSON.parse(raw) : null;
            return (d && d.chainOmAppImage) || "";
          } catch(e) { return ""; }
        })();
        const imgMach = localStorage.getItem("chainOmAppImageMachine") || (function() {
          try {
            const raw = localStorage.getItem("chain_tco_data");
            const d = raw ? JSON.parse(raw) : null;
            return (d && d.chainOmAppImageMachine) || "";
          } catch(e) { return ""; }
        })();
        if (imgMach && techMachineVal && imgMach.trim().toLowerCase() !== techMachineVal.trim().toLowerCase()) {
          return "";
        }
        return img;
      })(),
      chainOmAppImageMachine: techMachineVal || "",
      bearing_tco_data: (function() {
        try {
          const raw = localStorage.getItem("bearing_tco_data");
          const d = raw ? JSON.parse(raw) : null;
          if (d) {
            const imgMach = d.omAppImageMachine || localStorage.getItem("omAppImageMachine") || "";
            if (imgMach && techMachineVal && imgMach.trim().toLowerCase() !== techMachineVal.trim().toLowerCase()) {
              d.omAppImage = "";
              d.omAppImageMachine = "";
            }
          }
          return d;
        } catch(e) { return null; }
      })(),
      chain_tco_data: (function() {
        try {
          const raw = localStorage.getItem("chain_tco_data");
          const d = raw ? JSON.parse(raw) : null;
          if (d) {
            const imgMach = d.chainOmAppImageMachine || localStorage.getItem("chainOmAppImageMachine") || "";
            if (imgMach && techMachineVal && imgMach.trim().toLowerCase() !== techMachineVal.trim().toLowerCase()) {
              d.chainOmAppImage = "";
              d.chainOmAppImageMachine = "";
            }
          }
          return d;
        } catch(e) { return null; }
      })()
    };

    const jsonString = JSON.stringify(exportData, null, 2);

    // 5. Save file (using showSaveFilePicker if available, else Blob download)
    if (typeof window.showSaveFilePicker === "function") {
      try {
        const handle = await window.showSaveFilePicker({
          suggestedName: filename,
          types: [{
            description: isEnglish ? 'Interflon Calculation File (*.json)' : 'Interflon Opbrengstmodel Bestand (*.json)',
            accept: { 'application/json': ['.json'] }
          }]
        });
        const writable = await handle.createWritable();
        await writable.write(jsonString);
        await writable.close();
        showToastNotification(isEnglish ? "Calculation successfully saved!" : "Opbrengstmodel succesvol opgeslagen!");
        return;
      } catch (err) {
        if (err.name === "AbortError") return; // User cancelled
      }
    }

    // Fallback Blob download
    const blob = new Blob([jsonString], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    showToastNotification(isEnglish ? `Calculation saved: ${filename}` : `Opbrengstmodel opgeslagen: ${filename}`);
  } catch (e) {
    console.error("Error exporting calculation data:", e);
    showToastNotification("Fout bij opslaan van opbrengstmodel.", true);
  }
}

function triggerImportCalculation() {
  const fileInput = document.getElementById("importJsonFileInput");
  if (fileInput) {
    fileInput.value = "";
    fileInput.click();
  }
}

function handleImportFileSelected(event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const data = JSON.parse(e.target.result);
      if (!data || typeof data !== 'object') {
        showToastNotification("Ongeldig bestand.", true);
        return;
      }

      const isEnglish = (typeof currentLang !== "undefined" && currentLang === "en");

      // CASE 1: User imported a pure questionnaire JSON file directly into the calculator
      const isQuestionnaireOnly = (data.fileType === 'Interflon_Smeeranalyse_Vragenlijst' || (data.bearings && data.general)) && !data.inputs && !data.localStorage;
      if (isQuestionnaireOnly) {
        try {
          const qJson = JSON.stringify(data);
          localStorage.setItem('interflon_questionnaire_full_data', qJson);
          localStorage.setItem('interflon_last_questionnaire_data', qJson);
          if (data.surveyRasterConfig) {
            localStorage.setItem('interflon_survey_raster_config', JSON.stringify(data.surveyRasterConfig));
          }
          const qMach = (data.general && (data.general.machineName || data.general.name)) ||
                        (data.machine && (data.machine.name || data.machine.machineName)) ||
                        data.machineName || "";
          if (qMach) {
            localStorage.setItem('app_field_techMachineInput', qMach);
            localStorage.setItem('app_field_omTechMachine', qMach);
            localStorage.setItem('app_field_chainOmTechMachine', qMach);
            localStorage.setItem('tech_machine', qMach);
            const mIn = document.getElementById('techMachineInput');
            if (mIn) mIn.value = qMach;
            const omM = document.getElementById('omTechMachine');
            if (omM) omM.value = qMach;
            const chainM = document.getElementById('chainOmTechMachine');
            if (chainM) chainM.value = qMach;
          }
          const qBrand = (data.general && (data.general.machineBrand || data.general.brand)) || (data.machine && data.machine.brand) || "";
          if (qBrand) {
            localStorage.setItem('app_field_techBrandInput', qBrand);
            localStorage.setItem('app_field_omTechBrand', qBrand);
            localStorage.setItem('app_field_chainOmTechBrand', qBrand);
            localStorage.setItem('tech_brand', qBrand);
            const bIn = document.getElementById('techBrandInput');
            if (bIn) bIn.value = qBrand;
            const omB = document.getElementById('omTechBrand');
            if (omB) omB.value = qBrand;
          }
          const qApp = (data.general && (data.general.application || data.general.app)) || (data.machine && data.machine.application) || "";
          if (qApp) {
            localStorage.setItem('app_field_techAppInput', qApp);
            localStorage.setItem('app_field_omTechApp', qApp);
            localStorage.setItem('app_field_chainOmTechApp', qApp);
            localStorage.setItem('tech_app', qApp);
            const aIn = document.getElementById('techAppInput');
            if (aIn) aIn.value = qApp;
            const omA = document.getElementById('omTechApp');
            if (omA) omA.value = qApp;
          }
          if (data.contact) {
            if (data.contact.clientCompany) {
              localStorage.setItem('app_field_clientCompanyInput', data.contact.clientCompany);
              localStorage.setItem('app_field_omClientCompany', data.contact.clientCompany);
              localStorage.setItem('app_field_chainOmClientCompany', data.contact.clientCompany);
              localStorage.setItem('client_company', data.contact.clientCompany);
              const cIn = document.getElementById('clientCompanyInput');
              if (cIn) cIn.value = data.contact.clientCompany;
              const omC = document.getElementById('omClientCompany');
              if (omC) omC.value = data.contact.clientCompany;
            }
            if (data.contact.clientContact) {
              localStorage.setItem('app_field_clientContactInput', data.contact.clientContact);
              localStorage.setItem('app_field_omClientContact', data.contact.clientContact);
              localStorage.setItem('app_field_chainOmClientContact', data.contact.clientContact);
              localStorage.setItem('client_contact', data.contact.clientContact);
              const ctIn = document.getElementById('clientContactInput');
              if (ctIn) ctIn.value = data.contact.clientContact;
              const omCt = document.getElementById('omClientContact');
              if (omCt) omCt.value = data.contact.clientContact;
            }
            if (data.contact.clientPhone) {
              localStorage.setItem('app_field_clientPhoneInput', data.contact.clientPhone);
              localStorage.setItem('app_field_omClientPhone', data.contact.clientPhone);
              localStorage.setItem('app_field_chainOmClientPhone', data.contact.clientPhone);
              localStorage.setItem('client_phone', data.contact.clientPhone);
              const pIn = document.getElementById('clientPhoneInput');
              if (pIn) pIn.value = data.contact.clientPhone;
            }
            if (data.contact.clientEmail) {
              localStorage.setItem('app_field_clientEmailInput', data.contact.clientEmail);
              localStorage.setItem('app_field_omClientEmail', data.contact.clientEmail);
              localStorage.setItem('app_field_chainOmClientEmail', data.contact.clientEmail);
              localStorage.setItem('client_email', data.contact.clientEmail);
              const eIn = document.getElementById('clientEmailInput');
              if (eIn) eIn.value = data.contact.clientEmail;
              const omE = document.getElementById('omClientEmail');
              if (omE) omE.value = data.contact.clientEmail;
            }
          }

          window.latestSurveyFullData = data;
          const bList = Array.isArray(data.bearings) ? data.bearings : [];
          window.latestSurveyBearings = bList;
          const firstL = (bList.length > 0 && bList[0].letter) ? bList[0].letter : 'A';
          window.currentActiveSurveyBearingLetter = firstL;
          window.currentSurveyBearingLetter = firstL;
          window.activeTcoBearingSource = "survey_" + firstL;
          try {
            localStorage.setItem("interflon_active_survey_letter", firstL);
            localStorage.setItem("active_tco_bearing_source", "survey_" + firstL);
          } catch(err) {}

          if (typeof populateSurveyBearingsDropdown === 'function') populateSurveyBearingsDropdown(bList);
          if (typeof populateOmSurveyBearingsDropdown === 'function') populateOmSurveyBearingsDropdown(bList);
          if (typeof refreshSurveyBearingsList === 'function') refreshSurveyBearingsList(false);
          if (typeof syncAllQuestionnaireDataToCalculator === 'function') syncAllQuestionnaireDataToCalculator(data, firstL);
          if (typeof populateOmSurveyBearingsDropdown === 'function') {
            populateOmSurveyBearingsDropdown(bList);
            populateOmSurveyBearingsDropdown(bList, 'chain');
          }
          const surveyWrapper = document.getElementById("surveyBearingSelectWrapper");
          if (surveyWrapper) surveyWrapper.style.display = bList.length > 0 ? "flex" : "none";

          window.__lastDossierImportTime = Date.now();
          if (typeof BroadcastChannel !== 'undefined') {
            try {
              if (!window.__surveySyncBroadcastChannel) {
                window.__surveySyncBroadcastChannel = new BroadcastChannel('interflon_questionnaire_sync');
              }
              window.__surveySyncBroadcastChannel.postMessage({
                type: 'QUESTIONNAIRE_IMPORTED',
                data: data,
                fullData: data,
                bearings: bList,
                source: 'calculator_dossier_import'
              });
            } catch(e) {}
          }

          if (typeof loadClientDetails === 'function') loadClientDetails();
          if (typeof loadOperatorDetails === 'function') loadOperatorDetails();
          if (typeof loadTechDetails === 'function') loadTechDetails();

          // TCO Photo: restore if present in questionnaire, otherwise reset cleanly
          let qOmImage = "";
          if (data.omAppImage && typeof data.omAppImage === "string" && data.omAppImage.startsWith("data:image")) {
            qOmImage = data.omAppImage;
          } else if (data.bearing_tco_data && data.bearing_tco_data.omAppImage && typeof data.bearing_tco_data.omAppImage === "string" && data.bearing_tco_data.omAppImage.startsWith("data:image")) {
            qOmImage = data.bearing_tco_data.omAppImage;
          }
          if (typeof setBearingTcoImage === "function") {
            setBearingTcoImage(qOmImage, qMach);
          } else {
            tcoUploadedImageBase64 = qOmImage;
          }

          let qChainOmImage = "";
          if (data.chainOmAppImage && typeof data.chainOmAppImage === "string" && data.chainOmAppImage.startsWith("data:image")) {
            qChainOmImage = data.chainOmAppImage;
          } else if (data.chain_tco_data && data.chain_tco_data.chainOmAppImage && typeof data.chain_tco_data.chainOmAppImage === "string" && data.chain_tco_data.chainOmAppImage.startsWith("data:image")) {
            qChainOmImage = data.chain_tco_data.chainOmAppImage;
          }
          if (typeof setChainTcoImage === "function") {
            setChainTcoImage(qChainOmImage, qMach);
          } else {
            chainTcoUploadedImageBase64 = qChainOmImage;
          }

          photoFolders = [
            { id: "folder_default", name: "Algemeen", photos: [] }
          ];
          activePhotoFolderId = "folder_default";
          photoLibrary = [];
          if (typeof window !== "undefined") {
            window.photoFolders = photoFolders;
            window.activePhotoFolderId = activePhotoFolderId;
            window.photoLibrary = photoLibrary;
          }
          try {
            localStorage.removeItem("photo_folders");
            localStorage.removeItem("photoFolders");
            localStorage.removeItem("photo_library");
            localStorage.removeItem("photoLibrary");
          } catch(e) {}

          if (typeof loadBearingTcoDetails === "function") loadBearingTcoDetails();
          if (typeof loadChainTcoDetails === "function") loadChainTcoDetails();
          if (typeof updateClientBadge === 'function') updateClientBadge(data.contact ? data.contact.clientCompany : '', data.contact ? data.contact.clientContact : '');
          if (typeof updateTechBadge === 'function') updateTechBadge(qMach, qApp);
          if (typeof updateOmMetadata === 'function') updateOmMetadata();
          if (typeof calculateGrease === "function") calculateGrease();
          if (typeof calculateBearing === "function") calculateBearing();
          if (typeof calculateTco === "function") calculateTco();
          if (typeof updateOmKpiSummaryCards === "function") updateOmKpiSummaryCards();
          if (typeof renderAutoDevicesUI === "function") renderAutoDevicesUI();
          if (typeof calculateAutomationLubrication === "function") calculateAutomationLubrication();
          if (typeof updateRoiAutomationPage === "function") updateRoiAutomationPage();
          if (typeof calculateChain === "function") calculateChain();
          if (typeof calculateChainTco === "function") calculateChainTco();

          showToastNotification(qMach ? `Vragenlijst voor machine '${qMach}' succesvol geladen!` : "Vragenlijst succesvol geladen in de calculator!");
          return;
        } catch(e) {
          console.error("Fout bij laden van vragenlijst:", e);
        }
      }

      // CASE 2: Opbrengstmodel / Dossier import
      // 1. Extract questionnaire object
      let importedQuestionnaire = null;
      if (data.questionnaire && typeof data.questionnaire === 'object' && (data.questionnaire.bearings || data.questionnaire.general || data.questionnaire.fileType)) {
        importedQuestionnaire = data.questionnaire;
      } else if (data.questionnaireData && typeof data.questionnaireData === 'object') {
        importedQuestionnaire = data.questionnaireData;
      } else if (data.fullData && typeof data.fullData === 'object' && (data.fullData.bearings || data.fullData.general)) {
        importedQuestionnaire = data.fullData;
      } else if (data.localStorage) {
        const rawQ = data.localStorage.interflon_questionnaire_full_data || data.localStorage.interflon_last_questionnaire_data;
        if (rawQ) {
          try {
            importedQuestionnaire = (typeof rawQ === 'string') ? JSON.parse(rawQ) : rawQ;
          } catch(e) {}
        }
      }

      // 2. Determine target metadata (prioritizing explicit fields in imported file)
      const targetMachine = (data.tech && data.tech.machine) ||
                            data.techMachine ||
                            (importedQuestionnaire && importedQuestionnaire.general && (importedQuestionnaire.general.machineName || importedQuestionnaire.general.name)) ||
                            (data.general && (data.general.machineName || data.general.name)) ||
                            (data.machine && (data.machine.name || data.machine.machineName)) ||
                            data.machineName ||
                            (data.inputs && (data.inputs["techMachineInput"] || data.inputs["omTechMachine"] || data.inputs["chainOmTechMachine"])) ||
                            (data.localStorage && data.localStorage["tech_machine"]) || "";

      const targetBrand = (data.tech && data.tech.brand) ||
                          (importedQuestionnaire && importedQuestionnaire.general && (importedQuestionnaire.general.machineBrand || importedQuestionnaire.general.brand)) ||
                          (data.general && (data.general.machineBrand || data.general.brand)) ||
                          (data.machine && (data.machine.brand || data.machine.machineBrand)) ||
                          (data.inputs && (data.inputs["techBrandInput"] || data.inputs["omTechBrand"] || data.inputs["chainOmTechBrand"])) ||
                          (data.localStorage && data.localStorage["tech_brand"]) || "";

      const targetApp = (data.tech && data.tech.app) ||
                        (importedQuestionnaire && importedQuestionnaire.general && (importedQuestionnaire.general.application || importedQuestionnaire.general.app)) ||
                        (data.general && (data.general.application || data.general.app)) ||
                        (data.machine && (data.machine.application || data.machine.app)) ||
                        (data.inputs && (data.inputs["techAppInput"] || data.inputs["omTechApp"] || data.inputs["chainOmTechApp"])) ||
                        (data.localStorage && data.localStorage["tech_app"]) || "";

      const targetProduct = (data.tech && data.tech.product) ||
                            (data.inputs && (data.inputs["techProductInput"] || data.inputs["omTechProduct"] || data.inputs["chainOmTechProduct"])) ||
                            (data.localStorage && data.localStorage["tech_product"]) || "";

      const targetInterval = (data.tech && data.tech.interval) ||
                             (data.inputs && (data.inputs["techIntervalInput"] || data.inputs["omTechInterval"] || data.inputs["chainOmTechInterval"])) ||
                             (data.localStorage && data.localStorage["tech_interval"]) || "";

      const targetPrice = (data.tech && data.tech.price) ||
                          (data.inputs && (data.inputs["techPriceInput"] || data.inputs["omTechPrice"] || data.inputs["chainOmTechPrice"] || data.inputs["omProdPrice1"] || data.inputs["chainOmProdPrice1"])) ||
                          (data.localStorage && data.localStorage["tech_price"]) || "";

      const targetCompany = (data.client && data.client.company) ||
                            data.clientCompany ||
                            (importedQuestionnaire && importedQuestionnaire.contact && importedQuestionnaire.contact.clientCompany) ||
                            (data.contact && data.contact.clientCompany) ||
                            (data.inputs && (data.inputs["clientCompanyInput"] || data.inputs["omClientCompany"] || data.inputs["chainOmClientCompany"])) ||
                            (data.localStorage && data.localStorage["client_company"]) || "";

      const targetContact = (data.client && data.client.contact) ||
                            data.clientContact ||
                            (importedQuestionnaire && importedQuestionnaire.contact && importedQuestionnaire.contact.clientContact) ||
                            (data.contact && data.contact.clientContact) ||
                            (data.inputs && (data.inputs["clientContactInput"] || data.inputs["omClientContact"] || data.inputs["chainOmClientContact"])) ||
                            (data.localStorage && data.localStorage["client_contact"]) || "";

      const targetPhone = (data.client && data.client.phone) ||
                          (importedQuestionnaire && importedQuestionnaire.contact && importedQuestionnaire.contact.clientPhone) ||
                          (data.contact && data.contact.clientPhone) ||
                          (data.inputs && (data.inputs["clientPhoneInput"] || data.inputs["omClientPhone"] || data.inputs["chainOmClientPhone"])) ||
                          (data.localStorage && data.localStorage["client_phone"]) || "";

      const targetEmail = (data.client && data.client.email) ||
                          (importedQuestionnaire && importedQuestionnaire.contact && importedQuestionnaire.contact.clientEmail) ||
                          (data.contact && data.contact.clientEmail) ||
                          (data.inputs && (data.inputs["clientEmailInput"] || data.inputs["omClientEmail"] || data.inputs["chainOmClientEmail"])) ||
                          (data.localStorage && data.localStorage["client_email"]) || "";

      const targetOpName = (data.operator && data.operator.name) ||
                           (data.inputs && (data.inputs["opNameInput"] || data.inputs["omOpName"] || data.inputs["chainOmOpName"])) ||
                           (data.localStorage && data.localStorage["operator_name"]) || "";

      const targetOpPhone = (data.operator && data.operator.phone) ||
                            (data.inputs && (data.inputs["opPhoneInput"] || data.inputs["omOpPhone"] || data.inputs["chainOmOpPhone"])) ||
                            (data.localStorage && data.localStorage["operator_phone"]) || "";

      const targetOpEmail = (data.operator && data.operator.email) ||
                            (data.inputs && (data.inputs["opEmailInput"] || data.inputs["omOpEmail"] || data.inputs["chainOmOpEmail"])) ||
                            (data.localStorage && data.localStorage["operator_email"]) || "";

      // 2b. Reconstruct questionnaire from survey raster config or bearings if missing from top-level keys
      if (!importedQuestionnaire && (data.surveyRasterConfig || (data.localStorage && (data.localStorage.interflon_survey_raster_config || data.localStorage.interflon_raster_config)) || data.raster)) {
        const rawCfg = data.surveyRasterConfig || (data.localStorage && (data.localStorage.interflon_survey_raster_config || data.localStorage.interflon_raster_config));
        let cfg = null;
        if (rawCfg) {
          try {
            cfg = (typeof rawCfg === 'string') ? JSON.parse(rawCfg) : rawCfg;
          } catch(e) {}
        }
        if (cfg && (cfg.bearings || cfg.devices || cfg.machineName)) {
          importedQuestionnaire = {
            fileType: 'Interflon_Smeeranalyse_Vragenlijst',
            version: '1.0',
            exportDate: new Date().toISOString(),
            general: cfg.general || {
              machineName: cfg.machineName || targetMachine,
              machineBrand: targetBrand,
              application: targetApp,
              machineCount: (data.inputs && data.inputs.omSharedNumMachines) || '1'
            },
            contact: cfg.contact || {
              clientCompany: targetCompany,
              clientContact: targetContact,
              clientPhone: targetPhone,
              clientEmail: targetEmail
            },
            bearings: cfg.bearings || [],
            bearingDataMapSec2: cfg.bearingDataMapSec2 || {},
            bearingDataMapSec3: cfg.bearingDataMapSec3 || {},
            bearingDataMapSec4: cfg.bearingDataMapSec4 || {},
            activeBearings: cfg.activeBearings || {},
            raster: data.raster || cfg.raster || undefined,
            surveyRasterConfig: cfg
          };
        }
      }

      if (!importedQuestionnaire && data.bearings && Array.isArray(data.bearings) && data.bearings.length > 0) {
        importedQuestionnaire = {
          fileType: 'Interflon_Smeeranalyse_Vragenlijst',
          version: '1.0',
          exportDate: new Date().toISOString(),
          source: 'calculator_dossier_import',
          isDossierImport: true,
          general: {
            machineName: targetMachine,
            machineBrand: targetBrand,
            application: targetApp,
            machineCount: (data.inputs && data.inputs.omSharedNumMachines) || '1'
          },
          contact: {
            clientCompany: targetCompany,
            clientContact: targetContact,
            clientPhone: targetPhone,
            clientEmail: targetEmail,
            interflonContactEmail: targetOpEmail
          },
          bearings: data.bearings,
          bearingDataMapSec2: data.bearingDataMapSec2 || {},
          bearingDataMapSec3: data.bearingDataMapSec3 || {},
          bearingDataMapSec4: data.bearingDataMapSec4 || {},
          activeBearings: data.activeBearings || {}
        };
      }

      // 2c. Fallback synthesis: If imported file had no explicit questionnaire object, build one from dossier metadata and inputs
      if (!importedQuestionnaire && (targetMachine || targetCompany || (data.inputs && Object.keys(data.inputs).length > 0))) {
        const inp = data.inputs || {};
        const bNr = inp.bearingSearchInput || inp.omBearingNumber || inp.bearingNrInput || (data.currentSelectedBearing && data.currentSelectedBearing.designation) || 'Lager A';
        const bRpm = inp.inputSpeed || inp.omSpeed || '';
        const bQty = parseInt(inp.omBearingCount || inp.omCalcBearingQty || 1, 10) || 1;
        const bHours = parseFloat(inp.inputHoursPerDay || inp.omHoursPerDay) || 16;
        const bDays = parseFloat(inp.inputDaysPerWeek || inp.omDaysPerWeek) || 5;

        importedQuestionnaire = {
          fileType: 'Interflon_Smeeranalyse_Vragenlijst',
          version: '1.0',
          exportDate: new Date().toISOString(),
          source: 'calculator_dossier_import',
          isDossierImport: true,
          general: {
            machineName: targetMachine || 'Machine',
            machineBrand: targetBrand || '',
            application: targetApp || '',
            machineCount: String(inp.omSharedNumMachines || inp.chainOmSharedNumMachines || '1')
          },
          contact: {
            clientCompany: targetCompany || '',
            clientContact: targetContact || '',
            clientPhone: targetPhone || '',
            clientEmail: targetEmail || '',
            interflonContactEmail: targetOpEmail || ''
          },
          bearings: [
            {
              letter: 'A',
              nr: bNr,
              desc: targetApp || '',
              rpm: bRpm,
              pos: 'Horizontaal',
              qty: bQty,
              smeermiddel: targetProduct || '',
              prijsLiter: targetPrice || '',
              interval: targetInterval ? (targetInterval + (String(targetInterval).toLowerCase().includes('dag') ? '' : ' dagen')) : '',
              hoursPerDay: bHours,
              daysPerWeek: bDays
            }
          ],
          bearingDataMapSec2: {
            'A': {
              q11: targetProduct || '',
              q12_price: targetPrice || '',
              q4_freq_num: targetInterval ? (parseInt(targetInterval, 10) || '') : '',
              q4_freq_unit: 'Dagen',
              q13: bHours,
              q14: bDays
            }
          },
          bearingDataMapSec3: {},
          bearingDataMapSec4: {},
          activeBearings: { sec2: 'A', sec3: 'A', sec4: 'A' },
          raster: {
            machineRangeMeters: 10,
            layoutViewMode: '3d',
            showCentralPoint: true,
            showBearingDistances: false,
            bearingPositions: { 'A': { x: 0, y: 0 } },
            devices: []
          }
        };
      }

      // Align questionnaire metadata if questionnaire exists
      if (importedQuestionnaire && typeof importedQuestionnaire === 'object') {
        importedQuestionnaire.source = 'calculator_dossier_import';
        importedQuestionnaire.isDossierImport = true;
        importedQuestionnaire.exportDate = new Date().toISOString();
        if (!importedQuestionnaire.general) importedQuestionnaire.general = {};
        if (targetMachine) {
          importedQuestionnaire.general.machineName = targetMachine;
        }
        if (targetBrand) {
          importedQuestionnaire.general.machineBrand = targetBrand;
        }
        if (targetApp) {
          importedQuestionnaire.general.application = targetApp;
        }
        if (!importedQuestionnaire.contact) importedQuestionnaire.contact = {};
        if (targetCompany) importedQuestionnaire.contact.clientCompany = targetCompany;
        if (targetContact) importedQuestionnaire.contact.clientContact = targetContact;
        if (targetPhone) importedQuestionnaire.contact.clientPhone = targetPhone;
        if (targetEmail) importedQuestionnaire.contact.clientEmail = targetEmail;
        if (targetOpEmail) importedQuestionnaire.contact.interflonContactEmail = targetOpEmail;
      }

      // STEP 3: Purge existing field storage keys and photo states so no stale values linger
      tcoUploadedImageBase64 = "";
      chainTcoUploadedImageBase64 = "";
      if (typeof setBearingTcoImage === "function") setBearingTcoImage("");
      if (typeof setChainTcoImage === "function") setChainTcoImage("");

      const previewImg = document.getElementById("omAppImagePreview");
      if (previewImg) previewImg.src = "";
      const previewContainer = document.getElementById("omAppImagePreviewContainer");
      if (previewContainer) previewContainer.style.display = "none";
      const placeholder = document.getElementById("omAppImagePlaceholder");
      if (placeholder) placeholder.style.display = "flex";

      const chainPreviewImg = document.getElementById("chainOmAppImagePreview");
      if (chainPreviewImg) chainPreviewImg.src = "";
      const chainPreviewContainer = document.getElementById("chainOmAppImagePreviewContainer");
      if (chainPreviewContainer) chainPreviewContainer.style.display = "none";
      const chainPlaceholder = document.getElementById("chainOmAppImagePlaceholder");
      if (chainPlaceholder) chainPlaceholder.style.display = "flex";

      photoFolders = [
        { id: "folder_default", name: "Algemeen", photos: [] }
      ];
      activePhotoFolderId = "folder_default";
      photoLibrary = [];
      if (typeof window !== "undefined") {
        window.photoFolders = photoFolders;
        window.activePhotoFolderId = activePhotoFolderId;
        window.photoLibrary = photoLibrary;
      }

      Object.keys(localStorage).forEach(k => {
        if (k.startsWith("app_field_") || k.startsWith("bearing_calc_")) {
          try { localStorage.removeItem(k); } catch(e) {}
        }
      });
      const keysToPurge = [
        "tech_machine", "tech_app", "tech_brand", "tech_product", "tech_interval", "tech_price",
        "client_company", "client_contact", "client_phone", "client_email",
        "operator_name", "operator_phone", "operator_email",
        "interflon_active_survey_letter", "active_tco_bearing_source",
        "selected_bearing", "currentBearingId", "currentBearingName",
        "bearing_tco_data", "chain_tco_data", "bearing_calc_tco_data",
        "photo_folders", "photoFolders", "photo_library", "photoLibrary",
        "omAppImage", "chainOmAppImage", "omAppImageMachine", "chainOmAppImageMachine",
        "active_interflon_grease"
      ];
      keysToPurge.forEach(k => {
        try { localStorage.removeItem(k); } catch(e) {}
      });

      // STEP 4: Restore localStorage from imported file (with individual try/catch)
      if (data.localStorage && typeof data.localStorage === 'object') {
        Object.keys(data.localStorage).forEach(k => {
          if (data.localStorage[k] !== null && data.localStorage[k] !== undefined) {
            try {
              const valToStore = (typeof data.localStorage[k] === "object")
                ? JSON.stringify(data.localStorage[k])
                : String(data.localStorage[k]);
              localStorage.setItem(k, valToStore);
            } catch(err) {}
          }
        });
      }

      if (data.bearing_tco_data && typeof data.bearing_tco_data === 'object') {
        try {
          localStorage.setItem("bearing_tco_data", JSON.stringify(data.bearing_tco_data));
        } catch(e) {}
      }
      if (data.chain_tco_data && typeof data.chain_tco_data === 'object') {
        try {
          localStorage.setItem("chain_tco_data", JSON.stringify(data.chain_tco_data));
        } catch(e) {}
      }

      // STEP 5: Explicitly store verified metadata in localStorage
      try {
        localStorage.setItem("tech_machine", targetMachine);
        localStorage.setItem("tech_app", targetApp);
        localStorage.setItem("tech_brand", targetBrand);
        localStorage.setItem("tech_product", targetProduct);
        localStorage.setItem("tech_interval", targetInterval);
        localStorage.setItem("tech_price", targetPrice);

        localStorage.setItem("client_company", targetCompany);
        localStorage.setItem("client_contact", targetContact);
        localStorage.setItem("client_phone", targetPhone);
        localStorage.setItem("client_email", targetEmail);

        localStorage.setItem("operator_name", targetOpName);
        localStorage.setItem("operator_phone", targetOpPhone);
        localStorage.setItem("operator_email", targetOpEmail);

        localStorage.setItem("app_field_techMachineInput", targetMachine);
        localStorage.setItem("app_field_omTechMachine", targetMachine);
        localStorage.setItem("app_field_chainOmTechMachine", targetMachine);
        localStorage.setItem("app_field_techBrandInput", targetBrand);
        localStorage.setItem("app_field_omTechBrand", targetBrand);
        localStorage.setItem("app_field_chainOmTechBrand", targetBrand);
        localStorage.setItem("app_field_techAppInput", targetApp);
        localStorage.setItem("app_field_omTechApp", targetApp);
        localStorage.setItem("app_field_chainOmTechApp", targetApp);
        localStorage.setItem("app_field_techProductInput", targetProduct);
        localStorage.setItem("app_field_omTechProduct", targetProduct);
        localStorage.setItem("app_field_chainOmTechProduct", targetProduct);
        localStorage.setItem("app_field_techIntervalInput", targetInterval);
        localStorage.setItem("app_field_omTechInterval", targetInterval);
        localStorage.setItem("app_field_chainOmTechInterval", targetInterval);
        localStorage.setItem("app_field_techPriceInput", targetPrice);
        localStorage.setItem("app_field_omTechPrice", targetPrice);
        localStorage.setItem("app_field_chainOmTechPrice", targetPrice);

        localStorage.setItem("app_field_clientCompanyInput", targetCompany);
        localStorage.setItem("app_field_omClientCompany", targetCompany);
        localStorage.setItem("app_field_chainOmClientCompany", targetCompany);
        localStorage.setItem("app_field_clientContactInput", targetContact);
        localStorage.setItem("app_field_omClientContact", targetContact);
        localStorage.setItem("app_field_chainOmClientContact", targetContact);
        localStorage.setItem("app_field_clientPhoneInput", targetPhone);
        localStorage.setItem("app_field_omClientPhone", targetPhone);
        localStorage.setItem("app_field_chainOmClientPhone", targetPhone);
        localStorage.setItem("app_field_clientEmailInput", targetEmail);
        localStorage.setItem("app_field_omClientEmail", targetEmail);
        localStorage.setItem("app_field_chainOmClientEmail", targetEmail);

        localStorage.setItem("app_field_opNameInput", targetOpName);
        localStorage.setItem("app_field_omOpName", targetOpName);
        localStorage.setItem("app_field_chainOmOpName", targetOpName);
        localStorage.setItem("app_field_opPhoneInput", targetOpPhone);
        localStorage.setItem("app_field_omOpPhone", targetOpPhone);
        localStorage.setItem("app_field_chainOmOpPhone", targetOpPhone);
        localStorage.setItem("app_field_opEmailInput", targetOpEmail);
        localStorage.setItem("app_field_omOpEmail", targetOpEmail);
        localStorage.setItem("app_field_chainOmOpEmail", targetOpEmail);
      } catch(e) {}

      // STEP 6: Restore global states
      if (data.activeCalculationMode) {
        window.activeCalculationMode = data.activeCalculationMode;
        currentAppMode = data.activeCalculationMode;
        if (typeof updateModeUI === "function") updateModeUI();
      }
      if (data.autoDevicesState && Array.isArray(data.autoDevicesState)) {
        window.autoDevicesState = data.autoDevicesState;
        autoDevicesState = data.autoDevicesState;
        try {
          localStorage.setItem("autoDevicesState", JSON.stringify(data.autoDevicesState));
          localStorage.setItem("auto_devices_state", JSON.stringify(data.autoDevicesState));
        } catch(err){}
        if (typeof loadAutomationStateFromLocalStorage === "function") {
          loadAutomationStateFromLocalStorage(true);
        }
      }
      if (data.currentSelectedBearing) {
        window.currentSelectedBearing = data.currentSelectedBearing;
      }
      if (data.currentChainData) {
        window.currentChainData = data.currentChainData;
      }

      // STEP 7: Restore photo folders safely
      let importedFolders = [];
      if (data.photoFolders && Array.isArray(data.photoFolders) && data.photoFolders.length > 0) {
        importedFolders = data.photoFolders;
      } else if (data.photo_folders && Array.isArray(data.photo_folders) && data.photo_folders.length > 0) {
        importedFolders = data.photo_folders;
      } else if (data.localStorage && (data.localStorage["photo_folders"] || data.localStorage["photoFolders"])) {
        try {
          const rawF = data.localStorage["photo_folders"] || data.localStorage["photoFolders"];
          const parsed = JSON.parse(rawF);
          if (Array.isArray(parsed) && parsed.length > 0) importedFolders = parsed;
        } catch(e) {}
      }

      if (importedFolders.length === 0) {
        let legacyPhotos = [];
        if (data.photoLibrary && Array.isArray(data.photoLibrary) && data.photoLibrary.length > 0) {
          legacyPhotos = data.photoLibrary;
        } else if (data.photo_library && Array.isArray(data.photo_library) && data.photo_library.length > 0) {
          legacyPhotos = data.photo_library;
        } else if (data.localStorage && (data.localStorage["photo_library"] || data.localStorage["photoLibrary"])) {
          try {
            const rawP = data.localStorage["photo_library"] || data.localStorage["photoLibrary"];
            const parsed = JSON.parse(rawP);
            if (Array.isArray(parsed) && parsed.length > 0) legacyPhotos = parsed;
          } catch(e) {}
        }
        if (legacyPhotos.length > 0) {
          if (legacyPhotos[0].photos && Array.isArray(legacyPhotos[0].photos)) {
            importedFolders = legacyPhotos;
          } else {
            importedFolders = [
              { id: "folder_default", name: "Algemeen", photos: legacyPhotos }
            ];
          }
        }
      }

      if (importedFolders.length === 0) {
        importedFolders = [
          { id: "folder_default", name: "Algemeen", photos: [] }
        ];
      }

      photoFolders = importedFolders;
      photoFolders.forEach(f => {
        if (!f.photos || !Array.isArray(f.photos)) f.photos = [];
      });
      activePhotoFolderId = photoFolders[0].id;
      photoLibrary = getCurrentPhotoFolder().photos;

      if (typeof window !== "undefined") {
        window.photoFolders = photoFolders;
        window.activePhotoFolderId = activePhotoFolderId;
        window.photoLibrary = photoLibrary;
      }

      try {
        const fJson = JSON.stringify(photoFolders);
        localStorage.setItem("photo_folders", fJson);
        localStorage.setItem("photoFolders", fJson);

        const flatPhotos = getAllPhotosFlat();
        const pJson = JSON.stringify(flatPhotos);
        localStorage.setItem("photo_library", pJson);
        localStorage.setItem("photoLibrary", pJson);
      } catch(err) {
        console.warn("Could not write imported photo folders to localStorage:", err);
      }

      // STEP 7b: Restore TCO Machine Photos (Lager & Ketting)
      let importedOmImage = "";
      if (data.omAppImage && typeof data.omAppImage === "string" && data.omAppImage.startsWith("data:image")) {
        importedOmImage = data.omAppImage;
      } else if (data.bearing_tco_data && data.bearing_tco_data.omAppImage && typeof data.bearing_tco_data.omAppImage === "string" && data.bearing_tco_data.omAppImage.startsWith("data:image")) {
        importedOmImage = data.bearing_tco_data.omAppImage;
      } else if (data.localStorage && data.localStorage["bearing_tco_data"]) {
        try {
          const parsed = typeof data.localStorage["bearing_tco_data"] === "string"
            ? JSON.parse(data.localStorage["bearing_tco_data"])
            : data.localStorage["bearing_tco_data"];
          if (parsed && parsed.omAppImage && typeof parsed.omAppImage === "string" && parsed.omAppImage.startsWith("data:image")) {
            importedOmImage = parsed.omAppImage;
          }
        } catch(e) {}
      }

      // Check for photo contamination from another machine:
      // If targetMachine is specified, ensure imported image doesn't belong to a different machine
      const cleanTargetMach = (targetMachine || "").trim().toLowerCase();
      let isContaminatedImage = false;
      const fileImageMach = (data.omAppImageMachine || (data.bearing_tco_data && data.bearing_tco_data.omAppImageMachine) || "").trim().toLowerCase();
      if (fileImageMach && cleanTargetMach && fileImageMach !== cleanTargetMach) {
        isContaminatedImage = true;
      }

      // Also check if the image matches a photo with a conflicting machine name in its description/filename
      if (!isContaminatedImage && importedOmImage && cleanTargetMach && Array.isArray(importedFolders)) {
        for (const f of importedFolders) {
          if (f.photos && Array.isArray(f.photos)) {
            const pMatch = f.photos.find(p => p.dataUrl === importedOmImage);
            if (pMatch) {
              const pDesc = (pMatch.description || "").toLowerCase();
              const pFn = (pMatch.filename || "").toLowerCase();
              if ((pDesc.includes("bunker") || pFn.includes("bunker")) && !cleanTargetMach.includes("bunker")) {
                isContaminatedImage = true;
                break;
              }
            }
          }
        }
      }

      if (isContaminatedImage) {
        console.warn(`[TCO Photo] Contaminated machine photo detected for '${targetMachine}' (originated from '${fileImageMach || "bunkerband"}'). Resetting.`);
        importedOmImage = "";
      }

      // Safe fallback: ONLY if targetMachine is explicitly present and matches the photo's description or filename
      if (!importedOmImage && cleanTargetMach && Array.isArray(importedFolders)) {
        for (const f of importedFolders) {
          if (f.photos && Array.isArray(f.photos)) {
            const match = f.photos.find(p => {
              const desc = (p.description || "").toLowerCase();
              const fn = (p.filename || "").toLowerCase();
              return desc.includes(cleanTargetMach) || fn.includes(cleanTargetMach);
            });
            if (match && match.dataUrl) {
              importedOmImage = match.dataUrl;
              break;
            }
          }
        }
      }

      let importedChainOmImage = "";
      if (data.chainOmAppImage && typeof data.chainOmAppImage === "string" && data.chainOmAppImage.startsWith("data:image")) {
        importedChainOmImage = data.chainOmAppImage;
      } else if (data.chain_tco_data && data.chain_tco_data.chainOmAppImage && typeof data.chain_tco_data.chainOmAppImage === "string" && data.chain_tco_data.chainOmAppImage.startsWith("data:image")) {
        importedChainOmImage = data.chain_tco_data.chainOmAppImage;
      } else if (data.localStorage && data.localStorage["chain_tco_data"]) {
        try {
          const parsed = typeof data.localStorage["chain_tco_data"] === "string"
            ? JSON.parse(data.localStorage["chain_tco_data"])
            : data.localStorage["chain_tco_data"];
          if (parsed && parsed.chainOmAppImage && typeof parsed.chainOmAppImage === "string" && parsed.chainOmAppImage.startsWith("data:image")) {
            importedChainOmImage = parsed.chainOmAppImage;
          }
        } catch(e) {}
      }

      const fileChainImageMach = (data.chainOmAppImageMachine || (data.chain_tco_data && data.chain_tco_data.chainOmAppImageMachine) || "").trim().toLowerCase();
      if (fileChainImageMach && cleanTargetMach && fileChainImageMach !== cleanTargetMach) {
        importedChainOmImage = "";
      }

      if (typeof setBearingTcoImage === "function") {
        setBearingTcoImage(importedOmImage, targetMachine);
      } else {
        tcoUploadedImageBase64 = importedOmImage;
      }

      if (typeof setChainTcoImage === "function") {
        setChainTcoImage(importedChainOmImage, targetMachine);
      } else {
        chainTcoUploadedImageBase64 = importedChainOmImage;
      }

      // STEP 8: Restore inputs into DOM and localStorage WITH EVENT DISPATCHING
      if (data.inputs && typeof data.inputs === 'object') {
        Object.keys(data.inputs).forEach(id => {
          const val = data.inputs[id];
          try { localStorage.setItem("app_field_" + id, val); } catch(e) {}
          const el = document.getElementById(id);
          if (el) {
            if (el.type === "checkbox" || el.type === "radio") {
              el.checked = !!val;
            } else {
              el.value = (val !== null && val !== undefined) ? val : "";
            }
            try {
              el.dispatchEvent(new Event("input", { bubbles: true }));
              el.dispatchEvent(new Event("change", { bubbles: true }));
            } catch(e) {}
          }
        });
      }

      // STEP 9: Direct DOM assignments for master metadata fields to guarantee consistency
      const setValDirect = (id, val) => {
        const el = document.getElementById(id);
        if (el) {
          el.value = (val !== null && val !== undefined) ? val : "";
          try {
            el.dispatchEvent(new Event("input", { bubbles: true }));
            el.dispatchEvent(new Event("change", { bubbles: true }));
          } catch(e) {}
        }
      };
      const setTxtDirect = (id, txt) => {
        const el = document.getElementById(id);
        if (el) el.textContent = (txt !== null && txt !== undefined) ? txt : "";
      };

      setValDirect("techMachineInput", targetMachine);
      setValDirect("omTechMachine", targetMachine);
      setValDirect("chainOmTechMachine", targetMachine);
      setValDirect("techBrandInput", targetBrand);
      setValDirect("omTechBrand", targetBrand);
      setValDirect("chainOmTechBrand", targetBrand);
      setValDirect("techAppInput", targetApp);
      setValDirect("omTechApp", targetApp);
      setValDirect("chainOmTechApp", targetApp);
      setValDirect("techProductInput", targetProduct);
      setValDirect("omTechProduct", targetProduct);
      setValDirect("chainOmTechProduct", targetProduct);
      setTxtDirect("omProdName1", targetProduct || "Conventioneel Vet");
      setTxtDirect("chainOmProdName1", targetProduct || "Conventionele Kettingolie");

      const suffix = currentLang === "nl" ? " dagen" : currentLang === "fr" ? " jours" : " days";
      let formattedInterval = "";
      if (targetInterval !== null && targetInterval !== undefined && targetInterval !== "") {
        const iClean = String(targetInterval).replace(/[^0-9]/g, '');
        if (iClean) {
          formattedInterval = `${iClean}${suffix}`;
        } else {
          formattedInterval = String(targetInterval);
        }
      }
      setValDirect("techIntervalInput", targetInterval);
      setValDirect("omTechInterval", formattedInterval);
      setValDirect("chainOmTechInterval", formattedInterval);

      let formattedPrice = "";
      if (targetPrice !== null && targetPrice !== undefined && targetPrice !== "") {
        const pClean = String(targetPrice).replace(/[^0-9.,]/g, '').replace(',', '.');
        const pNum = parseFloat(pClean);
        if (!isNaN(pNum)) {
          formattedPrice = `€ ${pNum.toFixed(2)}`;
          setValDirect("omProdPrice1", pNum.toFixed(2));
          setValDirect("chainOmProdPrice1", pNum.toFixed(2));
        } else {
          formattedPrice = String(targetPrice);
        }
      }
      setValDirect("techPriceInput", targetPrice);
      setValDirect("omTechPrice", formattedPrice);
      setValDirect("chainOmTechPrice", formattedPrice);

      setValDirect("clientCompanyInput", targetCompany);
      setValDirect("omClientCompany", targetCompany);
      setValDirect("chainOmClientCompany", targetCompany);
      setValDirect("clientContactInput", targetContact);
      setValDirect("omClientContact", targetContact);
      setValDirect("chainOmClientContact", targetContact);
      setValDirect("clientPhoneInput", targetPhone);
      setValDirect("omClientPhone", targetPhone);
      setValDirect("chainOmClientPhone", targetPhone);
      setValDirect("clientEmailInput", targetEmail);
      setValDirect("omClientEmail", targetEmail);
      setValDirect("chainOmClientEmail", targetEmail);

      setValDirect("opNameInput", targetOpName);
      setValDirect("omOpName", targetOpName);
      setValDirect("chainOmOpName", targetOpName);
      setValDirect("opPhoneInput", targetOpPhone);
      setValDirect("omOpPhone", targetOpPhone);
      setValDirect("chainOmOpPhone", targetOpPhone);
      setValDirect("opEmailInput", targetOpEmail);
      setValDirect("omOpEmail", targetOpEmail);
      setValDirect("chainOmOpEmail", targetOpEmail);

      // Mark dossier import timestamp to protect against stale cross-tab broadcasts
      window.__lastDossierImportTime = Date.now();
      window.__activeDossierMachine = targetMachine;
      window.__activeDossierCompany = targetCompany;
      window.__isSyncingQuestionnaire = false;

      try {
        if (targetMachine) localStorage.setItem('interflon_active_dossier_machine', targetMachine);
        if (targetCompany) localStorage.setItem('interflon_active_dossier_company', targetCompany);
      } catch(e) {}

      // STEP 10: Activate questionnaire in calculator, dropdowns, and broadcast cross-tab
      if (importedQuestionnaire) {
        try {
          const qJson = JSON.stringify(importedQuestionnaire);
          localStorage.setItem('interflon_questionnaire_full_data', qJson);
          localStorage.setItem('interflon_last_questionnaire_data', qJson);
          if (targetMachine) localStorage.setItem('interflon_active_dossier_machine', targetMachine);
          if (targetCompany) localStorage.setItem('interflon_active_dossier_company', targetCompany);
          if (importedQuestionnaire.surveyRasterConfig) {
            localStorage.setItem('interflon_survey_raster_config', JSON.stringify(importedQuestionnaire.surveyRasterConfig));
          } else if (data.localStorage && data.localStorage.interflon_survey_raster_config) {
            const rawCfg = data.localStorage.interflon_survey_raster_config;
            localStorage.setItem('interflon_survey_raster_config', (typeof rawCfg === 'string') ? rawCfg : JSON.stringify(rawCfg));
          }
        } catch(e) {}

        window.latestSurveyFullData = importedQuestionnaire;
        const bList = Array.isArray(importedQuestionnaire.bearings) ? importedQuestionnaire.bearings : [];
        window.latestSurveyBearings = bList;

        const firstL = (bList.length > 0 && bList[0].letter) ? bList[0].letter : 'A';
        window.currentActiveSurveyBearingLetter = firstL;
        window.currentSurveyBearingLetter = firstL;
        window.activeTcoBearingSource = "survey_" + firstL;
        try {
          localStorage.setItem("interflon_active_survey_letter", firstL);
          localStorage.setItem("active_tco_bearing_source", "survey_" + firstL);
        } catch(e) {}

        if (typeof populateSurveyBearingsDropdown === "function") populateSurveyBearingsDropdown(bList);
        if (typeof populateOmSurveyBearingsDropdown === "function") populateOmSurveyBearingsDropdown(bList);
        if (typeof refreshSurveyBearingsList === "function") refreshSurveyBearingsList(false);
        if (typeof syncAllQuestionnaireDataToCalculator === "function") {
          syncAllQuestionnaireDataToCalculator(importedQuestionnaire, firstL);
        }
        if (typeof populateOmSurveyBearingsDropdown === "function") {
          populateOmSurveyBearingsDropdown(bList);
          populateOmSurveyBearingsDropdown(bList, 'chain');
        }

        const surveyWrapper = document.getElementById("surveyBearingSelectWrapper");
        if (surveyWrapper) surveyWrapper.style.display = bList.length > 0 ? "flex" : "none";

        if (typeof BroadcastChannel !== "undefined") {
          try {
            if (!window.__surveySyncBroadcastChannel) {
              window.__surveySyncBroadcastChannel = new BroadcastChannel('interflon_questionnaire_sync');
            }
            window.__surveySyncBroadcastChannel.postMessage({
              type: 'QUESTIONNAIRE_IMPORTED',
              data: importedQuestionnaire,
              fullData: importedQuestionnaire,
              bearings: bList,
              source: 'calculator_dossier_import'
            });
          } catch(e) {}
        }
      } else {
        window.latestSurveyFullData = null;
        window.latestSurveyBearings = [];
        try {
          localStorage.removeItem('interflon_questionnaire_full_data');
          localStorage.removeItem('interflon_last_questionnaire_data');
          localStorage.removeItem('interflon_survey_raster_config');
          localStorage.removeItem('interflon_raster_config');
        } catch(e) {}

        if (typeof populateSurveyBearingsDropdown === "function") populateSurveyBearingsDropdown([]);
        if (typeof populateOmSurveyBearingsDropdown === "function") populateOmSurveyBearingsDropdown([]);
        if (typeof refreshSurveyBearingsList === "function") refreshSurveyBearingsList(false);
        const surveyWrapper = document.getElementById("surveyBearingSelectWrapper");
        if (surveyWrapper) surveyWrapper.style.display = "none";

        if (typeof BroadcastChannel !== "undefined") {
          try {
            const syncChan = new BroadcastChannel('interflon_questionnaire_sync');
            syncChan.postMessage({ type: 'CLEAR_QUESTIONNAIRE', source: 'calculator_dossier_import' });
          } catch(e) {}
        }
      }

      // STEP 11: Explicitly reload all metadata in modals, topbar badges, and Opbrengstmodel columns
      if (typeof loadClientDetails === "function") loadClientDetails();
      if (typeof loadOperatorDetails === "function") loadOperatorDetails();
      if (typeof loadTechDetails === "function") loadTechDetails();
      if (typeof loadBearingTcoDetails === "function") loadBearingTcoDetails();
      if (typeof loadChainTcoDetails === "function") loadChainTcoDetails();
      if (typeof updateClientBadge === "function") updateClientBadge(targetCompany, targetContact);
      if (typeof updateTechBadge === "function") updateTechBadge(targetMachine, targetApp);
      if (typeof updateOperatorBadge === "function") updateOperatorBadge(targetOpName);
      if (typeof updateOmMetadata === "function") updateOmMetadata();
      if (typeof renderPhotoFolderTabs === "function") renderPhotoFolderTabs();
      if (typeof renderPhotoGrid === "function") renderPhotoGrid();
      if (typeof updatePhotoBadgeCounter === "function") updatePhotoBadgeCounter();

      // STEP 12: Display selected bearing if restored
      if (window.currentSelectedBearing && typeof displayBearingData === "function") {
        displayBearingData(window.currentSelectedBearing);
      }

      // STEP 13: Trigger all recalculations
      if (typeof calculateGrease === "function") calculateGrease();
      if (typeof calculateBearing === "function") calculateBearing();
      if (typeof calculateTco === "function") calculateTco();
      if (typeof updateOmKpiSummaryCards === "function") updateOmKpiSummaryCards();
      if (typeof renderAutoDevicesUI === "function") renderAutoDevicesUI();
      if (typeof calculateAutomationLubrication === "function") calculateAutomationLubrication();
      if (typeof updateRoiAutomationPage === "function") updateRoiAutomationPage();
      if (typeof calculateChain === "function") calculateChain();
      if (typeof calculateChainTco === "function") calculateChainTco();

      const displayName = targetMachine || targetCompany || "";
      const msg = isEnglish
        ? (displayName ? `Yield model for '${displayName}' successfully imported!` : "Yield model successfully imported!")
        : (displayName ? `Opbrengstmodel voor '${displayName}' succesvol geïmporteerd!` : "Opbrengstmodel succesvol geïmporteerd!");

      showToastNotification(msg);
    } catch (err) {
      console.error("Import error:", err);
      showToastNotification("Fout bij inlezen van bestand.", true);
    } finally {
      try {
        if (event && event.target) {
          event.target.value = "";
        }
      } catch(e) {}
    }
  };
  reader.readAsText(file);
}


