let twinInfoHoverTimer = null;

function clearTwinInfoHoverTimer() {
  if (twinInfoHoverTimer) {
    clearTimeout(twinInfoHoverTimer);
    twinInfoHoverTimer = null;
  }
}

function updateTwinInfoBtnState(activeMetric) {
  document.querySelectorAll(".twin-info-icon-btn").forEach(btn => {
    const metric = btn.getAttribute("data-twin-metric");
    if (activeMetric && metric === activeMetric) {
      btn.classList.add("active");
    } else {
      btn.classList.remove("active");
    }
  });
}

function showTwinMetricInfo(metricKey, event) {
  clearTwinInfoHoverTimer();
  if (twinInfoPinned && twinInfoPinned !== metricKey) return;

  const popover = document.getElementById("twinInfoPopover");
  const titleEl = document.getElementById("twinInfoPopoverTitle");
  const bodyEl = document.getElementById("twinInfoPopoverBody");
  if (!popover || !titleEl || !bodyEl) return;

  const data = twinMetricExplanations[metricKey];
  if (!data) return;

  titleEl.innerHTML = data.title;
  bodyEl.innerHTML = data.content;

  // Make visible before measuring to get accurate DOM layout height
  popover.style.display = "block";

  let btn = null;
  if (event && (event.currentTarget || event.target)) {
    const target = event.currentTarget || event.target;
    btn = target.closest ? target.closest(".twin-info-icon-btn") : target;
  }
  if (!btn) {
    btn = document.querySelector(`.twin-info-icon-btn[data-twin-metric="${metricKey}"]`);
  }

  if (btn && btn.getBoundingClientRect) {
    const rect = btn.getBoundingClientRect();
    const popoverWidth = 350;
    const popoverHeight = popover.offsetHeight || 350;

    // Position popover cleanly to the LEFT of the telemetry sidebar
    let left = rect.left - popoverWidth - 14;
    let top = rect.top - 12;

    if (left >= 12) {
      // Comfortable space in viewport/canvas zone to the left of the button
      if (top + popoverHeight > window.innerHeight - 16) {
        top = window.innerHeight - popoverHeight - 16;
      }
      if (top < 16) top = 16;
    } else {
      // Narrow viewport fallback: place above or below with guaranteed non-overlapping clearance
      left = Math.max(12, Math.min(window.innerWidth - popoverWidth - 12, rect.right - popoverWidth));
      if (rect.top - popoverHeight - 14 >= 12) {
        top = rect.top - popoverHeight - 14;
      } else {
        top = rect.bottom + 14;
      }
    }

    popover.style.left = Math.round(left) + "px";
    popover.style.top = Math.round(top) + "px";
  }

  if (twinInfoPinned === metricKey) {
    updateTwinInfoBtnState(metricKey);
  }
}

function hideTwinMetricInfo(metricKey, event, force = false) {
  if (force) {
    clearTwinInfoHoverTimer();
    twinInfoPinned = null;
    updateTwinInfoBtnState(null);
    const popover = document.getElementById("twinInfoPopover");
    if (popover) popover.style.display = "none";
    return;
  }

  if (twinInfoPinned) return; // Pinned state stays open until explicit unpin/close

  clearTwinInfoHoverTimer();
  twinInfoHoverTimer = setTimeout(() => {
    const popover = document.getElementById("twinInfoPopover");
    if (popover) popover.style.display = "none";
    updateTwinInfoBtnState(null);
  }, 150);
}

function toggleTwinMetricInfo(metricKey, event) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  clearTwinInfoHoverTimer();

  if (twinInfoPinned === metricKey) {
    // Already pinned on this metric -> close and unpin
    hideTwinMetricInfo(metricKey, event, true);
  } else {
    // Pin this metric
    twinInfoPinned = metricKey;
    showTwinMetricInfo(metricKey, event);
    updateTwinInfoBtnState(metricKey);
  }
}

// Global click listener to close popover when clicking outside
document.addEventListener("click", function(e) {
  const popover = document.getElementById("twinInfoPopover");
  if (popover && popover.style.display !== "none") {
    if (!popover.contains(e.target) && !e.target.closest(".twin-info-icon-btn")) {
      hideTwinMetricInfo(null, null, true);
    }
  }
});

// Global escape key listener to close popover
document.addEventListener("keydown", function(e) {
  if (e.key === "Escape") {
    const popover = document.getElementById("twinInfoPopover");
    if (popover && popover.style.display !== "none") {
      hideTwinMetricInfo(null, null, true);
    }
  }
});

function openDigitalTwinModal() {
  const modal = document.getElementById("digitalTwinModal");
  if (!modal) return;

  hideTwinMetricInfo(null, null, true);

  // Sync with current bearing data
  const data = getActiveBearingDataForTwin();
  twinSimState.rpm = data.rpm;
  twinSimState.annualSavings = data.savings;

  const bearingTitleEl = document.getElementById("twinBearingInfoTitle");
  if (bearingTitleEl) bearingTitleEl.textContent = data.bearingName;

  const greaseNameEl = document.getElementById("twinGreaseNameText");
  if (greaseNameEl) greaseNameEl.textContent = data.greaseName;

  const rpmSlider = document.getElementById("twinRpmSlider");
  const rpmDisplay = document.getElementById("twinRpmDisplay");
  if (rpmSlider) {
    if (twinSimState.rpm < parseInt(rpmSlider.min, 10)) {
      rpmSlider.min = Math.max(1, Math.floor(twinSimState.rpm / 10) * 10);
    }
    if (twinSimState.rpm > parseInt(rpmSlider.max, 10)) {
      rpmSlider.max = Math.ceil(twinSimState.rpm / 500) * 500;
    }
    rpmSlider.value = twinSimState.rpm;
  }
  if (rpmDisplay) rpmDisplay.textContent = twinSimState.rpm + " RPM";

  const savingsEl = document.getElementById("twinSavingsAmount");
  if (savingsEl) savingsEl.textContent = formatTwinEuro(twinSimState.annualSavings);

  modal.classList.remove("hidden");
  document.body.style.overflow = "hidden";
  twinSimState.isOpen = true;
  twinSimState.isPlaying = true;

  // Initialize Three.js if first time
  // Initialize Three.js and Graph
  if (!twinInitialized) {
    setTimeout(function() {
      initDigitalTwin3D();
      initDigitalTwinGraph();
      onTwinWindowResize();
      renderTwinTelemetryGraph();
      if (!twinAnimFrameId) animateDigitalTwin();
    }, 50);
  } else {
    setTimeout(function() {
      initDigitalTwinGraph();
      onTwinWindowResize();
      renderTwinTelemetryGraph();
      if (!twinAnimFrameId) animateDigitalTwin();
    }, 50);
  }
}

function closeDigitalTwinModal() {
  hideTwinMetricInfo(null, null, true);
  const modal = document.getElementById("digitalTwinModal");
  if (modal) modal.classList.add("hidden");
  document.body.style.overflow = "";
  twinSimState.isOpen = false;

  if (twinAnimFrameId) {
    cancelAnimationFrame(twinAnimFrameId);
    twinAnimFrameId = null;
  }
}

function onTwinWindowResize() {
  if (twinRenderer && twinCamera) {
    const container = document.getElementById("digitalTwinCanvasContainer");
    if (container && container.offsetParent !== null) {
      const width = container.clientWidth || 800;
      const height = container.clientHeight || 500;
      twinCamera.aspect = width / height;
      twinCamera.updateProjectionMatrix();
      twinRenderer.setSize(width, height, false);
    }
  }
  renderTwinTelemetryGraph();
}

function setTwinViewMode(mode) {
  twinSimState.viewMode = mode;
  const btnSplit = document.getElementById("btnTwinViewSplit");
  const btn3D = document.getElementById("btnTwinView3D");
  const btnGraph = document.getElementById("btnTwinViewGraph");
  [btnSplit, btn3D, btnGraph].forEach(b => { if (b) b.classList.remove("active"); });
  if (mode === "split" && btnSplit) btnSplit.classList.add("active");
  if (mode === "3d" && btn3D) btn3D.classList.add("active");
  if (mode === "graph" && btnGraph) btnGraph.classList.add("active");

  const canvasBox = document.getElementById("digitalTwinCanvasContainer");
  const graphBox = document.getElementById("digitalTwinGraphContainer");
  const divider = document.getElementById("twinStageDivider");

  if (mode === "split") {
    if (canvasBox) { canvasBox.style.display = "block"; canvasBox.style.flex = "1 1 50%"; }
    if (graphBox) { graphBox.style.display = "flex"; graphBox.style.flex = "1 1 50%"; }
    if (divider) divider.style.display = "block";
  } else if (mode === "3d") {
    if (canvasBox) { canvasBox.style.display = "block"; canvasBox.style.flex = "1 1 100%"; }
    if (graphBox) { graphBox.style.display = "none"; }
    if (divider) divider.style.display = "none";
  } else if (mode === "graph") {
    if (canvasBox) { canvasBox.style.display = "none"; }
    if (graphBox) { graphBox.style.display = "flex"; graphBox.style.flex = "1 1 100%"; }
    if (divider) divider.style.display = "none";
  }

  setTimeout(function() {
    onTwinWindowResize();
    renderTwinTelemetryGraph();
  }, 40);
}

function setTwinGraphFilter(filterKey) {
  twinSimState.graphFilter = filterKey;
  const filterIds = {
    all: "btnGraphFilterAll",
    friction: "btnGraphFilterFriction",
    temp: "btnGraphFilterTemp",
    wear: "btnGraphFilterWear",
    film: "btnGraphFilterFilm"
  };
  Object.keys(filterIds).forEach(k => {
    const el = document.getElementById(filterIds[k]);
    if (el) {
      if (k === filterKey) el.classList.add("active");
      else el.classList.remove("active");
    }
  });
  renderTwinTelemetryGraph();
}

let twinGraphInitialized = false;

function initDigitalTwinGraph() {
  const wrap = document.getElementById("digitalTwinGraphCanvasWrap");
  const canvas = document.getElementById("digitalTwinGraphCanvas");
  if (!wrap || !canvas) return;

  if (twinGraphInitialized) return;
  twinGraphInitialized = true;

  let isDragging = false;

  function handleScrub(e) {
    const rect = canvas.getBoundingClientRect();
    const padL = 48;
    const padR = 24;
    const plotW = rect.width - padL - padR;
    if (plotW <= 0) return;
    const clientX = e.clientX !== undefined ? e.clientX : (e.touches && e.touches[0] && e.touches[0].clientX);
    if (clientX === undefined) return;
    const x = clientX - rect.left - padL;
    const day = Math.max(0, Math.min(60, (x / plotW) * 60));

    if (twinSimState.mode === "manual") {
      const cycleDuration = 30;
      twinSimState.simTime = (day / 60) * cycleDuration;
    }
    renderTwinTelemetryGraph();
  }

  function handleHover(e) {
    const tooltip = document.getElementById("twinGraphTooltip");
    if (!tooltip) return;
    const rect = canvas.getBoundingClientRect();
    const padL = 48;
    const padR = 24;
    const padT = 32;
    const padB = 26;
    const plotW = rect.width - padL - padR;
    const plotH = rect.height - padT - padB;
    if (plotW <= 0) return;

    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    if (mouseX < padL || mouseX > rect.width - padR || mouseY < padT || mouseY > rect.height - padB) {
      tooltip.style.display = "none";
      twinSimState.graphHoverDay = null;
      return;
    }

    const day = Math.max(0, Math.min(60, ((mouseX - padL) / plotW) * 60));
    twinSimState.graphHoverDay = day;

    const curRpm = (twinSimState && twinSimState.rpm) ? twinSimState.rpm : 1450;
    const m = getTwinMetricsAtDay(day, curRpm);
    const pb = m.phaseBoundaries || { p1End: 4, p2End: 22, p3End: 42 };

    let phaseName = "Fase 1: Overvulling";
    let phaseColor = "#a3e635";
    if (day > pb.p3End) {
      phaseName = "Fase 4: Droogloop / Alarm";
      phaseColor = "#ef4444";
    } else if (day > pb.p2End) {
      phaseName = "Fase 3: Grenssmering";
      phaseColor = "#f59e0b";
    } else if (day > pb.p1End) {
      phaseName = "Fase 2: Optimaal venster";
      phaseColor = "#34d399";
    }

    tooltip.style.display = "block";
    tooltip.style.left = mouseX + "px";
    tooltip.style.top = Math.max(10, mouseY - 8) + "px";
    tooltip.innerHTML = `
      <div style="font-weight: 800; color: ${phaseColor}; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 3px; margin-bottom: 4px;">
        Dag ${Math.round(day)} • ${phaseName}
      </div>
      <div style="display: grid; grid-template-columns: auto auto; gap: 3px 10px; font-size: 10px;">
        <span style="color: #38bdf8;">⚡ Wrijving (μ):</span><strong style="text-align: right; color: #fff;">${m.friction.toFixed(4)}</strong>
        <span style="color: #f59e0b;">🌡️ Bedrijfstemp.:</span><strong style="text-align: right; color: #fff;">${m.temp.toFixed(1)} °C</strong>
        <span style="color: #ef4444;">⚙️ Slijtage:</span><strong style="text-align: right; color: #fff;">${m.wear.toFixed(1)} μm</strong>
        <span style="color: #10b981;">🛡️ Smeerfilm:</span><strong style="text-align: right; color: #fff;">${Math.round(m.film * 100)}%</strong>
      </div>
      <div style="font-size: 9px; color: #94a3b8; margin-top: 4px; text-align: center;"><em>Klik om hierheen te springen</em></div>
    `;
  }

  wrap.addEventListener("mousedown", function(e) {
    isDragging = true;
    handleScrub(e);
  });
  window.addEventListener("mousemove", function(e) {
    if (isDragging) handleScrub(e);
  });
  window.addEventListener("mouseup", function() {
    isDragging = false;
  });
  wrap.addEventListener("mousemove", handleHover);
  wrap.addEventListener("mouseleave", function() {
    const tooltip = document.getElementById("twinGraphTooltip");
    if (tooltip) tooltip.style.display = "none";
    twinSimState.graphHoverDay = null;
  });

  wrap.addEventListener("touchstart", function(e) {
    isDragging = true;
    handleScrub(e);
  }, { passive: true });
  window.addEventListener("touchmove", function(e) {
    if (isDragging) handleScrub(e);
  }, { passive: true });
  window.addEventListener("touchend", function() {
    isDragging = false;
  });
}

function getTwinMetricsAtDay(day, customRpm) {
  const rpm = (typeof customRpm === "number" && customRpm > 0)
    ? customRpm
    : (typeof twinSimState !== "undefined" && twinSimState.rpm ? twinSimState.rpm : 1450);

  // Snelheidsverhouding t.o.v. standaard industriële referentie (1450 RPM)
  const speedRatio = Math.max(0.1, Math.min(4.5, rpm / 1450));

  // SKF Vetlevensduur & degradatiefactor: hogere toerentallen verkorten het effectieve vetinterval (tf ~ 1/n)
  // Bij 3000 RPM (speedRatio ~ 2.07) treedt uitdroging veel sneller op.
  // Bij 500 RPM (speedRatio ~ 0.34) blijft de film veel langer behouden.
  const phaseScale = Math.pow(1 / speedRatio, 0.55);

  // Dynamische fasegrenzen in dagen (op 1450 RPM: 4d, 22d, 42d, 60d)
  const p1End = Math.max(1.5, Math.min(8.0, 4.0 * Math.pow(speedRatio, 0.3)));
  const p2End = Math.max(p1End + 3.0, Math.min(50.0, p1End + 18.0 * phaseScale));
  const p3End = Math.max(p2End + 4.0, Math.min(58.0, p2End + 20.0 * phaseScale));

  // Thermische basisschaal: bij hoger toerental levert schuifwrijving meer warmte op
  const tempOffset = (speedRatio - 1.0) * 16.0;

  let friction, temp, wear, film, life;

  if (day <= p1End) {
    // Fase 1: Overvulling / Churning
    const churnFric = 0.022 * Math.pow(speedRatio, 0.35);
    friction = churnFric;
    const peakOffset = (p1End - Math.abs(day - (p1End * 0.5))) * 1.5;
    temp = Math.max(40.0, 68.0 + tempOffset * 1.15 + peakOffset);
    wear = 0.0;
    film = 1.0;
    life = 1.0;
  } else if (day <= p2End) {
    // Fase 2: Optimaal venster
    const t = (day - p1End) / Math.max(0.1, (p2End - p1End));
    friction = (0.006 + t * 0.005) * Math.pow(speedRatio, 0.15);
    temp = Math.max(32.0, 48.0 + tempOffset + t * 3.0);
    wear = 0.0;
    film = 0.95 - t * 0.15;
    life = (1.2 - t * 0.2) * Math.pow(phaseScale, 0.3);
  } else if (day <= p3End) {
    // Fase 3: Grenssmering / Filmverdunning
    const t = (day - p2End) / Math.max(0.1, (p3End - p2End));
    friction = (0.011 + t * 0.030) * Math.pow(speedRatio, 0.22);
    temp = Math.max(38.0, (48.0 + tempOffset + 3.0) + t * (16.0 + (speedRatio - 1.0) * 5.0));
    // Slijtage volgens Archard (cumulatief aantal omwentelingen)
    wear = t * 0.4 * speedRatio;
    film = 0.80 - t * 0.55;
    life = Math.max(0.4, (1.0 - t * 0.4) * Math.pow(phaseScale, 0.4));
  } else {
    // Fase 4: Droogloop & Metaalcontact
    const t = (day - p3End) / Math.max(0.1, (60.0 - p3End));
    friction = (0.041 + t * 0.045) * Math.pow(speedRatio, 0.25);
    temp = Math.max(45.0, (67.0 + tempOffset * 1.25) + t * (20.0 + (speedRatio - 1.0) * 8.0));
    // Exponentiële cumulatieve slijtage bij droogloop
    const baseWear = 0.4 * speedRatio;
    const dryRunWear = (t * 1.6 + Math.pow(t, 2) * 1.2) * Math.pow(speedRatio, 1.25);
    wear = baseWear + dryRunWear;
    film = Math.max(0.02, (0.25 - t * 0.22));
    life = Math.max(0.2, (0.6 - t * 0.3) * Math.pow(phaseScale, 0.5));
  }

  return { friction, temp, wear, film, life, phaseBoundaries: { p1End, p2End, p3End } };
}

function renderTwinTelemetryGraph() {
  const canvas = document.getElementById("digitalTwinGraphCanvas");
  if (!canvas || !twinSimState.isOpen) return;

  const rect = canvas.getBoundingClientRect();
  const w = rect.width;
  const h = rect.height;
  if (w <= 0 || h <= 0) return;

  const dpr = window.devicePixelRatio || 1;
  if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
  }

  const ctx = canvas.getContext("2d");
  ctx.save();
  ctx.scale(dpr, dpr);

  // Clear Background
  ctx.fillStyle = "#080d1a";
  ctx.fillRect(0, 0, w, h);

  const padL = 48;
  const padR = 24;
  const padT = 32;
  const padB = 26;
  const plotW = Math.max(10, w - padL - padR);
  const plotH = Math.max(10, h - padT - padB);

  function getX(day) {
    return padL + (day / 60) * plotW;
  }

  const curRpm = (twinSimState && twinSimState.rpm) ? twinSimState.rpm : 1450;
  const speedRatio = Math.max(0.1, Math.min(4.5, curRpm / 1450));
  const isAuto = (twinSimState && twinSimState.mode === "auto");
  const showAll = (twinSimState && twinSimState.graphFilter === "all");

  // Current simulation day
  const cycleDuration = 30;
  const cycleTime = (twinSimState.simTime) % cycleDuration;
  const currentDay = (!isAuto) ? (cycleTime / cycleDuration) * 60 : 0;

  const curMetricsNow = getTwinMetricsAtDay(currentDay, curRpm);
  const pb = curMetricsNow.phaseBoundaries || { p1End: 4, p2End: 22, p3End: 42 };

  // 1. Phase Background Bands (dynamisch meeschalend met RPM)
  const phases = [
    { start: 0, end: pb.p1End, color: "rgba(132, 204, 22, 0.09)", stroke: "rgba(132, 204, 22, 0.3)", title: "F1: Overvulling", shortTitle: "F1", textColor: "#a3e635" },
    { start: pb.p1End, end: pb.p2End, color: "rgba(16, 185, 129, 0.08)", stroke: "rgba(16, 185, 129, 0.3)", title: "F2: Optimaal venster", shortTitle: "F2", textColor: "#34d399" },
    { start: pb.p2End, end: pb.p3End, color: "rgba(245, 158, 11, 0.08)", stroke: "rgba(245, 158, 11, 0.3)", title: "F3: Grenssmering", shortTitle: "F3", textColor: "#fbbf24" },
    { start: pb.p3End, end: 60, color: "rgba(239, 68, 68, 0.11)", stroke: "rgba(239, 68, 68, 0.3)", title: "F4: Droogloop / Slijtage", shortTitle: "F4", textColor: "#f87171" }
  ];

  phases.forEach(p => {
    const x1 = getX(p.start);
    const x2 = getX(p.end);
    const pw = x2 - x1;

    ctx.fillStyle = p.color;
    ctx.fillRect(x1, padT, pw, plotH);

    if (p.end < 60) {
      ctx.beginPath();
      ctx.setLineDash([3, 3]);
      ctx.strokeStyle = p.stroke;
      ctx.lineWidth = 1;
      ctx.moveTo(x2, padT);
      ctx.lineTo(x2, padT + plotH);
      ctx.stroke();
      ctx.setLineDash([]);
    }

    // Phase header labels are ONLY shown in manual mode (in automatic mode, there are no degradation phases!)
    if (!isAuto) {
      const label = (pw > 70 ? p.title : (pw > 30 ? p.shortTitle : ""));
      if (label) {
        ctx.font = "800 9.5px 'Outfit', sans-serif";
        ctx.fillStyle = p.textColor;
        ctx.textAlign = "center";
        ctx.fillText(label, x1 + pw / 2, padT - 8);
      }
    }
  });

  // 2. Horizontal Grid & Y-Axis Labels
  ctx.setLineDash([2, 4]);
  ctx.strokeStyle = "rgba(255, 255, 255, 0.08)";
  ctx.lineWidth = 1;
  const yTicks = [0, 0.25, 0.5, 0.75, 1.0];
  yTicks.forEach(val => {
    const y = padT + plotH * (1 - val);
    ctx.beginPath();
    ctx.moveTo(padL, y);
    ctx.lineTo(padL + plotW, y);
    ctx.stroke();

    ctx.font = "700 8.5px monospace";
    ctx.fillStyle = "rgba(148, 163, 184, 0.7)";
    ctx.textAlign = "right";

    if (twinSimState.graphFilter === "friction") {
      const uVal = 0.002 + val * (0.100 - 0.002);
      ctx.fillText(uVal.toFixed(3) + "μ", padL - 5, y + 3);
    } else if (twinSimState.graphFilter === "temp") {
      const tVal = 25 + val * 95;
      ctx.fillText(Math.round(tVal) + "°C", padL - 5, y + 3);
    } else if (twinSimState.graphFilter === "wear") {
      const wVal = val * 6.0;
      ctx.fillText(wVal.toFixed(1) + "μm", padL - 5, y + 3);
    } else if (twinSimState.graphFilter === "film") {
      ctx.fillText(Math.round(val * 100) + "%", padL - 5, y + 3);
    } else {
      ctx.fillText(Math.round(val * 100) + "%", padL - 5, y + 3);
    }
  });
  ctx.setLineDash([]);

  // 3. Time Grid (X-Axis)
  for (let d = 0; d <= 60; d += 10) {
    const x = getX(d);
    ctx.beginPath();
    ctx.strokeStyle = "rgba(255, 255, 255, 0.06)";
    ctx.moveTo(x, padT);
    ctx.lineTo(x, padT + plotH);
    ctx.stroke();

    ctx.font = "700 9px monospace";
    ctx.fillStyle = "#64748b";
    ctx.textAlign = "center";
    ctx.fillText(d + "d", x, padT + plotH + 15);
  }

  // 4. Draw Curves
  const numSteps = 120;
  const stepSize = 60 / numSteps;

  function getY(norm) {
    const clamped = Math.max(0, Math.min(1, norm));
    return padT + plotH * (1 - clamped);
  }

  function normFriction(u) { return (u - 0.002) / (0.100 - 0.002); }
  function normTemp(t) { return (t - 25) / 95; }
  function normWear(w) { return w / 6.0; }
  function normFilm(f) { return f; }

  if (isAuto) {
    let autoNorm = normFilm(0.98);
    let autoLabel = "✨ Continu 100% EHL Smeerfilm • 0 Slijtage";
    if (twinSimState.graphFilter === "temp") {
      const autoTemp = 39.0 + (speedRatio - 1.0) * 10.0;
      autoNorm = normTemp(autoTemp);
      autoLabel = `✨ Continu stabiel ${Math.round(autoTemp)}°C (Geen oververhitting)`;
    } else if (twinSimState.graphFilter === "wear") {
      autoNorm = normWear(0.0);
      autoLabel = "✨ Continu 0,0 μm Slijtage (Geen slijtage)";
    } else if (twinSimState.graphFilter === "friction") {
      const autoFric = 0.0028 * Math.pow(speedRatio, 0.12);
      autoNorm = normFriction(autoFric);
      autoLabel = `✨ Minimale wrijving (${autoFric.toFixed(4)}μ)`;
    }

    // Top header label in automatische modus (boven de grafiek waar in manuele modus de fasekoppen staan)
    ctx.font = "800 10.5px 'Outfit', sans-serif";
    ctx.fillStyle = "#34d399";
    ctx.textAlign = "left";
    ctx.fillText(autoLabel, padL + 6, padT - 8);

    // Reference dashed manual curve for comparison
    let refNormFn = m => normFilm(m.film);
    if (twinSimState.graphFilter === "temp") refNormFn = m => normTemp(m.temp);
    else if (twinSimState.graphFilter === "wear") refNormFn = m => normWear(m.wear);
    else if (twinSimState.graphFilter === "friction") refNormFn = m => normFriction(m.friction);

    ctx.beginPath();
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = "rgba(239, 68, 68, 0.4)";
    ctx.lineWidth = 1.5;
    for (let i = 0; i <= numSteps; i++) {
      const d = i * stepSize;
      const m = getTwinMetricsAtDay(d, curRpm);
      const x = getX(d);
      const y = getY(refNormFn(m));
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // Solid steady Green Micpol® Line
    const autoY = getY(autoNorm);
    ctx.shadowColor = "#10b981";
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.strokeStyle = "#10b981";
    ctx.lineWidth = 3;
    ctx.moveTo(padL, autoY);
    ctx.lineTo(padL + plotW, autoY);
    ctx.stroke();
    ctx.shadowBlur = 0;

  } else {
    // MANUAL MODE: Draw 4 Curves
    const curvesToDraw = [];

    if (showAll || twinSimState.graphFilter === "film") {
      curvesToDraw.push({
        key: "film",
        color: "#10b981",
        normFn: m => normFilm(m.film),
        label: "🛡️ Film & L10h",
        valFn: m => Math.round(m.film * 100) + "%"
      });
    }
    if (showAll || twinSimState.graphFilter === "friction") {
      curvesToDraw.push({
        key: "friction",
        color: "#38bdf8",
        normFn: m => normFriction(m.friction),
        label: "⚡ Wrijving",
        valFn: m => m.friction.toFixed(3) + "μ"
      });
    }
    if (showAll || twinSimState.graphFilter === "temp") {
      curvesToDraw.push({
        key: "temp",
        color: "#f59e0b",
        normFn: m => normTemp(m.temp),
        label: "🌡️ Temp",
        valFn: m => Math.round(m.temp) + "°C"
      });
    }
    if (showAll || twinSimState.graphFilter === "wear") {
      curvesToDraw.push({
        key: "wear",
        color: "#ef4444",
        normFn: m => normWear(m.wear),
        label: "⚙️ Slijtage",
        valFn: m => m.wear.toFixed(1) + "μm"
      });
    }

    curvesToDraw.forEach(curve => {
      ctx.beginPath();
      for (let i = 0; i <= numSteps; i++) {
        const d = i * stepSize;
        const m = getTwinMetricsAtDay(d, curRpm);
        const x = getX(d);
        const y = getY(curve.normFn(m));
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }

      ctx.shadowColor = curve.color;
      ctx.shadowBlur = showAll ? 6 : 12;
      ctx.strokeStyle = curve.color;
      ctx.lineWidth = showAll ? 2.2 : 3.2;
      ctx.stroke();
      ctx.shadowBlur = 0;

      if (!showAll) {
        ctx.lineTo(getX(60), padT + plotH);
        ctx.lineTo(getX(0), padT + plotH);
        ctx.closePath();
        const grad = ctx.createLinearGradient(0, padT, 0, padT + plotH);
        grad.addColorStop(0, curve.color.replace(")", ", 0.25)").replace("rgb", "rgba"));
        grad.addColorStop(1, "rgba(0,0,0,0)");
        ctx.fillStyle = grad;
        ctx.fill();
      }
    });

    // 5. MOVING TIME TRACKER LINE & ARROW ("bewegende lijn of pijl")
    const curX = getX(currentDay);
    const curMetrics = getTwinMetricsAtDay(currentDay, curRpm);

    // Glowing vertical needle
    ctx.shadowColor = "#38bdf8";
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.strokeStyle = "#38bdf8";
    ctx.lineWidth = 2.2;
    ctx.moveTo(curX, padT - 4);
    ctx.lineTo(curX, padT + plotH);
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Needle top arrow head & badge
    const badgeW = 60;
    const badgeH = 18;
    const badgeX = Math.max(padL, Math.min(padL + plotW - badgeW, curX - badgeW / 2));
    const badgeY = padT - 22;

    ctx.beginPath();
    ctx.fillStyle = "#0284c7";
    ctx.moveTo(curX - 5, badgeY + badgeH);
    ctx.lineTo(curX + 5, badgeY + badgeH);
    ctx.lineTo(curX, badgeY + badgeH + 5);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = "#0369a1";
    ctx.strokeStyle = "#38bdf8";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(badgeX, badgeY, badgeW, badgeH, 4) : ctx.rect(badgeX, badgeY, badgeW, badgeH);
    ctx.fill();
    ctx.stroke();

    ctx.font = "800 10px 'Outfit', sans-serif";
    ctx.fillStyle = "#ffffff";
    ctx.textAlign = "center";
    ctx.fillText("Dag " + Math.round(currentDay), badgeX + badgeW / 2, badgeY + 12);

    // Intersection dots on active curves
    curvesToDraw.forEach(curve => {
      const dotY = getY(curve.normFn(curMetrics));

      ctx.beginPath();
      ctx.arc(curX, dotY, 4.5, 0, Math.PI * 2);
      ctx.fillStyle = curve.color;
      ctx.shadowColor = curve.color;
      ctx.shadowBlur = 8;
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.beginPath();
      ctx.arc(curX, dotY, 2, 0, Math.PI * 2);
      ctx.fillStyle = "#ffffff";
      ctx.fill();

      if (!showAll) {
        ctx.font = "800 10.5px monospace";
        ctx.fillStyle = curve.color;
        ctx.textAlign = (curX > padL + plotW - 70) ? "right" : "left";
        const tagX = (curX > padL + plotW - 70) ? curX - 10 : curX + 10;
        ctx.fillText(curve.valFn(curMetrics), tagX, dotY + 4);
      }
    });
  }

  // Update day indicator in footer
  const dayIndEl = document.getElementById("twinGraphDayIndicator");
  const footerHintEl = document.getElementById("twinGraphFooterHint");
  if (isAuto) {
    if (dayIndEl) dayIndEl.innerHTML = "<span style='color: #10b981;'>Continu 100%</span>";
    if (footerHintEl) footerHintEl.innerHTML = "✨ <em style='color: #34d399;'>Continu micro-gedoseerd • Geen zaagtandverval</em>";
  } else {
    if (dayIndEl) dayIndEl.innerHTML = "Dag " + Math.round(currentDay) + " / 60";
    if (footerHintEl) footerHintEl.innerHTML = "💡 <em>Klik of sleep op de tijdlijn om direct naar een dag te springen</em>";
  }

  ctx.restore();
}

function setTwinCameraView(viewName) {
  if (!twinCamera) return;

  // Update active button classes
  const btns = ["btnTwinCam3d", "btnTwinCamFront", "btnTwinCamSide", "btnTwinCamTop"];
  btns.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.classList.remove("active");
  });

  const activeMap = {
    perspective: "btnTwinCam3d",
    front: "btnTwinCamFront",
    side: "btnTwinCamSide",
    top: "btnTwinCamTop"
  };
  const activeBtn = document.getElementById(activeMap[viewName]);
  if (activeBtn) activeBtn.classList.add("active");

  if (viewName === "perspective") {
    twinCamera.position.set(7.5, 5.0, 8.5);
  } else if (viewName === "front") {
    twinCamera.position.set(0, 0, 11.5);
  } else if (viewName === "side") {
    twinCamera.position.set(11.5, 0, 0);
  } else if (viewName === "top") {
    twinCamera.position.set(0, 12.0, 0.01);
  }
  twinCamera.lookAt(0, 0, 0);

  if (twinControls) {
    twinControls.target.set(0, 0, 0);
    twinControls.update();
  }
}

function resetTwinCamera() {
  setTwinCameraView("perspective");
}

function toggleTwinCutout() {
  twinSimState.cutaway = !twinSimState.cutaway;
  rebuildBearingGeometry();
}

function toggleTwinPlay() {
  twinSimState.isPlaying = !twinSimState.isPlaying;
  const iconEl = document.getElementById("twinPlayPauseIcon");
  const textEl = document.getElementById("twinPlayPauseText");
  if (iconEl && textEl) {
    if (twinSimState.isPlaying) {
      iconEl.textContent = "⏸️";
      textEl.textContent = "Live";
    } else {
      iconEl.textContent = "▶️";
      textEl.textContent = "Pauze";
    }
  }
}

function setDigitalTwinMode(mode) {
  twinSimState.mode = mode;
  const btnAuto = document.getElementById("btnTwinModeAuto");
  const btnManual = document.getElementById("btnTwinModeManual");
  if (btnAuto && btnManual) {
    if (mode === "auto") {
      btnAuto.classList.add("active");
      btnManual.classList.remove("active");
      twinSimState.filmHealth = 1.0;
      twinSimState.wearUm = 0.0;
      twinSimState.lifetimeFactor = 3.8;
    } else {
      btnAuto.classList.remove("active");
      btnManual.classList.add("active");
      twinSimState.simTime = 0;
    }
  }
}

function setTwinSimSpeed(speed) {
  twinSimState.simSpeed = speed;
  const speedIds = [
    { speed: 1, id: "btnTwinSpeed1" },
    { speed: 5, id: "btnTwinSpeed5" },
    { speed: 20, id: "btnTwinSpeed20" },
    { speed: 60, id: "btnTwinSpeed60" }
  ];
  speedIds.forEach(item => {
    const el = document.getElementById(item.id);
    if (el) {
      if (item.speed === speed) el.classList.add("active");
      else el.classList.remove("active");
    }
  });
}

function onTwinRpmChange(val) {
  const rpm = Math.max(50, Math.min(6000, parseInt(val, 10) || 1450));
  twinSimState.rpm = rpm;
  const disp = document.getElementById("twinRpmDisplay");
  if (disp) disp.textContent = rpm + " RPM";

  const slider = document.getElementById("twinRpmSlider");
  if (slider && parseInt(slider.value, 10) !== rpm) {
    slider.value = rpm;
  }

  // Houd ook de titel in het infoblok synchroon als deze (XXX RPM) bevat
  const titleEl = document.getElementById("twinBearingInfoTitle");
  if (titleEl && titleEl.textContent) {
    if (/\(\d+\s*RPM\)/i.test(titleEl.textContent)) {
      titleEl.textContent = titleEl.textContent.replace(/\(\d+\s*RPM\)/i, `(${rpm} RPM)`);
    }
  }

  // Update de fysica en telemetrie direct voor het huidige frame zodat de badges live mee veranderen
  if (typeof updateTwinSimulationPhysics === "function") {
    updateTwinSimulationPhysics(0);
  }

  // Herteken de grafiek onmiddellijk zodat de curven en fasen live vloeiend meebewegen
  if (typeof renderTwinTelemetryGraph === "function") {
    renderTwinTelemetryGraph();
  }
}

function triggerDigitalTwinPulse() {
  twinSimState.injectionPulseActive = true;
  twinSimState.injectionPulseTimer = 1.2;
  twinSimState.filmHealth = 1.0;

  if (twinSimState.mode === "manual") {
    // Reset manual cycle back to freshly lubricated Day 0
    twinSimState.simTime = 0;
  }

  // Flash pulse overlay on 3D canvas
  const overlay = document.getElementById("twinInjectionPulseOverlay");
  if (overlay) {
    overlay.style.opacity = "0.85";
    setTimeout(function() {
      overlay.style.opacity = "0";
    }, 450);
  }

  // Toast notification
  if (typeof showToastNotification === "function") {
    showToastNotification("💉 Verse Interflon Micpol® vetinjectie toegediend! Smeerfilm 100% hersteld.");
  }
}


/* ==========================================================================
   AI EXECUTIVE SUMMARY & DIRECTIEVOORSTEL GENERATOR
   Ondersteunt technische dienst en adviseur bij management- en directieaanvragen
   ========================================================================== */

let currentProposalTemplate = "formal"; // "formal" | "email" | "advisor" | "esg"

function formatProposalCount(n) {
  if (n === null || n === undefined || isNaN(n)) return "0";
  const num = typeof n === "number" ? n : parseFloat(String(n).replace(",", "."));
  if (isNaN(num)) return "0";
  if (Math.abs(num - Math.round(num)) < 0.05) {
    return Math.round(num).toString();
  }
  return (Math.round(num * 10) / 10).toString().replace(".", ",");
}

function getExecutiveProposalData() {
  if (typeof updateRoiAutomationPage === "function") {
    try {
      updateRoiAutomationPage();
    } catch (_) {}
  }

  // Machine name
  let machineName = "Installatie";
  const mInput = document.getElementById("techMachineInput") || document.getElementById("clientMachineInput") || document.getElementById("omMachineName") || document.getElementById("machineNameInput");
  if (mInput && mInput.value && mInput.value.trim()) {
    machineName = mInput.value.trim();
  } else {
    try {
      const saved = localStorage.getItem("tech_machine") || localStorage.getItem("app_field_techMachineInput") || localStorage.getItem("selectedMachineName");
      if (saved && saved.trim()) machineName = saved.trim();
    } catch (_) {}
  }

  // Client company
  let clientCompany = "Klantbedrijf";
  const cInput = document.getElementById("clientCompanyInput") || document.getElementById("clientContactInput") || document.getElementById("omClientContact");
  if (cInput && cInput.value && cInput.value.trim()) {
    clientCompany = cInput.value.trim();
  } else {
    try {
      const saved = localStorage.getItem("client_company") || localStorage.getItem("app_field_clientCompanyInput") || localStorage.getItem("selectedClientContact");
      if (saved && saved.trim()) clientCompany = saved.trim();
    } catch (_) {}
  }

  // Grease
  let greaseName = "Interflon Grease MP2/3 (met Micpol®)";
  const gSelect = document.getElementById("inputGrease");
  if (gSelect && gSelect.value) {
    greaseName = typeof formatGreaseDisplayName === "function" ? formatGreaseDisplayName(gSelect.value) : gSelect.value;
  }

  // Parse financials & ROI
  let investment = 0;
  let annualSavings = 0;
  let paybackMonthsStr = "Direct Rendabel";
  let manualHours = 52;
  let manualRounds = 52;
  let totalBeurten = 52;
  let effectiveBearings = 1;
  let manualHoursStr = "52";
  let numUnits = 1;
  let totalPoints = 1;
  let systemType = "Pulsarlube M2 (elektromechanisch)";

  // Parse devices count & lubrication points dynamically
  try {
    const deviceSelect = document.getElementById("automationDeviceSelect") || document.getElementById("autoDeviceSelect");
    const deviceKey = deviceSelect ? deviceSelect.value : ((typeof window !== "undefined" && window.selectedAutoDevice) || "pulsarlube_m2");
    const isSinglePoint = (deviceKey === "single_point");

    if (isSinglePoint) {
      systemType = "Interflon Single Point Lubricator (elektrochemisch)";
      const activeSpGroups = (typeof autoDevicesState !== "undefined" && Array.isArray(autoDevicesState))
        ? autoDevicesState.filter(d => d && d.isSinglePointGroup && (d.unitCount > 0 || (d.bearingLetters && d.bearingLetters.length > 0)))
        : [];
      if (activeSpGroups.length > 0) {
        numUnits = activeSpGroups.reduce((sum, g) => sum + (g.unitCount || (g.bearingLetters ? g.bearingLetters.length : 1)), 0);
        totalPoints = numUnits;
      } else {
        const spInput = document.getElementById("singlePointNumBearingsInput") || document.getElementById("spNumBearingsInput");
        const valFromDom = spInput ? parseInt(spInput.value, 10) : NaN;
        const count = (!isNaN(valFromDom) && valFromDom > 0) ? valFromDom : ((typeof window !== "undefined" && window.spNumBearingsValue) ? window.spNumBearingsValue : 1);
        numUnits = count;
        totalPoints = count;
      }
    } else {
      const numDevs = typeof getActiveNumDevices === "function" ? getActiveNumDevices() : 1;
      numUnits = numDevs;
      let ptsSum = 0;
      if (typeof autoDevicesState !== "undefined" && Array.isArray(autoDevicesState)) {
        for (let i = 0; i < numDevs; i++) {
          const d = autoDevicesState[i];
          ptsSum += (d && d.points ? (parseInt(d.points, 10) || 1) : 1);
        }
      }
      totalPoints = ptsSum > 0 ? ptsSum : numDevs;

      if (deviceKey === "pulsarlube_msp_ac") systemType = "Pulsarlube MSP AC (extern gevoed AC / synchroon)";
      else if (deviceKey === "pulsarlube_msp_dc" || deviceKey === "pulsarlube_msp") systemType = "Pulsarlube MSP DC (extern gevoed DC / synchroon)";
      else if (deviceKey === "pulsarlube_plc") systemType = "Pulsarlube PLC (volledig geïntegreerd)";
      else systemType = "Pulsarlube M2 (elektromechanisch)";
    }

    // Check of er lagers in de vragenlijst gedefinieerd zijn
    const qBearings = (typeof getQuestionnaireBearings === 'function') ? getQuestionnaireBearings() : [];
    if (qBearings && qBearings.length > 0 && totalPoints < qBearings.length) {
      totalPoints = qBearings.length;
    }
  } catch (_) {}

  function parseEuroVal(el) {
    if (!el || !el.textContent) return 0;
    const match = el.textContent.match(/[\d.,]+/);
    if (!match) return 0;
    const clean = match[0].replace(/\./g, "").replace(",", ".");
    const val = parseFloat(clean);
    return isNaN(val) ? 0 : val;
  }

  const yr1El = document.getElementById("roiAutoYear1Total");
  const recEl = document.getElementById("roiAutoRecurringTotal");
  const savEl = document.getElementById("roiNetYearlySaving");
  const payEl = document.getElementById("roiPaybackPeriod");

  const yr1Total = parseEuroVal(yr1El);
  const recTotal = parseEuroVal(recEl);
  investment = yr1Total > recTotal ? (yr1Total - recTotal) : yr1Total;
  annualSavings = parseEuroVal(savEl);

  if (investment <= 0 && yr1Total > 0) investment = yr1Total;
  if (annualSavings <= 0) annualSavings = 8450; // Realistische fallback

  if (payEl && payEl.textContent) {
    paybackMonthsStr = payEl.textContent.trim().split("(")[0].trim();
  } else if (investment > 0 && annualSavings > 0) {
    const m = (investment / annualSavings) * 12;
    paybackMonthsStr = m.toFixed(1).replace(".", ",") + " maanden";
  }

  // 1. Direct from window.__latestRoiData
  const roiData = (typeof window !== "undefined" && window.__latestRoiData) ? window.__latestRoiData : null;
  if (roiData) {
    if (typeof roiData.manualBeurtenPerYear === "number" && !isNaN(roiData.manualBeurtenPerYear) && roiData.manualBeurtenPerYear > 0) {
      manualRounds = roiData.manualBeurtenPerYear;
    }
    if (typeof roiData.effectiveManBearings === "number" && !isNaN(roiData.effectiveManBearings) && roiData.effectiveManBearings > 0) {
      effectiveBearings = roiData.effectiveManBearings;
    }
    if (typeof roiData.totalLagerBeurten === "number" && !isNaN(roiData.totalLagerBeurten) && roiData.totalLagerBeurten > 0) {
      totalBeurten = roiData.totalLagerBeurten;
    } else {
      totalBeurten = manualRounds * effectiveBearings;
    }
    if (typeof roiData.manualLaborHours === "number" && !isNaN(roiData.manualLaborHours) && roiData.manualLaborHours >= 0) {
      manualHours = roiData.manualLaborHours;
    }
  }

  // 2. DOM extraction fallback from #roiManBeurten and #roiManWorkTime
  const beurtenEl = document.getElementById("roiManBeurten");
  if (beurtenEl && beurtenEl.textContent) {
    const txt = beurtenEl.textContent.trim();
    const matchMulti = txt.match(/([\d.,]+)\s*\(([\d.,]+)\s*beurten\s*x\s*(\d+)\s*lagers\)/i);
    if (matchMulti) {
      totalBeurten = parseFloat(matchMulti[1].replace(/\./g, "").replace(",", "."));
      manualRounds = parseFloat(matchMulti[2].replace(/\./g, "").replace(",", "."));
      effectiveBearings = parseInt(matchMulti[3], 10);
    } else {
      const matchSingle = txt.match(/([\d.,]+)\s*beurten/i);
      if (matchSingle) {
        manualRounds = parseFloat(matchSingle[1].replace(/\./g, "").replace(",", "."));
        effectiveBearings = 1;
        totalBeurten = manualRounds;
      }
    }
  }

  const workTimeEl = document.getElementById("roiManWorkTime");
  if (workTimeEl && workTimeEl.textContent) {
    const matchHours = workTimeEl.textContent.match(/\(([\d.,]+)\s*u\/jaar\)/i);
    if (matchHours) {
      manualHours = parseFloat(matchHours[1].replace(/\./g, "").replace(",", "."));
    }
  }

  // 3. Opbrengstmodel frequency fallback if still 52
  if (manualRounds === 52) {
    const selMode = (document.getElementById("roiManualModeSelect") && document.getElementById("roiManualModeSelect").value) || "interflon";
    const freqElId = (selMode === "huidig") ? "omProdFreq1" : "omProdFreq2";
    const chainFreqElId = (selMode === "huidig") ? "chainOmProdFreq1" : "chainOmProdFreq2";
    const curFreqInput = document.getElementById(freqElId) || document.getElementById(chainFreqElId) || document.getElementById("tcoFreqCurrentInput");
    if (curFreqInput && !isNaN(parseFloat(curFreqInput.value)) && parseFloat(curFreqInput.value) > 0) {
      manualRounds = parseFloat(curFreqInput.value);
      totalBeurten = manualRounds * effectiveBearings;
    }
  }

  // Format manualHoursStr cleanly in Dutch
  if (typeof manualHours === "number") {
    if (manualHours < 10 && Math.abs(manualHours - Math.round(manualHours)) >= 0.05) {
      manualHoursStr = manualHours.toFixed(1).replace(".", ",");
    } else {
      manualHoursStr = Math.round(manualHours).toString();
    }
  } else {
    manualHoursStr = String(manualHours).replace(".", ",");
  }

  return {
    machineName,
    clientCompany,
    greaseName,
    investment,
    annualSavings,
    paybackMonthsStr,
    manualRounds,
    totalBeurten,
    effectiveBearings,
    manualHours,
    manualHoursStr,
    numUnits,
    totalPoints,
    systemType,
    dateStr: new Date().toLocaleDateString("nl-BE")
  };
}

function generateExecutiveProposalText(templateType) {
  const d = getExecutiveProposalData();
  const unitText = d.numUnits === 1 ? "1 automatisch Interflon precisiesmeertoestel" : `${d.numUnits} automatische Interflon precisiesmeertoestellen`;
  const pointsText = d.totalPoints === 1 ? "1 smeerpunt" : `${d.totalPoints} smeerpunten`;

  const roundsText = (d.effectiveBearings > 1)
    ? `${formatProposalCount(d.manualRounds)} handmatige smeerrondes (${formatProposalCount(d.totalBeurten)} lagersmeerbeurten, ${d.manualHoursStr} uur/jaar)`
    : `${formatProposalCount(d.manualRounds)} handmatige smeerbeurten (${d.manualHoursStr} uur/jaar)`;

  return `ONDERWERP: Investeringsvoorstel: Automatisering smering ${d.machineName} (Terugverdientijd: ${d.paybackMonthsStr})

Beste directie / management,

Om de bedrijfszekerheid van installatie "${d.machineName}" te verhogen en ongeplande stilstand te voorkomen, stellen wij voor om de smering te automatiseren met ${unitText} (${pointsText}), uitgerust met hoogwaardig ${d.greaseName}.

Financiële kerncijfers & Business Case:
• Investering (hardware): ${formatTwinEuro(d.investment)}
• Jaarlijkse netto besparing:       ${formatTwinEuro(d.annualSavings)} / jaar
• Verwachte terugverdientijd:        ${d.paybackMonthsStr}!
• Netto financieel voordeel na 3 jaar: ${formatTwinEuro(d.annualSavings * 3 - d.investment)}

Belangrijkste operationele & technische voordelen:
1. Arbeidswinst: ${roundsText} geëlimineerd.
2. Arbeidsveiligheid: Geen technici meer in gevaarlijke zones rond draaiende delen (100% veilig).
3. Langere levensduur: Continue micro-smering met Interflon Micpol® verlengt de lagerlevensduur met 50 tot 300%.
4. Geen zaagtand-effect: Sluit periodieke overvulling en hongerloop uit; lagers draaien continu optimaal.
5. Duurzaamheid & Compliance: 100% PFAS- en microplastic-vrij met drastische reductie van vetverbruik en afval (ISO 14001).
6. Voorspelbaarheid: Geen ad-hoc revisies meer; de smering verloopt volledig autonoom en betrouwbaar.

De gedetailleerde technische berekening, lageranalyses en de offerte zijn als bijlage toegevoegd ter goedkeuring.

Graag jullie akkoord om deze bestelling in gang te zetten.

Met vriendelijke groet,

Technische Dienst / Onderhoudsafdeling
${d.clientCompany}`;
}

function openExecutiveProposalModal() {
  const modal = document.getElementById("executiveProposalModal");
  if (!modal) return;

  const d = getExecutiveProposalData();

  // Populate KPI bar
  const kpiMach = document.getElementById("propKpiMachine");
  const kpiComp = document.getElementById("propKpiCompany");
  const kpiInv = document.getElementById("propKpiInvestment");
  const kpiSav = document.getElementById("propKpiSavings");
  const kpiPay = document.getElementById("propKpiPayback");
  const kpiSafe = document.getElementById("propKpiSafety");
  const docDate = document.getElementById("propDocDate");

  if (kpiMach) kpiMach.textContent = d.machineName;
  if (kpiComp) kpiComp.textContent = d.clientCompany;
  if (kpiInv) kpiInv.textContent = formatTwinEuro(d.investment);
  if (kpiSav) kpiSav.textContent = formatTwinEuro(d.annualSavings) + " / jr";
  if (kpiPay) kpiPay.textContent = d.paybackMonthsStr;
  if (kpiSafe) {
    if (d.effectiveBearings > 1) {
      kpiSafe.textContent = `${formatProposalCount(d.totalBeurten)} beurten / jr (${formatProposalCount(d.manualRounds)} rondes)`;
    } else {
      kpiSafe.textContent = `${formatProposalCount(d.manualRounds)} beurten / jr`;
    }
  }
  if (docDate) docDate.textContent = "Datum: " + d.dateStr;

  // Vul tekstveld met het voorstel
  const textEl = document.getElementById("executiveProposalText");
  if (textEl) {
    textEl.value = generateExecutiveProposalText();
  }

  modal.classList.remove("hidden");
  document.body.style.overflow = "hidden";
}

function closeExecutiveProposalModal() {
  const modal = document.getElementById("executiveProposalModal");
  if (modal) modal.classList.add("hidden");
  document.body.style.overflow = "";
}

function switchExecutiveProposalTab(tabName) {
  currentProposalTemplate = tabName;

  const tabs = [
    { id: "tabPropFormal", name: "formal" },
    { id: "tabPropEmail", name: "email" },
    { id: "tabPropAdvisor", name: "advisor" },
    { id: "tabPropEsg", name: "esg" }
  ];

  tabs.forEach(t => {
    const btn = document.getElementById(t.id);
    if (btn) {
      if (t.name === tabName) btn.classList.add("active");
      else btn.classList.remove("active");
    }
  });

  const textEl = document.getElementById("executiveProposalText");
  if (textEl) {
    textEl.value = generateExecutiveProposalText(tabName);
  }
}

function copyExecutiveProposalText() {
  const textEl = document.getElementById("executiveProposalText");
  const text = textEl ? textEl.value : generateExecutiveProposalText(currentProposalTemplate);

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToastNotification === "function") {
        showToastNotification("✓ Directievoorstel gekopieerd naar klembord!");
      }
    }).catch(() => {
      fallbackCopyProposal(text);
    });
  } else {
    fallbackCopyProposal(text);
  }
}

function fallbackCopyProposal(text) {
  const ta = document.createElement("textarea");
  ta.value = text;
  document.body.appendChild(ta);
  ta.select();
  document.execCommand("copy");
  document.body.removeChild(ta);
  if (typeof showToastNotification === "function") {
    showToastNotification("✓ Directievoorstel gekopieerd naar klembord!");
  }
}

function getProposalSubjectAndBody() {
  const textEl = document.getElementById("executiveProposalText");
  const fullText = textEl && textEl.value.trim() ? textEl.value : generateExecutiveProposalText();
  const d = getExecutiveProposalData();

  let subject = "Investeringsvoorstel: Automatisering smering " + (d.machineName || "Machine");
  let bodyLines = [];
  const lines = fullText.split("\n");
  let skippedSubject = false;

  for (let l of lines) {
    if (!skippedSubject && (l.startsWith("BETREFT:") || l.startsWith("ONDERWERP:"))) {
      subject = l.replace(/^(BETREFT:|ONDERWERP:)/, "").trim();
      skippedSubject = true;
    } else {
      bodyLines.push(l);
    }
  }

  while (bodyLines.length > 0 && !bodyLines[0].trim()) {
    bodyLines.shift();
  }

  const cleanBody = bodyLines.join("\n").trim();
  return { subject, body: cleanBody, fullText };
}

function openProposalInGmail() {
  const { subject, body, fullText } = getProposalSubjectAndBody();

  // 1. Kopieer de tekst naar het klembord
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(fullText).catch(() => {});
  }

  // 2. Open Gmail rechtstreeks via de officiële compose link
  const gmailUrl = "https://mail.google.com/mail/?view=cm&fs=1&su=" + encodeURIComponent(subject) + "&body=" + encodeURIComponent(body);
  const win = window.open(gmailUrl, "_blank");

  if (!win || win.closed || typeof win.closed === "undefined") {
    const a = document.createElement("a");
    a.href = gmailUrl;
    a.target = "_blank";
    a.rel = "noopener noreferrer";
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { if (document.body.contains(a)) document.body.removeChild(a); }, 500);
  }

  if (typeof showToastNotification === "function") {
    showToastNotification("✉️ Gmail geopend! ⚠️ Vergeet niet het PDF-rapport en/of de offerte toe te voegen.");
  }
}

function openProposalInOutlook() {
  const { subject, body, fullText } = getProposalSubjectAndBody();

  // 1. Kopieer de tekst naar het klembord
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(fullText).catch(() => {});
  }

  // 2. Open Outlook via protocol handler
  const mailtoUrl = "mailto:?subject=" + encodeURIComponent(subject) + "&body=" + encodeURIComponent(body);
  const a = document.createElement("a");
  a.href = mailtoUrl;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { if (document.body.contains(a)) document.body.removeChild(a); }, 500);

  if (typeof showToastNotification === "function") {
    showToastNotification("📧 Outlook / E-mail geopend! ⚠️ Vergeet niet het PDF-rapport en/of de offerte toe te voegen.");
  }
}

function emailExecutiveProposal() {
  openProposalInGmail();
}

function downloadExecutiveProposal() {
  const textEl = document.getElementById("executiveProposalText");
  const text = textEl ? textEl.value : generateExecutiveProposalText(currentProposalTemplate);
  const d = getExecutiveProposalData();

  const filename = "Directievoorstel_Smeerautomatisering_" + d.machineName.replace(/[^a-zA-Z0-9_-]/g, "_") + ".txt";
  const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  if (typeof showToastNotification === "function") {
    showToastNotification("✓ Directievoorstel gedownload als " + filename);
  }
}

