// Auto-run chain calculation & initialize photo library on init
document.addEventListener("DOMContentLoaded", function() {
  if (typeof loadPhotoLibrary === "function") {
    loadPhotoLibrary();
  }
  if (typeof loadAutomationStateFromLocalStorage === "function") {
    loadAutomationStateFromLocalStorage();
  }
  setTimeout(function() {
    if (typeof CHAINS_DB !== "undefined" && Array.isArray(CHAINS_DB) && CHAINS_DB.length > 0 && !activeChain) {
      activeChain = CHAINS_DB[3] || CHAINS_DB[0];
    }
    if (typeof calculateChainGrease === "function") {
      calculateChainGrease();
    }
    const bearings = (typeof getQuestionnaireBearings === "function") ? getQuestionnaireBearings() : [];
    if (bearings && bearings.length > 0) {
      if (typeof populateSurveyBearingsDropdown === "function") populateSurveyBearingsDropdown(bearings);
      if (typeof populateOmSurveyBearingsDropdown === "function") populateOmSurveyBearingsDropdown(bearings);
    }

    // Automatisering state is al betrouwbaar hersteld uit localStorage via loadAutomationStateFromLocalStorage().
    // We renderen en berekenen de herstelde status direct, zonder een automatische her-import uit de vragenlijst te forceren.
    if (typeof renderAutoDevicesUI === "function") renderAutoDevicesUI();
    if (typeof calculateAutomationLubrication === "function") calculateAutomationLubrication();

    if (typeof syncAllQuestionnaireDataToCalculator === "function") {
      syncAllQuestionnaireDataToCalculator();
    }
    if (typeof calculateTco === "function") {
      calculateTco();
    }
    if (typeof updateRoiAutomationPage === "function") {
      updateRoiAutomationPage();
    }
    if (typeof updateCorrectionFactorsHint === "function") {
      updateCorrectionFactorsHint();
    }
  }, 150);
});